if (!function_exists('category_feature_langs')) {
    // The shop languages whose 🛒 وضعیت قابلیت های فروشگاه has 🗂 دسته بندی on.
    // It is a per-language switch now (shop_feature_value); the old shop-wide
    // statuscategorygenral column only answers for a language that never set
    // its own, so reading that column alone asked for a category while it was
    // off, or not while it was on.
    function category_feature_langs()
    {
        $setting = select("setting", "*", null, null, "select");
        $on = [];
        foreach (panel_langs() as $l) {
            if (shop_feature_value('categroygenral', $l, $setting['statuscategorygenral'] ?? '') === 'oncategorys') {
                $on[] = $l;
            }
        }
        return $on;
    }
    // Why a product cannot be given a category right now - categories are off
    // in every language, or none exist yet - as the text to show; null when it
    // can. The path in the text is built from the menu's own button labels.
    function category_pick_blocker($textbotlang)
    {
        $t = $textbotlang['Admin']['Product'];
        $k = $textbotlang['keyboard'];
        if (empty(category_feature_langs())) {
            return strtr($t['categoryOffAlert'], ['{shop}' => $k['shopSettings'], '{status}' => $k['shopFeatureStatus'], '{category}' => $k['categoryBug']]);
        }
        if (intval(select("category", "*", null, null, "count")) === 0) {
            return strtr($t['categoryNoneAlert'], ['{shop}' => $k['shopSettings'], '{manage}' => $k['manageCategory'], '{add}' => $k['addCategory']]);
        }
        return null;
    }
}
if (!function_exists('shop_feature_lang_map')) {
    // 🛒 وضعیت قابلیت‌های فروشگاه, per language. Each of its 11 toggles used to
    // be one shop-wide flag (a `setting` column or a `shopSetting` row); this is
    // the per-language override sitting on top of that, so a shop can show
    // English customers a different set of buy-flow features than Persian ones.
    //
    // Shape: {featureKey: {lang: "onX"/"offX" - the SAME literal the feature has
    // always stored}}. A language with no entry here still reads whatever the
    // old global column/row says - the whole point being that nothing changes
    // for any language until an admin explicitly overrides one, so this needed
    // no migration script and no new default to invent per feature.
    function shop_feature_lang_map($fresh = false)
    {
        static $cache = null;
        if ($cache !== null && !$fresh) {
            return $cache;
        }
        $setting = select("setting", "*", null, null, "select");
        $m = json_decode((string) ($setting['shop_feature_lang'] ?? ''), true);
        return $cache = is_array($m) ? $m : [];
    }
    // $globalValue is whatever the caller already read from the old column/row
    // for this feature - the exact fallback for every language without an
    // override, so a shop that never touches this screen keeps behaving exactly
    // as it did before this existed.
    function shop_feature_value($featureKey, $lang, $globalValue)
    {
        $m = shop_feature_lang_map();
        if (isset($m[$featureKey][$lang]) && $m[$featureKey][$lang] !== '') {
            return $m[$featureKey][$lang];
        }
        // same rule as feature_value(): an unset language follows Persian, the
        // language this shop actually configures, rather than the shop-wide
        // column that predates per-language settings entirely
        if ($lang !== 'fa' && isset($m[$featureKey]['fa']) && $m[$featureKey]['fa'] !== '') {
            return $m[$featureKey]['fa'];
        }
        return $globalValue;
    }
    function shop_feature_set($featureKey, $lang, $value)
    {
        $m = shop_feature_lang_map(true);
        if (!isset($m[$featureKey]) || !is_array($m[$featureKey])) {
            $m[$featureKey] = [];
        }
        $m[$featureKey][$lang] = $value;
        update("setting", "shop_feature_lang", json_encode($m, JSON_UNESCAPED_UNICODE), null, null);
        shop_feature_lang_map(true);
    }
}
if (!function_exists('feature_setting_map')) {
    // Per-language overrides for the VALUES behind 🌐 وضعیت قابلیت‌ها (هر زبان)'s
    // ⚙️ تنظیمات sub-screens (affiliate percent, wheel prize, location limits,
    // ...) - separate column from feature_lang because that one holds the
    // on/off flags themselves.
    //
    // NOTE: unlike feature_value(), there is deliberately NO fallback to
    // Persian here, only to the global column. These are amounts, and each
    // language has its own currency (currency_for_lang): inheriting Persian's
    // wheel prize or affiliate gift would read a toman figure as dollars.
    // phone_prefix is the same shape of hazard - English defaults to "any
    // country" on purpose, and inheriting Persian's would force Iranian
    // numbers on it. Do not "fix" this into a Persian fallback.
    function feature_setting_map($fresh = false)
    {
        static $cache = null;
        if ($cache !== null && !$fresh) {
            return $cache;
        }
        $setting = select("setting", "*", null, null, "select");
        $m = json_decode((string) ($setting['feature_lang_settings'] ?? ''), true);
        return $cache = is_array($m) ? $m : [];
    }
    // $globalValue is whatever the caller already read from the old column/row,
    // so a language nobody has overridden keeps behaving exactly as before.
    function feature_setting_value($key, $lang, $globalValue)
    {
        $m = feature_setting_map();
        $v = $m[$key][$lang] ?? null;
        return ($v === null || $v === '') ? $globalValue : $v;
    }
    function feature_setting_set($key, $lang, $value)
    {
        $m = feature_setting_map(true);
        if (!isset($m[$key]) || !is_array($m[$key])) {
            $m[$key] = [];
        }
        $m[$key][$lang] = $value;
        update("setting", "feature_lang_settings", json_encode($m, JSON_UNESCAPED_UNICODE), null, null);
        feature_setting_map(true);
    }
}
if (!function_exists('phone_prefixes_for_lang')) {
    // Each language's OWN country dial code - never Iran's for everyone, which
    // is what the fixed 989xxxxxxxxx check used to enforce on every market.
    // English is deliberately unrestricted: it is a language, not a country.
    function phone_prefix_defaults()
    {
        return ['fa' => '98', 'en' => ''];
    }
    // Which dial codes a number may start with, for ONE language. Stored per
    // language (feature_lang_settings key "phone_prefix") as a comma list of
    // digits. An empty list means "any country" - that is the honest default
    // for a language with no single country behind it.
    function phone_prefixes_for_lang($lang)
    {
        $defaults = phone_prefix_defaults();
        $raw = (string) feature_setting_value('phone_prefix', $lang, $defaults[$lang] ?? '');
        $out = [];
        foreach (explode(',', $raw) as $p) {
            $p = preg_replace('/\D+/', '', (string) $p);
            // "0" is the stored sentinel for "no country restriction" - an
            // empty string cannot be used, feature_setting_value() reads that
            // as "never set" and falls back to the default
            if ($p !== '' && $p !== '0') {
                $out[] = $p;
            }
        }
        return $out;
    }
    // The countries 🌐 وضعیت قابلیت‌ها (هر زبان) → 📞 offers as one-tap buttons,
    // code => [flag, Persian name]; any other code can still be typed in.
    function phone_country_choices()
    {
        return [
            '98' => ['🇮🇷', 'ایران'], '1' => ['🇺🇸', 'آمریکا و کانادا'], '44' => ['🇬🇧', 'انگلیس'],
            '49' => ['🇩🇪', 'آلمان'], '90' => ['🇹🇷', 'ترکیه'], '971' => ['🇦🇪', 'امارات'],
            '7' => ['🇷🇺', 'روسیه'], '964' => ['🇮🇶', 'عراق'], '93' => ['🇦🇫', 'افغانستان'],
            '86' => ['🇨🇳', 'چین'], '31' => ['🇳🇱', 'هلند'], '33' => ['🇫🇷', 'فرانسه'],
        ];
    }
    // one language's list written back; an empty list means every country
    function phone_prefixes_set($lang, array $codes)
    {
        $clean = [];
        foreach ($codes as $c) {
            $c = preg_replace('/\D+/', '', (string) $c);
            if ($c !== '' && $c !== '0' && !in_array($c, $clean, true)) {
                $clean[] = $c;
            }
        }
        feature_setting_set('phone_prefix', $lang, $clean ? implode(',', $clean) : '0');
    }
    // Telegram hands contact numbers over without a "+", so a prefix test is
    // enough - and it is the only shape that generalises past one fixed country.
    function phone_matches_lang($phone, $lang)
    {
        $digits = preg_replace('/\D+/', '', (string) $phone);
        if ($digits === '') {
            return false;
        }
        $prefixes = phone_prefixes_for_lang($lang);
        if (!$prefixes) {
            // no country configured for this language: any real number passes
            return strlen($digits) >= 7;
        }
        foreach ($prefixes as $prefix) {
            if (strpos($digits, $prefix) === 0 && strlen($digits) >= strlen($prefix) + 6) {
                return true;
            }
        }
        return false;
    }
}
if (!function_exists('app_rows_for_lang')) {
    // app-download rows visible to one language, using the same lang-column
    // convention as the marzban_panel query in keyboard.php: a row with no
    // language (or 'all') belongs to every language, so every row that existed
    // before app.lang was added stays visible exactly as before.
    function app_rows_for_lang($lang)
    {
        global $pdo;
        $stmt = $pdo->prepare("SELECT * FROM app WHERE FIND_IN_SET(:userlang, lang) OR lang = 'all' OR lang IS NULL OR lang = ''");
        $stmt->bindValue(':userlang', (string) $lang);
        $stmt->execute();
        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }
}
if (!function_exists('score_on')) {
    // 🎲 points and the nightly lottery, per language - 🌐 وضعیت قابلیت‌ها (هر
    // زبان), falling back to the bot-wide switch they used to be
    function score_on($lang, $setting = null)
    {
        if (!is_array($setting)) {
            $setting = select("setting", "*", null, null, "select");
        }
        return intval(feature_value('scorestatus', $lang ?: 'fa', (string) ($setting['scorestatus'] ?? '0'))) === 1;
    }
    // [first, second, third] prize of one language's lottery
    function lottery_prizes_for_lang($lang)
    {
        $setting = select("setting", "*", null, null, "select");
        $m = json_decode((string) feature_setting_value('lottery_prize', $lang, (string) ($setting['Lottery_prize'] ?? '')), true);
        $m = is_array($m) ? $m : [];
        return [(string) ($m['one'] ?? '0'), (string) ($m['tow'] ?? '0'), (string) ($m['theree'] ?? '0')];
    }
    function lottery_prize_set($lang, $rank, $amount)
    {
        $p = lottery_prizes_for_lang($lang);
        $p[max(1, min(3, (int) $rank)) - 1] = (string) $amount;
        feature_setting_set('lottery_prize', $lang, json_encode(['one' => $p[0], 'tow' => $p[1], 'theree' => $p[2]]));
    }
    // 🔲 glass (inline) main menu, per language
    function glass_on($lang, $setting = null)
    {
        if (!is_array($setting)) {
            $setting = select("setting", "*", null, null, "select");
        }
        return feature_value('inlinebtnmain', $lang ?: 'fa', (string) ($setting['inlinebtnmain'] ?? 'offinline')) === 'oninline';
    }
    // the users one language's lottery draws from: another tab's language its
    // own; Persian everyone else (no language yet, or one without a tab)
    function lottery_lang_where($lang)
    {
        if ($lang !== 'fa') {
            return ["lang = ?", [$lang]];
        }
        $others = array_values(array_diff(panel_langs(), ['fa']));
        if (empty($others)) {
            return ["1 = 1", []];
        }
        return ["(lang IS NULL OR lang = '' OR lang NOT IN (" . implode(',', array_fill(0, count($others), '?')) . "))", $others];
    }
    // 🎲 the nightly draw, one per language that has it on: that language's
    // three highest scores win that language's prizes, told in their own
    // language, and that language's points start again. One Persian report
    // for the admins, a section per language.
    function lottery_run_nightly()
    {
        global $pdo;
        $setting = select("setting", "*", null, null, "select");
        if (!is_array($setting)) {
            return;
        }
        $panel = panel_texts();
        $report = '';
        foreach (panel_langs() as $lang) {
            if (!score_on($lang, $setting)) {
                continue;
            }
            $prizes = lottery_prizes_for_lang($lang);
            $agents = (string) feature_value('Lotteryagent', $lang, (string) ($setting['Lotteryagent'] ?? '0')) === '1';
            list($where, $params) = lottery_lang_where($lang);
            $stmt = $pdo->prepare("SELECT * FROM user WHERE User_Status = 'Active' AND score != '0' AND {$where}" . ($agents ? '' : " AND agent = 'f'") . " ORDER BY score DESC LIMIT 3");
            $stmt->execute($params);
            $tx = lang_tab_texts($lang);
            $rows = '';
            $rank = 0;
            while ($r = $stmt->fetch(PDO::FETCH_ASSOC)) {
                $prize = (float) (money_normalize($prizes[$rank] ?? '0') ?? 0);
                $rank++;
                if ($prize <= 0) {
                    continue;
                }
                wallet_credit($r['id'], $prize, currency_for_lang($lang));
                $amount = number_format($prize);
                sendmessage($r['id'], sprintf($tx['hardcoded']['lotteryWinnerNotice'], $rank, $amount), null, 'html');
                $rows .= sprintf($panel['hardcoded']['lotteryWinnerRow'], $r['username'], $r['id'], $amount, $rank);
            }
            // this language's points start again tomorrow
            $pdo->prepare("UPDATE user SET score = '0' WHERE {$where}")->execute($params);
            if ($rows !== '') {
                $report .= "\n🌐 " . ($panel['bottext']['langs'][$lang] ?? $lang) . ':' . $rows;
            }
        }
        if ($report !== '' && strlen((string) ($setting['Channel_Report'] ?? '')) > 0) {
            $otherreport = select("topicid", "idreport", "report", "otherreport", "select");
            telegram('sendmessage', [
                'chat_id' => $setting['Channel_Report'],
                'message_thread_id' => is_array($otherreport) ? ($otherreport['idreport'] ?? null) : null,
                'text' => $panel['hardcoded']['lotteryAdminReport'] . $report,
                'parse_mode' => "HTML",
            ]);
        }
    }
}
if (!function_exists('app_row_langs')) {
    // the languages one app-download row is shown in: a row with no language
    // of its own (from before the tabs) is every tab's
    function app_row_langs($row)
    {
        $l = trim((string) ($row['lang'] ?? ''));
        if ($l === '' || $l === 'all') {
            return panel_langs();
        }
        return array_values(array_filter(array_map('trim', explode(',', $l)), 'strlen'));
    }
}
if (!function_exists('text_fill_s')) {
    // sprintf() for a text an admin can edit: fills each %s in order and
    // leaves every other % alone. sprintf read English «50% for you» as a
    // number placeholder and threw, taking the whole referral page down.
    function text_fill_s($tpl, ...$args)
    {
        $i = 0;
        return preg_replace_callback('/%s/', function () use (&$i, $args) {
            return (string) ($args[$i++] ?? '');
        }, (string) $tpl);
    }
}
if (!function_exists('aff_classic_on')) {
    // The first of the two kinds of referral: 💼 زیرمجموعه‌گیری و هدیه خوش‌آمد
    // (the join gift and the purchase commission, and their page under 👥).
    // Per language, off until a tab turns it on. The other kind is 🎁 کانفیگ
    // رایگان با دعوت (affrw_cfg), with a switch of its own.
    function aff_classic_on($lang)
    {
        return (string) feature_setting_value('aff_classic', $lang, '0') === '1';
    }
    // anything under 👥 on for this language - the referral button's tap
    // sticker waits for it, so «nothing is active» does not come after one
    // 🎉 someone now counts for $refId's $plan: told in the inviter's own
    // language - 💼's about the commission, 🎁's with the free-config count
    // (only while it is still to be earned), and a plain one when neither
    // has anything to say.
    // $newId: the newcomer - one who was a member before the inviter's count
    // began does not count, and is announced as such (newReferralWasMember)
    function aff_notify_new_referral($refId, $displayName, $plan, $newId = null)
    {
        $ref = select("user", "*", "id", $refId, "select");
        $lang = is_array($ref) ? ($ref['lang'] ?? 'fa') : 'fa';
        $a = lang_tab_texts(in_array($lang, panel_langs(), true) ? $lang : 'fa')['users']['affiliates'];
        $name = htmlspecialchars((string) $displayName);
        if ($plan === 'c') {
            if (aff_classic_on($lang)) {
                bottext_extras_key_hint('users.affiliates.newReferralJoined');
                sendmessage($refId, text_fill_s($a['newReferralJoined'], htmlspecialchars(ltrim((string) $displayName, '@'))), null, 'html');
            }
            return;
        }
        $cfg = affrw_live($lang);
        $row = $cfg !== null ? affrw_row($refId) : null;
        if ($cfg !== null && affrw_counting($row)) {
            // a «new referral» whose counter did not move read as a bug: one
            // who was a member already is said to be one
            $key = ($newId === null || affrw_member_counts($refId, $newId)) ? 'newReferralJoinedReward' : 'newReferralWasMember';
            bottext_extras_key_hint("users.affiliates.{$key}");
            sendmessage($refId, strtr($a[$key], ['{username}' => $name, '{count}' => min(affrw_count($refId, affrw_since($cfg, $row)), $cfg['need']), '{need}' => $cfg['need']]), null, 'html');
        } elseif (!aff_classic_on($lang)) {
            bottext_extras_key_hint('users.affiliates.newReferralJoinedPlain');
            sendmessage($refId, strtr($a['newReferralJoinedPlain'], ['{username}' => $name]), null, 'html');
        }
    }
    function aff_any_on($lang)
    {
        $setting = select("setting", "*", null, null, "select");
        if (feature_value('affiliatesstatus', $lang, $setting['affiliatesstatus'] ?? '') == "offaffiliates") {
            return false;
        }
        return aff_classic_on($lang) || affrw_live($lang) !== null;
    }
    // ...and with 💼 off, one who has used 🎁 up gets nothing but its «used up»
    // message, which brings a sticker of its own: the button's would land
    // right on top of it, so that one goes alone
    function aff_tap_sticker_yields($uid, $lang)
    {
        if (aff_classic_on($lang) || affrw_live($lang) === null || !affrw_used_up(affrw_row($uid))) {
            return false;
        }
        $setting = select("setting", "*", null, null, "select");
        $layout = json_decode((string) ($setting['keyboardmain'] ?? ''), true);
        $map = (is_array($layout) && is_array($layout['text_stickers'] ?? null)) ? $layout['text_stickers'] : [];
        return bt_effective_sticker($map, 'users.affiliates.rewardLimitReached', $lang) !== '';
    }
}
if (!function_exists('refv_cfg')) {
    // 🛡 راستی‌آزمایی دعوت‌ها - one setting per plan and per language: 'c'
    // 💼 (commission, join gift) and 'r' 🎁 (the free-config count). An
    // invite counts for a plan only once the newcomer has done that plan's
    // part - sent their phone number and/or joined its channels. Off by
    // default - then an invite counts the moment the link is opened, as
    // before. The INVITER's language decides, like the plans.
    function refv_cfg($lang, $plan)
    {
        refv_split_legacy($lang);
        $ids = fn($v) => array_values(array_unique(array_filter(array_map('trim', explode(',', (string) $v)), 'strlen')));
        return [
            'phone' => (string) feature_setting_value("refv_{$plan}_phone", $lang, '0') === '1',
            'channel' => (string) feature_setting_value("refv_{$plan}_channel", $lang, '0') === '1',
            'channels' => array_map('intval', $ids(feature_setting_value("refv_{$plan}_channels", $lang, ''))),
            'vip' => $ids(feature_setting_value("refv_{$plan}_vip", $lang, '')),
        ];
    }
    // It was one setting for both plans at first: what was set there goes to
    // both, once, and the shared one is emptied - an emptied list of a plan
    // must not fall back to it.
    function refv_split_legacy($lang)
    {
        foreach (['phone', 'channel', 'channels', 'vip'] as $k) {
            $old = (string) feature_setting_value("refv_{$k}", $lang, '');
            if ($old === '') {
                continue;
            }
            foreach (['c', 'r'] as $plan) {
                if ((string) feature_setting_value("refv_{$plan}_{$k}", $lang, '') === '') {
                    feature_setting_set("refv_{$plan}_{$k}", $lang, $old);
                }
            }
            feature_setting_set("refv_{$k}", $lang, '');
        }
    }
    // the chosen channels that still exist, as rows
    function refv_channel_rows($cfg)
    {
        $rows = [];
        foreach ((array) select("channels", "*", null, null, "fetchAll") as $r) {
            if (is_array($r) && in_array((int) $r['id'], $cfg['channels'], true)) {
                $rows[] = $r;
            }
        }
        return $rows;
    }
    // What an invite to $inviterId has to pass before it counts for $plan: a
    // list of 'phone' / 'channel', empty when nothing (verification off, the
    // plan itself off, or a 👑 inviter of that plan). The phone check needs
    // 📞 احراز شماره تماس on for that language - it is that setting's
    // country codes the number is checked against.
    function refv_needs($inviterId, $plan)
    {
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $lang = is_array($inv) ? ($inv['lang'] ?? 'fa') : 'fa';
        if ($plan === 'c' ? !aff_classic_on($lang) : affrw_live($lang) === null) {
            return [];
        }
        $cfg = refv_cfg($lang, $plan);
        if (in_array((string) $inviterId, $cfg['vip'], true)) {
            return [];
        }
        // an admin with no limit (🛡 دسترسی ادمین): nothing asked of their invites either
        if ($plan === 'r' && affrw_admin_free($inviterId)) {
            return [];
        }
        $setting = select("setting", "*", null, null, "select");
        $needs = [];
        if ($cfg['phone'] && feature_value('get_number', $lang, $setting['get_number'] ?? '') == "onAuthenticationphone") {
            $needs[] = 'phone';
        }
        if ($cfg['channel'] && refv_channel_rows($cfg)) {
            $needs[] = 'channel';
        }
        return $needs;
    }
    // $plan's chosen channels $uid has not joined (rows)
    function refv_unjoined($uid, $inviterId, $plan)
    {
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $out = [];
        foreach (refv_channel_rows(refv_cfg(is_array($inv) ? ($inv['lang'] ?? 'fa') : 'fa', $plan)) as $r) {
            $res = telegram('getChatMember', ['chat_id' => $r['link'], 'user_id' => $uid]);
            if (empty($res['ok']) || !in_array($res['result']['status'] ?? '', ['member', 'creator', 'administrator'], true)) {
                $out[] = $r;
            }
        }
        return $out;
    }
    // what the newcomer has not done yet for $plan
    function refv_missing($userRow, $inviterId, $plan)
    {
        // 🎁 does not count a member from before the count began - so they are
        // not asked to join channels or send a number on its behalf either
        if ($plan === 'r' && !affrw_member_counts($inviterId, $userRow['id'] ?? '')) {
            return [];
        }
        $needs = refv_needs($inviterId, $plan);
        $missing = [];
        if (in_array('phone', $needs, true)) {
            $num = (string) ($userRow['number'] ?? 'none');
            if ($num === 'none' || $num === '' || !phone_matches_lang($num, $userRow['lang'] ?? 'fa')) {
                $missing[] = 'phone';
            }
        }
        if (in_array('channel', $needs, true) && refv_unjoined($userRow['id'], $inviterId, $plan)) {
            $missing[] = 'channel';
        }
        return $missing;
    }
    // whether $userRow already counts for $plan: 💼 is the link itself
    // (user.affiliates), 🎁 its own (user.aff_rw)
    function aff_counted($userRow, $plan)
    {
        return $plan === 'c' ? intval($userRow['affiliates'] ?? 0) != 0 : (string) ($userRow['aff_rw'] ?? '') !== '';
    }
    // user.aff_pending: the inviter a newcomer is still being verified for.
    // Made here, empty by default, before anything writes it - update() would
    // otherwise create it with its first value as every user's default.
    function refv_ensure_schema()
    {
        static $done = false;
        if (!$done) {
            $done = true;
            addFieldToTable('user', 'aff_pending', null, 'VARCHAR(50) NULL');
            // ⛔️ the plans an admin keeps this user out of as an inviter (aff_blocked)
            addFieldToTable('user', 'aff_block', null, 'VARCHAR(4) NULL');
            affrw_ensure_table();
        }
    }
    // 👤 مدیریت کاربر ← 👥 ← ⛔️: $uid kept out of $plan ('c' 💼 / 'r' 🎁) as
    // an INVITER - new invites through their link do not count for it, no
    // commission or share of a join gift (💼), no free config (🎁), and 👥
    // tells them it is closed. Invites counted before stay as they were.
    function aff_blocked($uid, $plan)
    {
        refv_ensure_schema();
        $u = select("user", "*", "id", (string) $uid, "select");
        return is_array($u) && strpos((string) ($u['aff_block'] ?? ''), (string) $plan) !== false;
    }
    function aff_block_set($uid, $plan, $on)
    {
        refv_ensure_schema();
        $u = select("user", "*", "id", (string) $uid, "select", ['cache' => false]);
        $now = is_array($u) ? (string) ($u['aff_block'] ?? '') : '';
        $set = [];
        foreach (['c', 'r'] as $p) {
            if ($p === $plan ? $on : strpos($now, $p) !== false) {
                $set[] = $p;
            }
        }
        update("user", "aff_block", $set ? implode('', $set) : null, "id", (string) $uid);
    }
    // asks the newcomer for the first thing still missing for the plans in
    // $plans - the phone first, then every channel of them not joined yet
    function refv_prompt($userRow, $inviterId, array $plans)
    {
        global $request_contact;
        $tx = payer_texts($userRow['id']);
        $a = $tx['users']['affiliates'];
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $name = (is_array($inv) && !empty($inv['username']) && $inv['username'] !== 'none') ? '@' . $inv['username'] : (string) $inviterId;
        $missing = [];
        foreach ($plans as $plan) {
            $missing = array_merge($missing, refv_missing($userRow, $inviterId, $plan));
        }
        if (in_array('phone', $missing, true)) {
            update("user", "Processing_value", "verifyref", "id", $userRow['id']);
            step('get_number', $userRow['id']);
            bottext_extras_key_hint('users.affiliates.verifyPhonePrompt');
            sendmessage($userRow['id'], strtr($a['verifyPhonePrompt'], ['{inviter}' => htmlspecialchars($name)]), $request_contact, 'HTML');
            return;
        }
        $kb = ['inline_keyboard' => []];
        $seen = [];
        foreach ($plans as $plan) {
            foreach (refv_unjoined($userRow['id'], $inviterId, $plan) as $r) {
                if (isset($seen[$r['id']])) {
                    continue;
                }
                $seen[$r['id']] = true;
                $r = channel_row_for_lang($r, $userRow['lang'] ?? 'fa');
                if (empty($r['linkjoin'])) {
                    continue;
                }
                [$t, $icon] = channel_button_text($r);
                $b = ['text' => $t, 'url' => $r['linkjoin']];
                if ($icon !== '') {
                    $b['icon_custom_emoji_id'] = $icon;
                }
                $kb['inline_keyboard'][] = [$b];
            }
        }
        $kb['inline_keyboard'][] = [['text' => $a['verifyChannelBtn'], 'callback_data' => 'refverify', 'style' => 'success']];
        bottext_extras_key_hint('users.affiliates.verifyChannelPrompt');
        sendmessage($userRow['id'], strtr($a['verifyChannelPrompt'], ['{inviter}' => htmlspecialchars($name)]), json_encode($kb), 'HTML');
    }
    // $userRow now counts for $inviterId's $plan: 'c' 💼 (the link is
    // written - commission, join gift - and the inviter's count goes up) or
    // 'r' 🎁 (the free-config count, which may now be reached). The inviter
    // is told, in their own language.
    function aff_count_for($userRow, $inviterId, $plan)
    {
        global $pdo, $from_id, $first_name;
        refv_ensure_schema();
        $uid = (string) $userRow['id'];
        $u = (string) ($userRow['username'] ?? '');
        $own = ((string) ($from_id ?? '') === $uid && (string) ($first_name ?? '') !== '') ? (string) $first_name : $uid;
        $display = ($u !== '' && $u !== 'none' && $u !== 'NOT_USERNAME') ? '@' . $u : $own;
        if ($plan === 'c') {
            $inv = select("user", "*", "id", (string) $inviterId, "select");
            update("user", "affiliates", $inviterId, "id", $uid);
            aff_notify_new_referral($inviterId, $display, 'c');
            update("user", "affiliatescount", intval($inv['affiliatescount'] ?? 0) + 1, "id", (string) $inviterId);
            $stmt = $pdo->prepare("INSERT IGNORE INTO reagent_report (user_id, get_gift,time,reagent) VALUES (?, ?,?, ?)");
            $stmt->execute([$uid, false, date('Y/m/d H:i:s'), (string) $inviterId]);
            aff_report_classic($inviterId, $uid, intval($inv['affiliatescount'] ?? 0) + 1);
            return;
        }
        update("user", "aff_rw", (string) $inviterId, "id", $uid);
        // 🚪 a free config paused by a leave: this invite fills the gap
        affrw_refill($inviterId, $uid);
        aff_notify_new_referral($inviterId, $display, 'r', $uid);
        // 🎁 and in the report group, before any request or config it brings
        affrw_report_referral($inviterId, $uid);
        affrw_check($inviterId);
    }
    // 👋 the newcomer, once they count for everything: the welcome of the
    // plan on for them - 💼's tells them about the join gift, 🎁's that they
    // can earn a free config too, and with neither just a welcome
    function aff_welcome($userRow, $inviterId, $keyboard = null)
    {
        $uid = (string) $userRow['id'];
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $tx = payer_texts($uid);
        $myLang = $userRow['lang'] ?? 'fa';
        // a plan the inviter is ⛔️ kept out of did not count this invite: its
        // welcome (a join gift, a free config to earn) would promise nothing
        $welcome = (aff_classic_on($myLang) && !aff_blocked($inviterId, 'c')) ? 'welcomeInvited'
            : ((affrw_live($myLang) !== null && !aff_blocked($inviterId, 'r')) ? 'welcomeInvitedReward' : 'welcomeInvitedPlain');
        $invName = (is_array($inv) && !empty($inv['username']) && $inv['username'] !== 'none') ? '@' . $inv['username'] : (string) $inviterId;
        bottext_extras_key_hint("users.affiliates.{$welcome}");
        sendmessage($uid, strtr(text_fill_s($tx['users']['affiliates'][$welcome], (string) ($inv['username'] ?? '')), ['{inviter}' => htmlspecialchars($invName)]), $keyboard, 'html');
    }
    // /start with $inviterId's link: each plan counts it now or once its own
    // part is done - asked for straight away, and free to use the bot
    // meanwhile
    function aff_invite_start($userRow, $inviterId, $keyboard = null)
    {
        refv_ensure_schema();
        update("user", "aff_pending", (string) $inviterId, "id", (string) $userRow['id']);
        refv_try($userRow['id'], $keyboard);
    }
    // After the link was opened, a number sent, «✅ عضو شدم» tapped or a
    // channel joined: every plan whose part is done now counts it. True once
    // all of them do; otherwise asked for what is left ($quiet: say nothing -
    // a join event, not a tap).
    function refv_try($uid, $keyboard = null, $quiet = false)
    {
        $u = select("user", "*", "id", (string) $uid, "select", ['cache' => false]);
        $inviterId = is_array($u) ? (string) ($u['aff_pending'] ?? '') : '';
        if ($inviterId === '') {
            return false;
        }
        $left = [];
        foreach (['c', 'r'] as $plan) {
            // ⛔️ an inviter kept out of this plan: it does not count, and the
            // newcomer is not asked for its phone / channels either
            if (aff_counted($u, $plan) || aff_blocked($inviterId, $plan)) {
                continue;
            }
            if (refv_missing($u, $inviterId, $plan)) {
                $left[] = $plan;
                continue;
            }
            aff_count_for($u, $inviterId, $plan);
        }
        if ($left) {
            if (!$quiet) {
                refv_prompt($u, $inviterId, $left);
            }
            return false;
        }
        update("user", "aff_pending", "", "id", (string) $uid);
        aff_welcome($u, $inviterId, $keyboard);
        return true;
    }
}
if (!function_exists('aff_detach')) {
    // 👤 مدیریت کاربر's «خارج کردن از زیرمجموعه»: $uid is nobody's referral any
    // more - for 💼 (affiliates, and the inviter's affiliatescount), for 🎁
    // (aff_rw) and for a 🛡 check still waiting (aff_pending). These buttons
    // used to clear affiliates alone: the customer went on counting for 🎁 and
    // could never be invited by anyone again. A join gift not claimed yet goes
    // too; one already claimed stays on record, so it cannot be claimed twice.
    function aff_detach($uid)
    {
        global $pdo;
        refv_ensure_schema();
        $id = (string) $uid;
        $u = select("user", "*", "id", $id, "select", ['cache' => false]);
        if (!is_array($u)) {
            return;
        }
        $ref = (string) ($u['affiliates'] ?? '0');
        if ($ref !== '' && $ref !== '0') {
            $pdo->prepare("UPDATE user SET affiliatescount = GREATEST(CAST(affiliatescount AS SIGNED) - 1, 0) WHERE id = ?")->execute([$ref]);
        }
        $pdo->prepare("UPDATE user SET affiliates = '0', aff_rw = NULL, aff_pending = NULL WHERE id = ?")->execute([$id]);
        $pdo->prepare("DELETE FROM reagent_report WHERE user_id = ? AND (get_gift = 0 OR get_gift IS NULL)")->execute([$id]);
        clearSelectCache();
    }
    // ...«حذف زیرمجموعه های کاربر»: every referral of $uid, in both plans
    function aff_detach_all($uid)
    {
        global $pdo;
        refv_ensure_schema();
        $id = (string) $uid;
        $pdo->prepare("UPDATE user SET affiliates = '0' WHERE affiliates = ?")->execute([$id]);
        $pdo->prepare("UPDATE user SET aff_rw = NULL WHERE aff_rw = ?")->execute([$id]);
        $pdo->prepare("UPDATE user SET aff_pending = NULL WHERE aff_pending = ?")->execute([$id]);
        $pdo->prepare("UPDATE user SET affiliatescount = '0' WHERE id = ?")->execute([$id]);
        $pdo->prepare("DELETE FROM reagent_report WHERE reagent = ? AND (get_gift = 0 OR get_gift IS NULL)")->execute([$id]);
        clearSelectCache();
    }
    // ...and «👥 زیرمجموعه های کاربر»: who came through $uid's link, for 💼
    // or for 🎁 (each plan keeps its own)
    function aff_referrals_of($uid)
    {
        global $pdo;
        refv_ensure_schema();
        $st = $pdo->prepare("SELECT id FROM user WHERE affiliates = ? OR aff_rw = ? ORDER BY CAST(register AS UNSIGNED)");
        $st->execute([(string) $uid, (string) $uid]);
        return array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN));
    }
    // A value in a Persian line of a report, kept in place: Telegram lays a
    // mixed line out by the letters it meets, so a Latin name or @username -
    // or one starting with "-" - jumped about. A Latin one gets a
    // left-to-right mark in front; every one a right-to-left mark after it,
    // so what follows stays in the line's order. ($plain decides, $html is
    // what is shown.)
    function aff_bidi($plain, $html)
    {
        return (preg_match('/^[^\p{L}]*[\p{Latin}\p{Cyrillic}\p{Greek}]/u', (string) $plain) ? "\u{200E}" : '') . $html . "\u{200F}";
    }
    // 👥 the name (in bold, a link to them) and @username a report shows for
    // someone - '' when not known ($row: their user row; first_name is kept
    // by index.php)
    function aff_name_parts($id, $row = null)
    {
        $name = trim((string) (is_array($row) ? ($row['first_name'] ?? '') : ''));
        $u = (string) (is_array($row) ? ($row['username'] ?? '') : '');
        $u = ($u !== '' && $u !== 'none' && $u !== 'NOT_USERNAME') ? $u : '';
        return [
            $name === '' ? '' : aff_bidi($name, '<a href="tg://user?id=' . htmlspecialchars((string) $id) . '"><b>' . htmlspecialchars($name) . '</b></a>'),
            $u === '' ? '' : aff_bidi('@' . $u, '@' . htmlspecialchars($u)),
        ];
    }
    // ...on one line: name · @username · id
    function aff_label($id, $row = null)
    {
        $parts = array_values(array_filter(aff_name_parts($id, $row), 'strlen'));
        $parts[] = '<code>' . htmlspecialchars((string) $id) . '</code>';
        return implode(' · ', $parts);
    }
    // ...one per line, for a report's 👤 block
    function aff_user_block($id, $row = null)
    {
        $t = panel_texts()['Admin']['AffReward'];
        [$name, $u] = aff_name_parts($id, $row);
        $out = [];
        if ($name !== '') {
            $out[] = strtr($t['lineName'], ['{v}' => $name]);
        }
        if ($u !== '') {
            $out[] = strtr($t['lineUsername'], ['{v}' => $u]);
        }
        $out[] = strtr($t['lineId'], ['{v}' => '<code>' . htmlspecialchars((string) $id) . '</code>']);
        return implode("\n", $out);
    }
    // ...as one line of a list ($date: when they joined, or ''); it starts
    // with a right-to-left mark so every line is laid out the same way,
    // whatever script the name is in
    function aff_list_line($id, $row = null, $date = '')
    {
        return "\u{200F}• " . aff_label($id, $row) . ($date !== '' ? ' · 🕓 ' . $date : '');
    }
    // ...a list of them in the order given; the first $max, then «… و N نفر
    // دیگه». $withDate: when each joined (the admins' request).
    function aff_label_lines(array $ids, $max = 15, $withDate = false)
    {
        global $pdo;
        $ids = array_values(array_unique(array_map('strval', $ids)));
        $shown = array_slice($ids, 0, $max);
        $rows = [];
        if ($shown) {
            $st = $pdo->prepare("SELECT * FROM user WHERE id IN (" . implode(',', array_fill(0, count($shown), '?')) . ")");
            $st->execute($shown);
            foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
                $rows[(string) $r['id']] = $r;
            }
        }
        $out = '';
        foreach ($shown as $id) {
            $reg = (int) ($rows[$id]['register'] ?? 0);
            $out .= aff_list_line($id, $rows[$id] ?? null, ($withDate && $reg > 0) ? jdate('Y/m/d H:i', $reg) : '') . "\n";
        }
        if (count($ids) > $max) {
            $out .= strtr(panel_texts()['Admin']['AffReward']['listMore'], ['{n}' => count($ids) - $max]) . "\n";
        }
        return rtrim($out);
    }
    // 💼 a new referral counted, in the report group's 💰 پورسانت topic: the
    // inviter, the newcomer, which referral of theirs this is ($n), how many
    // services their referrals have bought (as their 👥 page counts them) and
    // the latest of them. Only while 💼 is on for the inviter's language.
    function aff_report_classic($inviterId, $memberId, $n)
    {
        global $pdo;
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $lang = is_array($inv) ? ($inv['lang'] ?? 'fa') : 'fa';
        if (!aff_classic_on($lang)) {
            return;
        }
        // only a report: the referral is counted whatever happens here
        try {
            $st = $pdo->prepare("SELECT COUNT(*) FROM invoice WHERE refral = ? AND Status IN ('active', 'end_of_time', 'sendedwarn', 'send_on_hold')");
            $st->execute([(string) $inviterId]);
            $buys = (int) $st->fetchColumn();
            $st = $pdo->prepare("SELECT id FROM user WHERE affiliates = ? AND id != ? ORDER BY CAST(register AS UNSIGNED) DESC");
            $st->execute([(string) $inviterId, (string) $inviterId]);
            $pt = panel_texts();
            $code = in_array($lang, panel_langs(), true) ? $lang : 'fa';
            affrw_report('porsantreport', strtr($pt['Admin']['AffReward']['newReferral'], [
                '{inviter}' => aff_user_block($inviterId, $inv),
                '{member}' => aff_user_block($memberId, select("user", "*", "id", (string) $memberId, "select")),
                '{n}' => (int) $n,
                '{buys}' => $buys,
                '{list}' => aff_label_lines($st->fetchAll(PDO::FETCH_COLUMN), 10),
            ]) . "\n\n" . sprintf($pt['Admin']['reportgroup']['userLangLine'], $pt['bottext']['langs'][$code] ?? $code));
        } catch (Throwable $e) {
            error_log('aff_report_classic: ' . $e->getMessage());
        }
    }
}
if (!function_exists('phone_required_for')) {
    // 📞 احراز شماره تماس on for this customer's language, and meant for them:
    // everyone (as before), only customers who joined after it was set to
    // «new», or only invited ones - the audience set on its ⚙️ screen
    function phone_required_for($userRow)
    {
        $lang = $userRow['lang'] ?? 'fa';
        $setting = select("setting", "*", null, null, "select");
        if (feature_value('get_number', $lang, $setting['get_number'] ?? '') != "onAuthenticationphone") {
            return false;
        }
        return audience_includes((string) feature_setting_value('phone_audience', $lang, 'all'), (int) feature_setting_value('phone_audience_since', $lang, '0'), $userRow);
    }
    // all / new (joined after $since) / invited (came with a referral link)
    function audience_includes($aud, $since, $userRow)
    {
        if ($aud === 'new') {
            return (int) ($userRow['register'] ?? 0) > $since;
        }
        if ($aud === 'invited') {
            return intval($userRow['affiliates'] ?? 0) != 0 || (string) ($userRow['aff_pending'] ?? '') !== '';
        }
        return $aud !== 'none';
    }
}
if (!function_exists('channel_gate_map')) {
    // 📯 who has to join each channel for the bot to work, per language:
    // {channelId: {"aud": all|new|invited|none, "since": ts}}. A channel not
    // in it is «all» - what every channel was before.
    function channel_gate_map($lang)
    {
        $m = json_decode((string) feature_setting_value('chn_gate', $lang, '{}'), true);
        return is_array($m) ? $m : [];
    }
    function channel_gate_aud($lang, $channelId)
    {
        return (string) (channel_gate_map($lang)[(string) $channelId]['aud'] ?? 'all');
    }
    // the channel links this customer has to join to use the bot
    function channel_gate_links_for($userRow)
    {
        $lang = $userRow['lang'] ?? 'fa';
        $map = channel_gate_map($lang);
        $out = [];
        foreach ((array) select("channels", "*", null, null, "fetchAll") as $r) {
            if (!is_array($r)) {
                continue;
            }
            $g = $map[(string) $r['id']] ?? ['aud' => 'all', 'since' => 0];
            if (audience_includes((string) ($g['aud'] ?? 'all'), (int) ($g['since'] ?? 0), $userRow)) {
                $out[] = $r['link'];
            }
        }
        return $out;
    }
}
if (!function_exists('feature_aff_banner')) {
    // 🎁 the referral banner of one language: [caption, photo]. Persian falls
    // back to the banner set before the tabs; another language does not - that
