        $isFa = ($lang === 'fa');
        return [
            (string) feature_setting_value('aff_banner_text', $lang, $isFa ? (string) ($affRow['description'] ?? '') : ''),
            (string) feature_setting_value('aff_banner_media', $lang, $isFa ? (string) ($affRow['id_media'] ?? '') : 'none'),
        ];
