            addFieldToTable('user', 'card_trust_auto', null, 'VARCHAR(20) NULL');
        }
    }
    // 📅 a second way to count as a returning customer, per language: joined
    // the bot on or before this Gregorian day («cardtrustdate», Y-m-d; empty =
    // no date rule). Either rule is enough - more than N purchases/renewals, or
    // a member since then.
    function card_trust_date_ok($d)
    {
        return is_string($d) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $d) === 1
            && checkdate((int) substr($d, 5, 2), (int) substr($d, 8, 2), (int) substr($d, 0, 4));
    }
    function card_trust_date($lang)
    {
        $d = trim((string) pay_value('cardtrustdate', $lang, ''));
        return card_trust_date_ok($d) ? $d : '';
    }
    // what an admin typed, as Y-m-d, or null: 2026-11-02, 2026/11/2, 2026.11.02,
    // Persian or Arabic digits. A Jalali day (1405/08/12) is turned into its
    // Gregorian one - no join date of a Telegram bot falls in the years 1300-1500.
    function card_trust_date_parse($s)
    {
        $s = strtr(trim((string) $s), [
            '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
            '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
        ]);
        if (!preg_match('~^(\d{4})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})$~', $s, $m)) {
            return null;
        }
        [$y, $mo, $d] = [(int) $m[1], (int) $m[2], (int) $m[3]];
        if ($y >= 1300 && $y <= 1500) {
            if (!function_exists('jalali_to_gregorian') || !jcheckdate($mo, $d, $y)) {
                return null;
            }
            [$y, $mo, $d] = array_map('intval', jalali_to_gregorian($y, $mo, $d));
        }
        if ($y < 2000 || $y > 2100 || !checkdate($mo, $d, $y)) {
            return null;
        }
        return sprintf('%04d-%02d-%02d', $y, $mo, $d);
    }
    // the last second of that day, in this language's zone (lang_timezone):
    // "2 November" takes in everyone who joined on the 2nd too
    function card_trust_date_until($lang)
    {
        $d = card_trust_date($lang);
        if ($d === '') {
            return null;
        }
        $dt = DateTime::createFromFormat('!Y-m-d H:i:s', $d . ' 23:59:59', new DateTimeZone(lang_timezone($lang)));
        return $dt ? $dt->getTimestamp() : null;
    }
    // user.register is the unix time of the first /start ('none' until the
    // first message after an old install filled it in - not a member date)
    function card_trust_joined_by_date($userRow, $lang)
    {
        $until = card_trust_date_until($lang);
        $reg = trim((string) ($userRow['register'] ?? ''));
        return $until !== null && ctype_digit($reg) && (int) $reg > 0 && (int) $reg <= $until;
    }
    // how many users of this language joined on or before the day
    function card_trust_date_count($lang)
    {
        global $pdo;
        $until = card_trust_date_until($lang);
        if ($until === null) {
            return 0;
        }
        [$w, $p] = user_lang_where($lang);
        $st = $pdo->prepare("SELECT COUNT(*) FROM user WHERE {$w} AND register REGEXP '^[0-9]+$' AND CAST(register AS UNSIGNED) > 0 AND CAST(register AS UNSIGNED) <= ?");
        $st->execute(array_merge($p, [$until]));
        return (int) $st->fetchColumn();
    }
    // the day as an admin reads it: 2026-11-02, and in Persian also its Jalali
    // day (۱۱ آبان ۱۴۰۵)
    function card_trust_date_label($lang)
    {
        $d = card_trust_date($lang);
        if ($d === '') {
            return '';
        }
        // noon of the same calendar day on Tehran time, so the Jalali day is
        // that day whatever the language's own zone is
        $noon = DateTime::createFromFormat('!Y-m-d H:i:s', $d . ' 12:00:00', new DateTimeZone('Asia/Tehran'));
        $jal = ($noon && function_exists('jdate')) ? jdate('j F Y', $noon->getTimestamp(), '', 'Asia/Tehran') : '';
        return $d . ($jal !== '' ? " ({$jal})" : '');
    }
    // Does this customer get the card-to-card button right now? Their own
    // switch (user.cardpayment - 👥 کارت‌به‌کارت کاربرها, the user's page) as
    // before; with 🛡 on, also more than N paid purchases/renewals. The first
    // time a customer is found past N, card-to-card is switched on for them -
    // once: card_trust_auto remembers it, so an admin who turns it off for that
    // customer afterwards is not overruled on the next message.
    function card_visible_for($userRow, $lang)
    {
        if (!is_array($userRow) || empty($userRow['id'])) {
            return false;
        }
        $on = (string) ($userRow['cardpayment'] ?? '') === '1';
        if (!card_trust_on($lang)) {
            return $on;
        }
        // 📅 a member since the day set is trusted too - the cheap check first
        if (!card_trust_joined_by_date($userRow, $lang) && card_trust_count($userRow['id']) <= card_trust_min($lang)) {
            return false;
        }
        if (trim((string) ($userRow['card_trust_auto'] ?? '')) === '') {
            card_trust_ensure_schema();
            update("user", "card_trust_auto", (string) time(), "id", $userRow['id']);
            if (!$on) {
                update("user", "cardpayment", "1", "id", $userRow['id']);
                $on = true;
            }
        }
        return $on;
    }
}
if (!function_exists('card_access_counts')) {
    function card_sms_forward_on()
    {
        return (select("setting", "smsForwardEnabled", null, null, "select")['smsForwardEnabled'] ?? '0') === '1';
    }
    // what croncard.php needs to confirm a receipt by itself: 🤖 on AND a
    // time - the minutes, or 0 when it would not happen
    function card_auto_confirm_minutes($lang)
    {
        if (pay_value('autoconfirmcart', $lang, 'offauto') !== 'onauto') {
            return 0;
        }
        return max(0, intval(pay_value('timeauto_not_verify', $lang, '0')));
    }
    // 👥 کارت‌به‌کارت کاربرها («نمایش شماره کارت به کاربران» was): this
    // language's users who see the card-to-card button (user.cardpayment = 1)
    // and who do not
    function card_access_counts($lang)
    {
        global $pdo;
        [$w, $p] = user_lang_where($lang);
        $st = $pdo->prepare("SELECT COUNT(*) AS n, COALESCE(SUM(cardpayment = '1'), 0) AS on_n FROM user WHERE {$w}");
        $st->execute($p);
        $r = $st->fetch(PDO::FETCH_ASSOC) ?: [];
        $on = (int) ($r['on_n'] ?? 0);
        return [$on, (int) ($r['n'] ?? 0) - $on];
    }
    // a change for all of them - 'on', 'off', 'offf' (all but the agents):
    // the users it actually changes
    function card_access_where($lang, $op)
    {
        [$w, $p] = user_lang_where($lang);
        $val = $op === 'on' ? '1' : '0';
        return [$w . ($op === 'offf' ? " AND agent = 'f'" : '') . ' AND cardpayment <> ?', array_merge($p, [$val]), $val];
    }
    function card_access_target_count($lang, $op)
    {
        global $pdo;
        [$w, $p] = card_access_where($lang, $op);
        $st = $pdo->prepare("SELECT COUNT(*) FROM user WHERE {$w}");
        $st->execute($p);
        return (int) $st->fetchColumn();
    }
    function card_access_apply($lang, $op)
    {
        global $pdo;
        [$w, $p, $val] = card_access_where($lang, $op);
        $st = $pdo->prepare("UPDATE user SET cardpayment = ? WHERE {$w}");
        $st->execute(array_merge([$val], $p));
        clearSelectCache('user');
        return $st->rowCount();
    }
    // 🚫 one list of user ids (PaySetting Exception_auto_cart), checked by
    // croncard.php for whoever pays; each language's screen shows and edits
    // its own users in it
    function card_exc_list()
    {
        $l = json_decode((string) (select("PaySetting", "ValuePay", "NamePay", "Exception_auto_cart", "select")['ValuePay'] ?? '[]'), true);
        return is_array($l) ? array_values(array_map('strval', $l)) : [];
    }
    function card_exc_members($lang)
    {
        global $pdo;
        $ids = card_exc_list();
        if (!$ids) {
            return [];
        }
        [$w, $p] = user_lang_where($lang);
        $st = $pdo->prepare("SELECT id, username FROM user WHERE id IN (" . implode(',', array_fill(0, count($ids), '?')) . ") AND {$w}");
        $st->execute(array_merge($ids, $p));
        return $st->fetchAll(PDO::FETCH_KEY_PAIR);
    }
    // 🚫 this language's users in the list replaced by $ids; the other
    // languages' users in it stay
    function card_exc_set_lang($lang, array $ids)
    {
        $keep = array_diff(card_exc_list(), array_map('strval', array_keys(card_exc_members($lang))));
        update("PaySetting", "ValuePay", json_encode(array_values(array_unique(array_merge($keep, array_map('strval', $ids))))), "NamePay", "Exception_auto_cart");
    }
}
if (!function_exists('card_legacy_has_any_override')) {
    // Drives the green "this language is customised" state on the main
    // screen's entry button - deliberately scoped to only the 5 per-language
    // fields (not the 4 global ones below them), since a global change isn't
    // "this language's" customisation and would wrongly turn every language's
    // entry button green at once.
    function card_legacy_has_any_override($lang)
    {
        foreach (array_keys(card_legacy_toggle_fields()) as $f) {
            if (gw_pay_override_has($f, $lang)) {
                return true;
            }
        }
        return gw_pay_override_has('timeauto_not_verify', $lang) || gw_pay_override_has('helpcart', $lang) || gw_pay_override_has('showcard', $lang)
            || gw_pay_override_has('cardtrustmin', $lang) || gw_pay_override_has('cardtrustdate', $lang);
    }
}
if (!function_exists('gw_lang_has_any_override')) {
    function gw_lang_has_any_override($lang)
    {
        foreach (array_keys(gw_field_registry()) as $k) {
            if (gw_has_any_override($k, $lang)) {
                return true;
            }
        }
        return false;
    }
}
if (!function_exists('gw_reset_gateway')) {
    function gw_reset_gateway($gatewayKey, $lang)
    {
        $m = gw_lang_settings_map();
        foreach (gw_field_registry()[$gatewayKey] ?? [] as $f) {
            if (gw_field_scope($f) === 'global') {
                continue; // "reset this language" must never wipe a shared credential
            }
            if ($f['type'] === 'cards') {
                unset($m[$lang]['cards']);
            } else {
                unset($m[$lang]['pay'][$f['field']]);
            }
        }
        if (isset($m[$lang]['pay']) && empty($m[$lang]['pay'])) {
            unset($m[$lang]['pay']);
        }
        gw_lang_settings_save($m);
        // same reasoning as gw_has_any_override() above - these two live in
        // their own storage, so "reset this language" has to clear them here
        if ($gatewayKey === 'card') {
            card_invoice_caption_set($lang, '');
            $btnMap = card_invoice_btnstyle_map(true);
            unset($btnMap[$lang]);
            card_invoice_btnstyle_save($btnMap);
            card_invoice_expired_caption_set($lang, '');
        }
    }
}
