    function gateway_disc_group_members($group, $lang, $textbotlang)
    {
        $live = topup_disc_enabled_gateways($lang, $textbotlang);
        $out = [];
        foreach (gateway_disc_groups()[$group] ?? [] as $key) {
            if (isset($live[$key])) {
                $out[$key] = $live[$key];
            }
        }
        return $out;
    }
}
