    function plisio_invoice_btnstyle_map($fresh = false)
    {
        static $cache = null;
        if ($cache !== null && !$fresh) {
            return $cache;
        }
        $setting = select("setting", "*", null, null, "select");
        $m = json_decode((string) ($setting['plisio_invoice_btnstyle'] ?? ''), true);
        $cache = is_array($m) ? $m : [];
