            'exp' => $t['askExpCaption'],
        ][$kind] ?? $t['askCaption'];
        // popups are plain text - say so where the admin types one
        if (in_array($kind, ['paidalert', 'notseen'], true)) {
            $prompt .= $t['popupPlainNote'] ?? '';
        }
        return $prompt . topup_gwcap_placeholders($kind, $key, $textbotlang);
    }
}
