    {
        $sb_b = statusbtn_bucket($kind);
        $setting = select("setting", "*", null, null, "select");
        $be = json_decode((string) ($setting['button_edit'] ?? ''), true);
        return (is_array($be) && isset($be[$lang][$sb_b][$key]) && is_array($be[$lang][$sb_b][$key]))
            ? $be[$lang][$sb_b][$key]
            : [];
