            'mm_color' => ['bit' => 32, 'label' => '🎨 رنگ دکمه‌های منو', 'sep' => ''],
            'mm_emoji' => ['bit' => 64, 'label' => '😀 ایموجی دکمه‌های منو', 'sep' => ''],
            'mm_visibility' => ['bit' => 128, 'label' => '👁 نام و مخفی‌بودن دکمه‌ها', 'sep' => ''],
