            }
            if (empty($be[$lang])) {
                unset($be[$lang]);
            }
        } else {
            $be[$lang][$key][0]['tapSticker'] = (string) $fileId;
        }
        update("setting", "button_edit", empty($be) ? null : json_encode($be, JSON_UNESCAPED_UNICODE), null, null);
    }
    // what such a button sends: its action, marked with which button it is so
