if (!function_exists('genbtn_current')) {
    // merged text/style only - what the admin's plain-text preview/list rows show
    function genbtn_current(array $def, array $ov)
    {
        $text = (isset($ov['text']) && $ov['text'] !== '') ? $ov['text'] : $def['text'];
        $style = (isset($ov['style']) && in_array($ov['style'], ['primary', 'success', 'danger'], true)) ? $ov['style'] : $def['style'];
        return [$text, $style];
    }
}
if (!function_exists('genbtn_is_hidden')) {
    // an explicit override wins either way; with none, a def may ship hidden
    // ('ab'/'ut') - which is why "shown" is stored as hidden => false there
    function genbtn_is_hidden(array $def, array $ov)
    {
        return array_key_exists('hidden', $ov) ? !empty($ov['hidden']) : !empty($def['hidden']);
    }
}
if (!function_exists('genbtn_render')) {
    // the button as it is actually sent to a real user - same emoji-baking
    // algorithm as volumepct_tier_kb(), generalized to any def/override pair
    function genbtn_render(array $def, array $ov, $callback_data)
    {
        list($text, $style) = genbtn_current($def, $ov);
        $pos = (isset($ov['pos']) && $ov['pos'] === 'left') ? 'left' : 'right';
        $btn = ['text' => $text, 'callback_data' => $callback_data];
        if ($style !== '') {
            $btn['style'] = $style;
        }
        if (!empty($ov['simple'])) {
            $btn['text'] = strip_leading_emoji($text);
        } elseif (!empty($ov['emojiIcon'])) {
            $btn['text'] = strip_leading_emoji($text);
            $btn['icon_custom_emoji_id'] = $ov['emojiIcon'];
        } else {
            if (!empty($ov['emoji'])) {
                $emoji = $ov['emoji'];
                $rest = strip_leading_emoji($text);
            } else {
                list($emoji, $rest) = split_leading_emoji($text);
            }
            if ($emoji !== '') {
                $btn['text'] = ($pos === 'left') ? trim($rest . ' ' . $emoji) : trim($emoji . ' ' . $rest);
            }
        }
        return $btn;
    }
}
if (!function_exists('myservices_close_btn')) {
    function myservices_close_btn($lang, $textbotlang)
    {
        $defs = genbtn_defs('sc', $textbotlang);
        $ov = genbtn_override($lang, 'users.sell.service_sell', 0);
        return genbtn_render($defs[0], $ov, $defs[0]['callback_data']);
    }
    // One of 🛍 سرویس‌های من's paging buttons (genbtn 'sc' 1-4) as this tab's
    // admin set it up, or null when it is hidden there.
    function myservices_page_btn($lang, $textbotlang, $idx)
    {
        $defs = genbtn_defs('sc', $textbotlang);
        $ov = genbtn_override($lang, 'users.sell.service_sell', $idx);
        if (genbtn_is_hidden($defs[$idx], $ov)) {
            return null;
        }
        return genbtn_render($defs[$idx], $ov, $defs[$idx]['callback_data']);
    }
}
if (!function_exists('myservices_nav_rows')) {
    // The rows under 🛍 سرویس‌های من's list, the same on every page: 🔎
    // جستجو سریع and the paging when the list runs past one page, then ❌
    // بستن. Page one has «صفحه بعد» (there is no page before it); later pages
    // «بعدی / قبلی». Each page used to build its own - page one had no
    // search, later pages no close, and «قبلی» back onto page one kept a
    // «قبلی» that led to a page zero.
    function myservices_nav_rows($lang, $textbotlang, $page, $paged)
    {
        $rows = [];
        if ($paged) {
            $search = myservices_page_btn($lang, $textbotlang, 2);
            if ($search !== null) {
                $rows[] = [$search];
            }
            $rows[] = $page <= 1
                ? [myservices_page_btn($lang, $textbotlang, 1)]
                : [myservices_page_btn($lang, $textbotlang, 3), myservices_page_btn($lang, $textbotlang, 4)];
        }
        if (!bt_button_hidden($lang, 'users.sell.service_sell')) {
            $rows[] = [myservices_close_btn($lang, $textbotlang)];
        }
        return $rows;
    }
}
if (!function_exists('subapp_kind')) {
    // The kind of a service: b خرید, t اکانت تست, r 🎁 هدیه‌ی دعوت not renewed
    // yet (renewed, it is a service like any other), h ⏱ اشتراک ساعتی. The
    // 🌐 / 📲 pair and the app list are one for all of them (genbtn gb / kb);
    // the kind tells which 💡 / status buttons a screen carries.
    function subapp_kind($inv)
    {
        if ((int) ($inv['payg'] ?? 0) === 1) {
            return 'h';
        }
        if ((int) ($inv['affrw'] ?? 0) === 1) {
            return 'r';
        }
        // a test account keeps the name it was made with, in the language its
        // owner had then
        foreach (panel_langs() as $l) {
            $labels = lang_tab_texts($l)['common']['labels'];
            $names = array_filter([(string) ($labels['testService5'] ?? ''), (string) ($labels['testServiceName'] ?? '')]);
            if (in_array((string) ($inv['name_product'] ?? ''), $names, true)) {
                return 't';
            }
        }
        return 'b';
    }
    // the keys of that group
    function subapps_group_keys()
    {
        global $textbotlang;
        return array_values(array_column(array_filter($textbotlang['bottext']['items'] ?? [], fn($it) => ($it['group'] ?? '') === 'subapps' && !empty($it['key'])), 'key'));
    }
    // the two looks of the app-opening page (subapp.php): the words, the font
    // and the motion are the same, only the theme changes. Chosen per language
    // (feature_lang_settings 'subapp_look'), 'glass' until someone picks
    function subapp_looks()
    {
        global $textbotlang;
        $n = $textbotlang['bottext']['saLookNames'] ?? [];
        return ['glass' => $n['glass'] ?? '✨ A — Glass', 'minimal' => $n['minimal'] ?? '⚪ B — Minimal'];
    }
    function subapp_look($lang)
    {
        $v = (string) feature_setting_value('subapp_look', $lang, 'glass');
        return isset(subapp_looks()[$v]) ? $v : 'glass';
    }
    // dark / light of that page, chosen per language like the look: 'auto' (the
