                $clean[$k] = $lay[$k];
            }
        }
        $clean = array_merge($clean, subapp_layout_clean_extras($lay));
        $clean['hide'] = array_values(array_intersect(subapp_layout_elements(), (array) ($lay['hide'] ?? [])));
        $ord = array_values(array_unique(array_intersect((array) ($lay['order'] ?? []), subapp_layout_blocks())));
        $clean['order'] = array_merge($ord, array_values(array_diff(subapp_layout_blocks(), $ord)));
        // nothing changed: nothing kept
        feature_setting_set('subapp_layout', $lang, $clean === subapp_layout_defaults() ? '' : json_encode($clean));
    }
    function subapp_layout_changed($lang)
    {
        return subapp_layout($lang) !== subapp_layout_defaults();
    }
    // the stores of an app: Google Play, the latest GitHub release, the App
    // Store, its own site. The admin may change each (per language); «-» says
    // «none» and an empty one is the default
    function subapp_link_kinds()
    {
        return ['play', 'github', 'ios', 'site'];
    }
    function subapp_link_valid($url)
    {
        return (bool) preg_match('~^https?://[^\s<>"\']{3,300}$~i', (string) $url);
    }
    function subapp_links($lang)
    {
        $raw = json_decode((string) feature_setting_value('subapp_links', $lang, ''), true);
        return is_array($raw) ? $raw : [];
    }
    function subapp_link_set($lang, $appId, $kind, $value)
    {
        $m = subapp_links($lang);
        if ($value === '') {
            unset($m[$appId][$kind]);
            if (empty($m[$appId])) {
                unset($m[$appId]);
            }
        } else {
            $m[$appId][$kind] = $value;
        }
        feature_setting_set('subapp_links', $lang, $m ? json_encode($m, JSON_UNESCAPED_SLASHES) : '');
    }
    // subapp_apps() with this language's links on top of the defaults
    function subapp_apps_for($lang)
    {
        $m = subapp_links($lang);
        $apps = subapp_apps();
        foreach ($apps as $i => $a) {
            foreach (subapp_link_kinds() as $kind) {
                $v = $m[$a['id']][$kind] ?? null;
                if ($v === '-') {
                    $apps[$i][$kind] = '';
                } elseif (is_string($v) && subapp_link_valid($v)) {
                    $apps[$i][$kind] = $v;
                }
            }
        }
        return $apps;
    }
    // anything of the page changed here: its look, theme, layout or links
    function subapps_customized($lang)
    {
        return subapp_look($lang) !== 'glass' || subapp_theme($lang) !== 'auto' || subapp_layout_changed($lang) || subapp_links($lang) !== [];
    }
    // a link to the page with made-up data, for the admin to see a look before
    // choosing it - signed like the real ones, and it opens nothing (subapp.php)
    function subapp_preview_link($look, $lang, $appId = 'karing', $state = '', array $extra = [])
    {
        global $domainhosts;
        $q = ['demo' => $look, 'l' => $lang, 'a' => $appId, 's' => subapp_sig('demo' . $look . $lang, $appId)];
        if (in_array($state, ['opening', 'missing', 'opened', 'downloading', 'back'], true)) {
            $q['st'] = $state;
        }
        // th: a theme, os: whose stores, ed: the admin's editor talks to the page
        $q += array_intersect_key($extra, ['th' => 1, 'os' => 1, 'ed' => 1]);
        return "https://{$domainhosts}/subapp.php?" . http_build_query($q);
    }
    // 🧩 the page's layout as a 🎨 screen: [text, keyboard json]
    function subapp_layout_screen($lang)
    {
        global $textbotlang;
        $tb = $textbotlang['bottext'];
        $p = $textbotlang['panel'];
        $lay = subapp_layout($lang);
        $blockEls = ['stage' => ['logo', 'flow'], 'title' => ['title'], 'chip' => ['chip'], 'status' => ['status'], 'actions' => ['steps', 'note', 'download', 'stores', 'retry']];
        $rows = [];
        $last = count($lay['order']) - 1;
        foreach ($lay['order'] as $i => $b) {
            $rows[] = [
                ['text' => $p['seBlock' . ucfirst($b)], 'callback_data' => 'bt_sep|subapps_lay'],
                ['text' => '⬆️', 'callback_data' => $i > 0 ? "salay|{$lang}|mv_{$b}_u" : 'bt_sep|subapps_lay'],
                ['text' => '⬇️', 'callback_data' => $i < $last ? "salay|{$lang}|mv_{$b}_d" : 'bt_sep|subapps_lay'],
            ];
            $row = [];
            foreach ($blockEls[$b] as $el) {
                $shown = !in_array($el, $lay['hide'], true);
                $row[] = ['text' => ($shown ? '✅ ' : '🚫 ') . $p['seEl' . ucfirst($el)], 'callback_data' => "salay|{$lang}|tg_{$el}", 'style' => $shown ? 'success' : 'danger'];
            }
            $rows[] = $row;
        }
        // the logo and the text: each button turns to the next choice
        $cycle = ['size' => ['seSize', ['sm' => 'seSizeSm', 'md' => 'seSizeMd', 'lg' => 'seSizeLg', 'xl' => 'seSizeXl']],
            'shape' => ['seShape', ['squircle' => 'seShapeSquircle', 'circle' => 'seShapeCircle', 'square' => 'seShapeSquare']],
            'stageAlign' => ['seStageAlign', ['center' => 'seAlignCenter', 'start' => 'seAlignStart', 'end' => 'seAlignEnd']],
            'align' => ['seTextAlign', ['center' => 'seAlignCenter', 'start' => 'seAlignStart']]];
        $btns = [];
        foreach ($cycle as $field => [$title, $names]) {
            $btns[] = ['text' => $p[$title] . ': ' . $p[$names[$lay[$field]]], 'callback_data' => "salay|{$lang}|cy_{$field}", 'style' => 'primary'];
        }
        foreach (array_chunk($btns, 2) as $r) {
            $rows[] = $r;
        }
        $rows[] = [['text' => $tb['saLookPreview'], 'url' => subapp_preview_link(subapp_look($lang), $lang)], ['text' => '🔁 ' . $p['seResetLayout'], 'callback_data' => "salay|{$lang}|reset", 'style' => 'danger']];
        $rows[] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_group|{$lang}|subapps", 'style' => 'danger']];
        $rows[] = [['text' => $tb['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return [strtr($tb['saLayCaption'], ['{lang}' => $tb['langs'][$lang] ?? $lang]), json_encode(['inline_keyboard' => $rows])];
    }
    // 🔗 the apps' links: the list of apps ($appId '') or one app's screen
    function subapp_links_screen($lang, $appId = '')
    {
        global $textbotlang;
        $tb = $textbotlang['bottext'];
        $p = $textbotlang['panel'];
        $mine = subapp_links($lang);
        $apps = subapp_apps();
        $names = ['play' => 'seLinkPlay', 'github' => 'seLinkGithub', 'ios' => 'seLinkIos', 'site' => 'seLinkSite'];
        $rows = [];
        $app = null;
        foreach ($apps as $a) {
            if ($a['id'] === $appId) {
                $app = $a;
            }
        }
        if ($app === null) {
            foreach (array_chunk($apps, 2) as $pair) {
                $rows[] = array_map(fn($a) => ['text' => '📱 ' . $a['name'], 'callback_data' => "salinks|{$lang}|{$a['id']}", 'style' => empty($mine[$a['id']]) ? 'primary' : 'success'], $pair);
            }
            $rows[] = [['text' => '🔁 ' . $p['seResetLayout'], 'callback_data' => "salinks|{$lang}|reset", 'style' => 'danger']];
            $rows[] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_group|{$lang}|subapps", 'style' => 'danger']];
            $rows[] = [['text' => $tb['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
            return [strtr($tb['saLinksCaption'], ['{lang}' => $tb['langs'][$lang] ?? $lang]), json_encode(['inline_keyboard' => $rows])];
        }
        $eff = array_column(subapp_apps_for($lang), null, 'id')[$appId];
        $lines = '';
        foreach ($names as $kind => $tk) {
            $o = $mine[$appId][$kind] ?? null;
            $state = $o === null ? $tb['saLinkDefault'] : ($o === '-' ? $tb['saLinkNone'] : $tb['saLinkChanged']);
            $lines .= '• <b>' . $p[$tk] . '</b> (' . $state . '): ' . ($eff[$kind] !== '' ? '<code>' . htmlspecialchars($eff[$kind]) . '</code>' : '—') . "\n";
            $rows[] = [
                ['text' => '✏️ ' . $p[$tk], 'callback_data' => "salinkedit|{$lang}|{$appId}|{$kind}", 'style' => $o === null ? 'primary' : 'success'],
                ['text' => '↩️ ' . $tb['saLinkDefault'], 'callback_data' => "salinkset|{$lang}|{$appId}|{$kind}|d"],
                ['text' => '🚫', 'callback_data' => "salinkset|{$lang}|{$appId}|{$kind}|n"],
            ];
        }
        $rows[] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "salinks|{$lang}", 'style' => 'danger']];
        $rows[] = [['text' => $tb['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return [strtr($tb['saLinkAppCaption'], ['{app}' => $app['name'], '{lang}' => $tb['langs'][$lang] ?? $lang, '{links}' => $lines]), json_encode(['inline_keyboard' => $rows])];
    }
    // every text the app-opening web page (subapp.php) shows - they live in the
    // same 🎨 registry as the bot's messages but are page text, not messages
    function subapp_page_keys()
    {
        $keys = [];
        foreach (['Opening', 'Button', 'Hint', 'Download', 'Error', 'Service', 'MissingTitle', 'Missing', 'Retry', 'Opened',
            'StoreCaption', 'StoreGoogle', 'StoreGithub', 'StoreApple', 'StoreSite', 'NoPlatform',
            'DownloadingTitle', 'Downloading', 'Step1', 'Step2', 'Step3', 'Back'] as $k) {
            $keys[] = 'users.subapps.page' . $k;
        }
        return $keys;
    }
    // the list's apps in its buttons' order - each one's genbtn kb number,
    // the id its link carries, its button's text (users.subapps.*), and where
    // to get it on each kind of phone ('' = not there). 5 is the list's 🔙
    // (subapp_back_idx), so an app added later takes the next free number and
    // every button keeps the look its admin gave it
    function subapp_apps()
    {
        // 'play' Google Play, 'github' the latest release there (the app's own
        // builds, for one that is not on Google Play), 'ios' the App Store and
        // 'site' the app's own download page - '' where it has none. 'icon' is
        // its file in subapp_assets/icons and 'accent' / 'accent2' the colours
        // of its glow on the page it opens (subapp.php)
        return [
            0 => ['id' => 'v2rayng', 'name' => 'v2rayNG', 'text' => 'appV2rayng', 'icon' => 'v2rayng', 'accent' => '#2467b8', 'accent2' => '#5aa9ff',
                'play' => '', 'github' => 'https://github.com/2dust/v2rayNG/releases/latest', 'ios' => '', 'site' => ''],
            1 => ['id' => 'hiddify', 'name' => 'Hiddify', 'text' => 'appHiddify', 'icon' => 'hiddify', 'accent' => '#3f57d8', 'accent2' => '#8aa2ff',
                'play' => 'https://play.google.com/store/apps/details?id=app.hiddify.com', 'github' => 'https://github.com/hiddify/hiddify-app/releases/latest', 'ios' => 'https://apps.apple.com/app/id6596777532', 'site' => ''],
            2 => ['id' => 'v2box', 'name' => 'v2Box', 'text' => 'appV2box', 'icon' => 'v2box', 'accent' => '#0f766e', 'accent2' => '#34d3b4',
                'play' => 'https://play.google.com/store/apps/details?id=dev.hexasoftware.v2box', 'github' => '', 'ios' => 'https://apps.apple.com/app/id6446814690', 'site' => ''],
            3 => ['id' => 'streisand', 'name' => 'Streisand', 'text' => 'appStreisand', 'icon' => 'streisand', 'accent' => '#c026a3', 'accent2' => '#38bdf8',
                'play' => '', 'github' => '', 'ios' => 'https://apps.apple.com/app/id6450534064', 'site' => ''],
            4 => ['id' => 'happ', 'name' => 'Happ', 'text' => 'appHapp', 'icon' => 'happ', 'accent' => '#4b5d78', 'accent2' => '#94a3b8',
                'play' => 'https://play.google.com/store/apps/details?id=com.happproxy', 'github' => '', 'ios' => 'https://apps.apple.com/app/id6504287215', 'site' => 'https://www.happ.su/'],
            6 => ['id' => 'karing', 'name' => 'Karing', 'text' => 'appKaring', 'icon' => 'karing', 'accent' => '#5b3df5', 'accent2' => '#22c7e8',
                'play' => '', 'github' => 'https://github.com/KaringX/karing/releases/latest', 'ios' => 'https://apps.apple.com/app/id6472431552', 'site' => 'https://karing.app/download'],
        ];
    }
    // the list's 🔙 بازگشت به منوی قبلی (genbtn kb)
    function subapp_back_idx()
    {
        return 5;
    }
    // the address that opens the app with the subscription added
    function subapp_deep_link($appId, $sub, $name)
    {
        $enc = rawurlencode((string) $sub);
        $n = rawurlencode((string) $name);
        $links = [
            'v2rayng' => "v2rayng://install-sub?name={$n}&url={$enc}",
            'hiddify' => "hiddify://import/{$sub}#{$n}",
            'v2box' => "v2box://install-sub?url={$enc}&name={$n}",
            'streisand' => "streisand://import/{$sub}#{$n}",
            'happ' => "happ://add/{$sub}",
            'karing' => "karing://install-config?url={$enc}&name={$n}",
        ];
        return $links[$appId] ?? '';
    }
    // an app's button: a link to subapp.php naming the service and the app,
    // signed with the bot's token - the subscription itself never travels in
    // it, and a link the bot did not make opens nothing
    function subapp_sig($invoiceId, $appId)
    {
        global $APIKEY;
        return substr(hash_hmac('sha256', "subapp|{$invoiceId}|{$appId}", (string) $APIKEY), 0, 20);
    }
    function subapp_link($invoiceId, $appId)
    {
        global $domainhosts;
        return "https://{$domainhosts}/subapp.php?" . http_build_query(['i' => $invoiceId, 'a' => $appId, 's' => subapp_sig($invoiceId, $appId)]);
    }
    // whether the list still has an app to show
    function subapp_any_app($lang, $tx)
    {
        $key = genbtn_alias_to_key('kb');
        foreach (genbtn_defs('kb', $tx) as $idx => $d) {
            if (isset(subapp_apps()[$idx]) && !genbtn_is_hidden($d, genbtn_override($lang, $key, $idx))) {
                return true;
            }
        }
        return false;
    }
    // the rows on top of a service's screen, or of a message that delivers one:
    // 🌐 (a link to $sub) and 📲 (the app list), as this tab has them - the same
    // pair in every one of those places - [] when the panel gives the
    // subscription no address. $keep: 📲 leaves the message it is under where
    // it is (the purchase message carries the config - it must not go)
    function subapp_entry_rows($lang, $tx, $sub, $invoiceId, $keep = false)
    {
        if (strpos((string) $sub, 'http') !== 0) {
            return [];
        }
        $alias = 'gb';
        $key = genbtn_alias_to_key($alias);
        $btns = [];
        foreach (genbtn_defs($alias, $tx) as $idx => $d) {
            $ov = genbtn_override($lang, $key, $idx);
            // 📲 only while its list has an app left on it
            if (genbtn_is_hidden($d, $ov) || ($idx === 1 && !subapp_any_app($lang, $tx))) {
                continue;
            }
            $b = genbtn_render($d, $ov, "subapps_{$invoiceId}" . ($keep ? '_k' : ''));
            if ($idx === 0) {
                unset($b['callback_data']);
                $b['url'] = (string) $sub;
            }
            $btns[$idx] = $b;
        }
        return genbtn_group_rows($alias, $lang, $btns, $tx);
    }
    // 📲's screen: [text, keyboard] - the caption, each app a link to
    // subapp.php, ↪️ back to the service's own screen. One screen for every
    // kind of service
    function subapp_list_screen($lang, $tx, array $inv)
    {
        $alias = 'kb';
        $key = genbtn_alias_to_key($alias);
        $apps = subapp_apps();
        $btns = [];
        foreach (genbtn_defs($alias, $tx) as $idx => $d) {
            $ov = genbtn_override($lang, $key, $idx);
            if (genbtn_is_hidden($d, $ov)) {
                continue;
            }
            $b = genbtn_render($d, $ov, 'product_' . $inv['id_invoice']);
            if (isset($apps[$idx])) {
                unset($b['callback_data']);
                $b['url'] = subapp_link($inv['id_invoice'], $apps[$idx]['id']);
            }
            $btns[$idx] = $b;
        }
        $text = strtr($tx['users']['subapps']['listBuy'], ['{username}' => htmlspecialchars((string) $inv['username'])]);
        return [$text, json_encode(['inline_keyboard' => genbtn_group_rows($alias, $lang, $btns, $tx)])];
    }
}
