            ['text' => ($color === 'success' ? '✅ ' : '') . '🟢 سبز', 'callback_data' => "tpbpc:{$lang}:{$key}:success", 'style' => 'success'],
            ['text' => ($color === 'danger' ? '✅ ' : '') . '🔴 قرمز', 'callback_data' => "tpbpc:{$lang}:{$key}:danger", 'style' => 'danger'],
