        if (intval($c['expiry'] ?? 0) > 0 && time() >= intval($c['expiry'])) {
            return 'expired';
        }
        $limit = intval($c['limitTotal'] ?? 0);
        if ($limit > 0 && topup_disc_code_used_count($c['code']) >= $limit) {
            return 'exhausted';
        }
