        $tabTexts = function_exists('lang_tab_texts') ? lang_tab_texts($lang) : $textbotlang;
        $tier = $tiers[$index];
        $look = volumepct_tier_look($tier, $lang);
        $pct = intval($tier['pct'] ?? 0);
        $hasCustomText = !empty($tier['text'][$lang]);
        $curStyle = (isset($look['style']) && in_array($look['style'], ['primary', 'success', 'danger'], true)) ? $look['style'] : 'primary';
        $curPos = (isset($look['pos']) && $look['pos'] === 'left') ? 'left' : 'right';
        $curSimple = !empty($look['simple']);
        $hasSticker = !empty($tier['sticker'][$lang]);
        $hasEmoji = !empty($look['emoji']) || !empty($look['emojiIcon']);
        $previewKb = json_decode(volumepct_tier_kb($index, $lang, $tabTexts, 0, true), true);
        $previewBtn = $previewKb['inline_keyboard'][0][0];
        // only a preview: white, so it does not look like a tool, and a tap
        // says so (its colour is the one ticked ✅ below)
        unset($previewBtn['style']);
        $previewBtn['callback_data'] = 'volpct|prev';
        $isHidden = !empty($look['hidden']);
        if ($isHidden) {
            $previewBtn['text'] = '🚫 ' . $previewBtn['text'];
        }

        $kind = volumepct_tier_kind($tier);
        $meta = volumepct_kind_meta($kind);
        $defaultCaption = volumepct_tier_default_text($tabTexts, $kind);
        $title = $meta['single'] ? $meta['title'] : sprintf($meta['title'], $pct);
        // the caption as the customer gets it - its premium emoji and its
        // formatting rendered, not shown as tags
        $quote = function ($s) {
            return "<blockquote>" . str_replace(['<blockquote>', '</blockquote>'], '', (string) $s) . "</blockquote>\n";
        };
        $info = "{$meta['icon']} <b>{$title}</b>" . mainmenu_tab_note($lang) . "\n➖➖➖➖➖➖➖➖➖➖\n";
        $info .= "✏️ کپشن: " . ($hasCustomText ? "سفارشی ✅" : "پیش‌فرض") . "\n";
        if ($hasCustomText) {
            $info .= "📋 <b>متن پیش‌فرض:</b>\n" . $quote($defaultCaption);
            $info .= "👁 <b>متن فعلی:</b>\n" . $quote($tier['text'][$lang]);
        } else {
            $info .= "👁 <b>متن فعلی</b> (همون پیش‌فرض):\n" . $quote($defaultCaption);
        }
        $info .= "🖼 استیکر: " . ($hasSticker ? "ست شده ✅" : "ندارد ❌") . "\n";
        if ($isHidden) {
            $info .= "🚫 دکمه مخفیه - این پیام بدون دکمه فرستاده می‌شه.\n";
        }
        $info .= $meta['single'] ? "🌐 کپشن، استیکر و متن و ظاهر دکمه (رنگ، ایموجی، جا) مال همین زبانه.\n" : "🔗 آستانه برای همه‌ی زبان‌ها یکیه؛ کپشن، استیکر و متن و ظاهر دکمه (رنگ، ایموجی، جا) مال همین زبانه.\n";
        $info .= "➖➖➖➖➖➖➖➖➖➖\n👁 پیش‌نمایش دکمه (سفید = فقط برای دیدن؛ رنگش همونیه که پایین ✅ خورده) 👇";

        $kb = ['inline_keyboard' => []];
        // a one-off notice has no list screen above it, so its switch is here
        if ($meta['single']) {
            $kb['inline_keyboard'][] = notice_switch_row("volpct.{$kind}", $lang, "volpct|sw|{$lang}|{$kind}");
        }
        $kb['inline_keyboard'][] = [$previewBtn];
        if (!$meta['single']) {
            $kb['inline_keyboard'][] = [['text' => sprintf($meta['thresholdBtn'], $pct), 'callback_data' => "volpct|pct|{$lang}|{$index}", 'style' => 'primary']];
        }
        $kb['inline_keyboard'][] = [['text' => '✏️ ویرایش کپشن', 'callback_data' => "volpct|text|{$lang}|{$index}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [['text' => '🖼 استیکر', 'callback_data' => "volpct|sticker|{$lang}|{$index}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [['text' => '✏️ متن دکمه', 'callback_data' => "volpct|btntext|{$lang}|{$index}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [
            ['text' => ($curStyle === 'primary' ? '✅ ' : '') . '🔵 آبی', 'callback_data' => "volpct|style|{$lang}|{$index}|primary", 'style' => 'primary'],
            ['text' => ($curStyle === 'success' ? '✅ ' : '') . '🟢 سبز', 'callback_data' => "volpct|style|{$lang}|{$index}|success", 'style' => 'success'],
            ['text' => ($curStyle === 'danger' ? '✅ ' : '') . '🔴 قرمز', 'callback_data' => "volpct|style|{$lang}|{$index}|danger", 'style' => 'danger'],
        ];
        $kb['inline_keyboard'][] = [['text' => ($hasEmoji ? '✅ ' : '') . '💎 ایموجی دکمه', 'callback_data' => "volpct|emoji|{$lang}|{$index}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [['text' => ($curSimple ? '✅ ' : '') . '🎭 حالت ساده (بدون ایموجی)', 'callback_data' => "volpct|simple|{$lang}|{$index}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [
            ['text' => ($curPos === 'right' ? '✅ ' : '') . '➡️ راست', 'callback_data' => "volpct|pos|{$lang}|{$index}|right", 'style' => 'primary'],
            ['text' => ($curPos === 'left' ? '✅ ' : '') . '⬅️ چپ', 'callback_data' => "volpct|pos|{$lang}|{$index}|left", 'style' => 'primary'],
        ];
        $kb['inline_keyboard'][] = [[
            'text' => $isHidden ? '👁 نمایش دادن دکمه' : '🚫 مخفی کردن دکمه',
            'callback_data' => "volpct|hide|{$lang}|{$index}",
            'style' => $isHidden ? 'success' : 'danger',
        ]];
        $kb['inline_keyboard'][] = [['text' => '🔁 ریست کپشن و دکمه', 'callback_data' => "volpct|rst|{$lang}|{$index}", 'style' => 'danger']];
        if (!$meta['single']) {
            $kb['inline_keyboard'][] = [['text' => '🗑 حذف این آستانه', 'callback_data' => "volpct|del|{$lang}|{$index}", 'style' => 'danger']];
        }
        // the one-off notices sit on the hub itself; a threshold goes back to its list
        $backCb = $meta['single'] ? "volpct|hub|{$lang}" : "volpct|sec|{$lang}|{$kind}";
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت', 'callback_data' => $backCb, 'style' => 'danger']];
        return [$info, json_encode($kb)];
    }
}
// Where the 🔙 of a config-display hub (ترتیب و رنگ دکمه‌های دریافت کانفیگ) goes.
// The hub is reached from two places - the message item's own screen, and the
// 📌 نحوه‌ی نمایش کانفیگ panel screen - and from the hub the admin also goes on
// into an element's editor and back, or flips the column order, which draws the
// hub again. Those later screens carry no memory of the way in, so «back» fell
// to the message item every time, whatever the admin had come from. The way in
// is kept here, per admin and per kind (usertest / buy / affrw), set by each
// entry and read by every later draw. A file rather than the user's
// Processing_value: the element editor's text step wipes that.
if (!function_exists('cfgcol_back_set')) {
    // 🎨 screens several others open - a caption that is in its own section
    // and on a gateway's screen too, one button group under two messages, the
    // config-button hub - go 🔙 to the one they were opened from. Each 🎨
    // message remembers the screen it shows (by its message id); opening one
    // of those screens from another notes that one as its way back. Its own
    // sub-screens and back buttons never do (bt_origin_track, admin.php).
    function bt_origin_file($adminId)
    {
        return __DIR__ . '/storage/bt_origin_' . preg_replace('/\D/', '', (string) $adminId) . '.json';
    }
    function bt_origin_load($adminId)
    {
        $m = json_decode((string) @file_get_contents(bt_origin_file($adminId)), true);
        return ['s' => (array) ($m['s'] ?? []), 'o' => (array) ($m['o'] ?? [])];
    }
    function bt_origin_save($adminId, array $m)
    {
        // the last screens only - an old message's is never asked for again
        $m['s'] = array_slice($m['s'], -40, null, true);
        $f = bt_origin_file($adminId);
        if (!is_dir(dirname($f))) {
            @mkdir(dirname($f), 0775, true);
        }
        @file_put_contents($f, json_encode($m, JSON_UNESCAPED_UNICODE), LOCK_EX);
    }
    // where $target (its opening callback) was opened from, or null - then
    // the screen's own back applies
    function bt_origin_get($adminId, $target)
    {
        $v = bt_origin_load($adminId)['o'][(string) $target] ?? null;
        return is_string($v) && $v !== '' ? $v : null;
    }
    // The 🎨 screens a message can show and be opened again by - not the
    // actions on them, which only redraw the same screen
    function bt_origin_is_screen($data)
    {
        return (bool) preg_match('/^(bt_group\|[a-z]{2}\|\w+$|bt_edit\||gbs\|hub\||btact\|cfgcolbuy\||btact\|cfgcol\||topupgw:[a-z]{2}:[a-z0-9]+$|topupgwlist:|topupset:|cfgdeliv\|(list|p)\||volpct\|(hub|sec)\||(status|buy|test|ref)btn\|list\||bt_btnsettings\||btnset_open:|chnbtn_hub:|help_lang:|bt_lang:|btact\|back\|)/', (string) $data);
    }
    // the screens that go back the way they were opened
    function bt_origin_is_target($data)
    {
        return (bool) preg_match('/^(bt_edit\|[a-z]{2}\|.+|bt_group\|[a-z]{2}\|subapps|gbs\|hub\|[a-z]{2}\|\w+(\|u)?|btact\|cfgcolbuy\|[a-z]{2}\|.+|(status|buy|test|ref)btn\|list\|[a-z]{2})$/', (string) $data);
    }
    // a tap on a 🎨 message: notes the way back of the screen it opens, and the
    // screen the message shows from now on. $keyboard is the message's own
    // (the one the tapped button was on).
    function bt_origin_track($adminId, $messageId, $data, array $keyboard)
    {
        if (!bt_origin_is_screen($data) || (int) $messageId <= 0) {
            return;
        }
        $m = bt_origin_load($adminId);
        $from = (string) ($m['s'][(string) $messageId] ?? '');
        if (bt_origin_is_target($data)) {
            // a 🔙 that leads to it: it is this screen's own parent, not a
            // place to come back to
            $isBack = false;
            $found = false;
            foreach ($keyboard as $row) {
                foreach ((array) $row as $btn) {
                    if (($btn['callback_data'] ?? null) === $data) {
                        $found = true;
                        if (preg_match('/^\s*(🔙|↩️)/u', (string) ($btn['text'] ?? ''))) {
                            $isBack = true;
                        }
                    }
                }
            }
            // from 🎨's own list it is its usual way in: its own back
            $fromHome = (bool) preg_match('/^(btact\|back\||bt_lang:)/', $from);
            if ($from !== '' && $from !== $data && $found && !$isBack && !$fromHome) {
                $m['o'][$data] = $from;
            } elseif ($from === '' || !$found || $fromHome) {
                // or opened from a screen nothing is known of
                unset($m['o'][$data]);
            }
        }
        $m['s'][(string) $messageId] = (string) $data;
        bt_origin_save($adminId, $m);
    }
    function cfgcol_back_file($adminId)
    {
        return __DIR__ . '/storage/cfgcol_back_' . preg_replace('/\D/', '', (string) $adminId) . '.json';
    }
    // $cb null: reached from the message item itself (the hub's own default)
    function cfgcol_back_set($adminId, $kind, $cb)
    {
        $f = cfgcol_back_file($adminId);
        $m = json_decode((string) @file_get_contents($f), true);
        $m = is_array($m) ? $m : [];
        if ($cb === null) {
            unset($m[$kind]);
        } else {
            $m[$kind] = (string) $cb;
        }
        if (!is_dir(dirname($f))) {
            @mkdir(dirname($f), 0775, true);
        }
        @file_put_contents($f, json_encode($m), LOCK_EX);
    }
    function cfgcol_back_get($adminId, $kind)
    {
        $m = json_decode((string) @file_get_contents(cfgcol_back_file($adminId)), true);
        $v = is_array($m) ? ($m[$kind] ?? null) : null;
        return is_string($v) && $v !== '' ? $v : null;
    }
    // the hub drawn again (order flipped, back from an element's editor), with
    // the way in it was opened by
    function cfgcol_hub_render($textbotlang, $lang, $kind)
    {
        global $from_id;
        $back = cfgcol_back_get($from_id, $kind);
        if ($back === null) {
            $def = [
                'usertest' => ['users.usertest.selectUsernamePrompt', 'users.status.getConfigHint'],
                'buy' => ['users.status.getConfigHintBuy', 'users.status.getConfigHintBuy'],
                'affrw' => [null, 'users.affiliates.rewardConfigHint'],
            ][$kind];
            return config_col_order_payload($textbotlang, $lang, $def[0], $kind === 'affrw' ? "cfgdeliv|list|{$lang}|r" : null, $def[1], $kind);
        }
        return config_col_order_payload($textbotlang, $lang, null, $back, $kind === 'affrw' ? 'users.affiliates.rewardConfigHint' : null, $kind);
    }
}
if (!function_exists('config_col_order_payload')) {
    // controls which column comes first on the per-service config-list screen
    // (keyboard_config() in keyboard.php): the "دریافت کانفیگ" button, or the
    // config's display name - shows a live 2-row preview so the admin can see
    // exactly what the header + a sample row will look like before saving
    function config_col_order_payload($textbotlang, $originLang = null, $originKey = null, $backCallback = null, $captionKey = 'users.status.getConfigHint', $kind = 'usertest')
    {
        $lang = $originLang ?? 'fa';
