        $kb['inline_keyboard'][] = [[
            'text' => ($nameFirst ? '✅ ' : '') . 'نام کانفیگ، بعد دکمه‌ی دریافت',
            'callback_data' => $cbNameFirst,
            'style' => ($nameFirst ? 'success' : 'primary'),
