        $sec = $data[$lang][$kind] ?? [];
        return [
            'order' => is_array($sec['order'] ?? null) ? $sec['order'] : [],
            'width' => is_array($sec['width'] ?? null) ? $sec['width'] : [],
            'emoji' => is_array($sec['emoji'] ?? null) ? $sec['emoji'] : [],
            'emojiIcon' => is_array($sec['emojiIcon'] ?? null) ? $sec['emojiIcon'] : [],
            'emojiSimple' => !empty($sec['emojiSimple']),
            'color' => is_array($sec['color'] ?? null) ? $sec['color'] : [],
            'rename' => is_array($sec['rename'] ?? null) ? $sec['rename'] : [],
            // {key => true} for the buttons the admin has switched off in
            // 📐 چیدمان. A hide is a display choice only: the item itself stays
            // exactly as it is in the database, and its own on/off switch
            // (a panel's status, a gateway's toggle) is untouched.
            'hidden' => is_array($sec['hidden'] ?? null) ? $sec['hidden'] : [],
        ];
    }
}
if (!function_exists('help_layout_visible')) {
    // drops the keys the admin hid, for the customer-facing keyboards only -
    // every admin screen keeps listing them (marked 🚫) or there would be no way
    // back to visible.
    //
    // If EVERY item ends up hidden the hide list is ignored instead of shipping
    // a keyboard with nothing on it. The editor already refuses to hide the last
    // visible button, so this only catches the case where the items themselves
    // changed underneath a saved list (a panel deleted, a gateway switched off).
    function help_layout_visible(array $orderedKeys, array $section)
    {
        $hidden = $section['hidden'] ?? [];
        if (!is_array($hidden) || empty($hidden)) {
            return $orderedKeys;
        }
        $out = [];
        foreach ($orderedKeys as $key) {
            if (!empty($hidden[(string) $key])) {
                continue;
            }
            $out[] = $key;
        }
        return empty($out) ? $orderedKeys : $out;
    }
}
if (!function_exists('help_layout_emoji_prefix')) {
    // resolves what to show for one item's emoji: a plain-text prefix to
    // prepend to its label, and/or a premium icon_custom_emoji_id to set on
    // the button - never both. "simple mode" forces the icon off (prefix
    // stays empty too, since a premium emoji has no plain-text fallback
    // glyph of its own).
    function help_layout_emoji_prefix($key, array $section)
    {
        $iconId = $section['emojiIcon'][$key] ?? '';
        if ($iconId !== '' && empty($section['emojiSimple'])) {
            return ['prefix' => '', 'icon' => $iconId];
        }
        $emojiText = $section['emoji'][$key] ?? '';
        if ($emojiText !== '') {
            return ['prefix' => $emojiText . ' ', 'icon' => ''];
        }
        return ['prefix' => '', 'icon' => ''];
    }
}
if (!function_exists('help_layout_set_section')) {
    function help_layout_set_section($lang, $kind, array $section)
    {
        $data = help_layout_get();
        if (!isset($data[$lang]) || !is_array($data[$lang])) {
            $data[$lang] = [];
        }
        $data[$lang][$kind] = $section;
        help_layout_save($data);
    }
}
if (!function_exists('help_layout_apply_order')) {
    // reorders $items (flat list of string keys) per a stored order list,
    // appending any items not yet in that order at the end (first-seen order)
    function help_layout_apply_order(array $items, array $order)
    {
        // compare by string value (PHP normalizes numeric-string array keys
        // to int, so tutorial-id items may arrive as int while the stored
        // order list, JSON-decoded, keeps its values as strings)
        $ordered = [];
        $usedIdx = [];
        foreach ($order as $key) {
            foreach ($items as $idx => $item) {
                if (isset($usedIdx[$idx])) {
                    continue;
                }
                if ((string) $item === (string) $key) {
                    $ordered[] = $item;
                    $usedIdx[$idx] = true;
                    break;
                }
            }
        }
        foreach ($items as $idx => $item) {
            if (!isset($usedIdx[$idx])) {
                $ordered[] = $item;
                $usedIdx[$idx] = true;
            }
        }
        return $ordered;
    }
}
if (!function_exists('help_layout_items')) {
    // returns [key => label]. 'tutorials': key == tutorial id (stable,
    // language-independent), label == resolved name for $lang.
    // 'categories': key == the base (fa) category string (stable identity —
    // this is also what routes end-user taps, see keyboard.php's
    // "helpctgoryـ{category}" callback_data), label == resolved per-language
    // category text. Keying categories by the base string (not the resolved
    // label) matters: if the label were the key, re-translating a category's
    // display name would silently orphan any saved order/width/emoji for it.
    function help_layout_items($lang, $kind)
    {
        if ($kind === 'panel' || $kind === 'product' || $kind === 'category') {
            return help_layout_items_commerce($lang, $kind);
        }
        if ($kind === 'langpick') {
            // The five buttons on the language picker - the screen the bot shows
            // before the user has a language at all. Keyed by language code so a
            // rename never orphans the styling saved for it.
            //
            // Only the languages the shop actually offers are listed, the same
            // way 'gateway' lists only live gateways: styling a button nobody
            // will ever see is noise. The picker itself filters the same list.
            $lp_names = ['fa' => '🇮🇷 فارسی', 'en' => '🇬🇧 English'];
            $lp_section = help_layout_section($lang, 'langpick');
            $out = [];
            foreach (lang_switch_enabled_langs() as $code) {
                if (isset($lp_names[$code])) {
                    $out[$code] = $lp_section['rename'][$code] ?? $lp_names[$code];
                }
            }
            return $out;
        }
        if ($kind === 'gateway') {
            // only called from admin.php's btnstyle_* screens, so gateway_registry()
            // is guaranteed loaded; $lang may differ from the admin's own display
            // language, so its OWN translation file is loaded fresh rather than
            // assuming the caller's $textbotlang matches
            if (!function_exists('gateway_registry') || !function_exists('gateway_applicable_for_lang') || !function_exists('gateway_allowed_for_lang') || !function_exists('gateway_globally_on')) {
                return [];
            }
            $gwLangFile = __DIR__ . "/lang/$lang.php";
            $gwTextbotlang = is_file($gwLangFile) ? (require $gwLangFile) : [];
            $gwSection = help_layout_section($lang, 'gateway');
            $items = [];
            foreach (gateway_registry($gwTextbotlang) as $key => $label) {
                if (!gateway_applicable_for_lang($key, $lang)) {
                    continue;
                }
                if (!gateway_allowed_for_lang($key, $lang) || !gateway_globally_on($key)) {
                    continue;
                }
                $items[$key] = $gwSection['rename'][$key] ?? $label;
            }
            return $items;
        }
        $rows = select("help", "*", null, null, "fetchAll");
        if (!is_array($rows)) {
            return [];
        }
        $items = [];
        foreach ($rows as $row) {
            $view = help_resolve_lang($row, $lang);
            if ($kind === 'categories') {
                $faCat = trim((string) ($row['category'] ?? ''));
                if ($faCat === '' || $faCat === '0') {
                    continue;
                }
                if (!isset($items[$faCat])) {
                    $label = trim((string) ($view['category'] ?? ''));
                    $items[$faCat] = ($label !== '') ? $label : $faCat;
                }
            } else {
                $key = (string) $row['id'];
                $items[$key] = $view['name'];
            }
        }
        return $items;
    }
}
if (!function_exists('help_button_icon_set')) {
    // a 📚 tutorial's or category's button gets a premium emoji on one tab - what
    // a premium emoji at the start of a name the admin sent becomes (🎨 ظاهر
    // دکمه‌های آموزش shows and resets it like one set there)
    function help_button_icon_set($lang, $kind, $key, $icon)
    {
        $section = help_layout_section($lang, $kind);
        $section['emojiIcon'][(string) $key] = (string) $icon;
        unset($section['emoji'][(string) $key]);
        help_layout_set_section($lang, $kind, $section);
    }
}
if (!function_exists('help_layout_items_commerce')) {
    // same [key => label] contract as help_layout_items(), for the
    // end-user-facing panel/product/category buttons (button styling: order,
    // width, emoji, color, custom rename - see the "🎨 ..." button-styling
    // hub in admin.php). key is always the item's stable, language- and
    // rename-independent identity: code_panel / product id / category id.
    // label is the real name unless a per-language rename override is set.
    function help_layout_items_commerce($lang, $kind)
    {
        $section = help_layout_section($lang, $kind);
        $items = [];
        if ($kind === 'panel') {
            $rows = select("marzban_panel", "*", null, null, "fetchAll");
            if (!is_array($rows)) {
                return [];
            }
            foreach ($rows as $row) {
                $key = (string) $row['code_panel'];
                $items[$key] = $section['rename'][$key] ?? $row['name_panel'];
            }
        } elseif ($kind === 'product') {
            $rows = select("product", "*", null, null, "fetchAll");
            if (!is_array($rows)) {
                return [];
            }
            foreach ($rows as $row) {
                $key = (string) $row['id'];
                $items[$key] = $section['rename'][$key] ?? $row['name_product'];
            }
            // 🧩 حجم دلخواه: its entry button sits among the plans (cvol.php)
            if (function_exists('cvol_layout_on') && cvol_layout_on()) {
                $items['cvol'] = $section['rename']['cvol'] ?? cvol_layout_label($lang);
            }
        } else {
            $rows = select("category", "*", null, null, "fetchAll");
            if (!is_array($rows)) {
                return [];
            }
            foreach ($rows as $row) {
                $key = (string) $row['id'];
                $items[$key] = $section['rename'][$key] ?? $row['remark'];
            }
        }
        return $items;
    }
}
if (!function_exists('help_layout_chunk_rows')) {
    // groups an ordered list of prebuilt inline-keyboard button arrays into
    // rows, pairing adjacent "half"-width items two-per-row and keeping
    // "full"-width items (the default) on their own row
    function help_layout_chunk_rows(array $orderedKeys, array $buttonsByKey, array $widthMap)
    {
        $rows = [];
        $pending = null;
        foreach ($orderedKeys as $key) {
            if (!isset($buttonsByKey[$key])) {
                continue;
            }
            $width = $widthMap[$key] ?? 'full';
            if ($width === 'half') {
                if ($pending === null) {
                    $pending = $buttonsByKey[$key];
                } else {
                    $rows[] = [$pending, $buttonsByKey[$key]];
                    $pending = null;
                }
            } else {
                if ($pending !== null) {
                    $rows[] = [$pending];
                    $pending = null;
                }
                $rows[] = [$buttonsByKey[$key]];
            }
        }
        if ($pending !== null) {
            $rows[] = [$pending];
        }
        return $rows;
    }
}

if (!function_exists('affrw_cfg')) {
    // 🎁 کانفیگ رایگان با دعوت. One set of settings per language (🌐 وضعیت
    // قابلیت‌ها (هر زبان) ← 👥 طرح‌های زیرمجموعه‌گیری), and the INVITER's
    // language decides: switched on for English, it never reaches a Persian
    // customer. 'since' is when it was switched on - only people who joined
    // after that count.
    function affrw_cfg($lang)
    {
        return [
            'on' => feature_setting_value('affrw_on', $lang, '0') === '1',
            'need' => max(1, (int) feature_setting_value('affrw_need', $lang, '3')),
            'gb' => max(0.01, (float) feature_setting_value('affrw_gb', $lang, '10')),
            'days' => max(1, (int) feature_setting_value('affrw_days', $lang, '1')),
            // 🚀 Mbps on a Rebecca panel, 0 = none
            'speed' => max(0, (float) feature_setting_value('affrw_speed', $lang, '0')),
            'panel' => (string) feature_setting_value('affrw_panel', $lang, ''),
            'mode' => feature_setting_value('affrw_mode', $lang, 'admin') === 'auto' ? 'auto' : 'admin',
            'since' => (int) feature_setting_value('affrw_since', $lang, '0'),
            // how many times one customer can earn it; after each, their
            // count starts again from zero
            'max' => max(1, (int) feature_setting_value('affrw_max', $lang, '1')),
        ];
    }
    // the panel the gift is made on; null when none is picked or it was deleted
    function affrw_panel($cfg)
    {
        if ($cfg['panel'] === '') {
            return null;
        }
        $p = select("marzban_panel", "*", "code_panel", $cfg['panel'], "select");
        return is_array($p) ? $p : null;
    }
    // on for this language: switched on, a panel to make it on, and the
    // referral section itself on
    function affrw_live($lang)
    {
        $cfg = affrw_cfg($lang);
        $setting = select("setting", "*", null, null, "select");
        if (!$cfg['on'] || affrw_panel($cfg) === null
            || feature_value('affiliatesstatus', $lang, $setting['affiliatesstatus'] ?? '') == "offaffiliates") {
            return null;
        }
        return $cfg;
    }
    // 🎨 ← 🛡 دسترسی و محدودیت‌های ادمین ← «🎁 کانفیگ رایگان با دعوت بدون
    // محدودیت»: one switch for the whole bot, like that screen's other two.
    // On, an admin gets the free config every time they open 👥 - no invites,
    // nobody's approval, whichever way it is delivered (affrw_admin_give) -
    // and their own invites skip 🛡's checks and approval too; up to the 🔁
    // allowance, like a customer, and reaching it switches it off
    // (affrw_admin_spent). Off, an admin is a customer like any other.
    function affrw_admin_free($uid)
    {
        $setting = select("setting", "*", null, null, "select");
        if ((string) ($setting['admin_affrw_unlimited'] ?? '0') !== '1') {
            return false;
        }
        return in_array((string) $uid, array_map('strval', (array) select("admin", "id_admin", null, null, "FETCH_COLUMN")), true);
    }
    // ...and the config itself: their language's 🎁 plan, made and sent the
    // way a customer gets it, so the admin sees exactly that. It counts
    // towards 🔁 چند بار like a customer's (affiliate_reward.times); nothing
    // once that is used up. False when the plan is off for their language,
    // the allowance is used up or the panel refused (the admin is told why).
    function affrw_admin_give($uid)
    {
        global $pdo;
        $u = select("user", "*", "id", (string) $uid, "select");
        $lang = is_array($u) ? ($u['lang'] ?? 'fa') : 'fa';
        $cfg = affrw_live($lang);
        if ($cfg === null) {
            return false;
        }
        $row = affrw_row($uid);
        if (affrw_used_up($row)) {
            return false;
        }
        $err = null;
        $panel = affrw_panel($cfg);
        $made = affrw_deliver($uid, $cfg, $panel, is_array($u) ? $u : ['username' => ''], payer_texts($uid), $lang, $cfg['need'], $err);
        if ($made === null) {
            sendmessage($uid, strtr(lang_tab_texts('fa')['Admin']['AffTest']['realFailed'], ['{msg}' => htmlspecialchars(json_encode($err, JSON_UNESCAPED_UNICODE))]), null, 'HTML');
            return false;
        }
        $times = affrw_times($row) + 1;
        // in the report group like a customer's, said to be an admin's own
        affrw_report_made($uid, $u, $cfg, $panel, $made, $lang, "\n\n" . lang_tab_texts('fa')['Admin']['AffReward']['reportAdmin'], $times);
        // no invitees behind it, so none of 🚪's to watch; a round of his
        // own invites that is under way keeps its status
        $done = $times >= $cfg['max'];
        if ($row === null) {
            $pdo->prepare("INSERT INTO affiliate_reward (user_id, lang, status, invites, since, time, times, id_invoice, members, left_ids, suspended) VALUES (?, ?, ?, 0, ?, ?, ?, ?, '[]', '[]', 0)")
                ->execute([(string) $uid, $lang, $done ? 'done' : 'open', time(), time(), $times, $made['id_invoice']]);
        } else {
            $pdo->prepare("UPDATE affiliate_reward SET lang = ?, times = ?, id_invoice = ?, time = ?, members = '[]', left_ids = '[]', suspended = 0 WHERE user_id = ?")
                ->execute([$lang, $times, $made['id_invoice'], time(), (string) $uid]);
            $pdo->prepare("UPDATE affiliate_reward SET status = ?, since = ? WHERE user_id = ? AND status IN ('open', 'rejected', 'done')")
                ->execute([$done ? 'done' : 'open', time(), (string) $uid]);
        }
        if ($done) {
            affrw_admin_spent($uid, $cfg);
        }
        return true;
    }
    // 🛡 an admin with no limit who has now had it as many times as 🔁 چند بار
    // allows: the switch goes off - it is one for every admin - and they are
    // told; their next 👥 says the allowance is used up, as a customer's does
    function affrw_admin_spent($uid, $cfg)
    {
        if (!affrw_admin_free($uid)) {
            return;
        }
        update("setting", "admin_affrw_unlimited", "0", null, null);
        clearSelectCache('setting');
        sendmessage($uid, strtr(lang_tab_texts('fa')['Admin']['AffReward']['adminSpent'], ['{max}' => $cfg['max']]), null, 'HTML');
    }
    // One row per customer who reached the count, and it is what makes the
    // gift once only: status pending (waiting for an admin), giving (being
    // made), done, or rejected. Also made here for a bot whose table.php has
    // not run since.
    function affrw_ensure_table()
    {
        static $done = false;
        global $pdo;
        if ($done) {
            return;
        }
        $done = true;
        $pdo->query("CREATE TABLE IF NOT EXISTS affiliate_reward (
            user_id VARCHAR(200) NOT NULL PRIMARY KEY,
            lang VARCHAR(10) NOT NULL,
            status VARCHAR(20) NOT NULL,
            invites INT NOT NULL DEFAULT 0,
            since INT NOT NULL DEFAULT 0,
            time INT NOT NULL DEFAULT 0,
            id_invoice VARCHAR(200) NULL)
            ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci");
        // times: rewards earned so far (status 'open' = the next round is
        // counting); members / left_ids / suspended: the invitees behind the
        // last one, and which of them left its verification channel
        addFieldToTable('affiliate_reward', 'times', null, 'INT NOT NULL DEFAULT 0');
        addFieldToTable('affiliate_reward', 'members', null, 'TEXT NULL');
        addFieldToTable('affiliate_reward', 'left_ids', null, 'TEXT NULL');
        addFieldToTable('affiliate_reward', 'suspended', null, 'INT NOT NULL DEFAULT 0');
        // user.first_name: the name the referral reports show next to an id
        // (index.php keeps it up to date) - empty until the user writes again
        addFieldToTable('user', 'first_name', null, 'VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL');
        // user.aff_rw: whose free-config count a customer is in - apart from
        // 💼's link (affiliates), each plan having its own 🛡 check. Everyone
        // counted before that was counted for both.
        try {
            $has = $pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'user' AND COLUMN_NAME = 'aff_rw'")->fetchColumn();
            if (!$has) {
                $pdo->exec("ALTER TABLE user ADD aff_rw VARCHAR(50) NULL");
                $pdo->exec("UPDATE user SET aff_rw = affiliates WHERE affiliates IS NOT NULL AND affiliates NOT IN ('', '0')");
            }
        } catch (Exception $e) {
            error_log("aff_rw: " . $e->getMessage());
        }
        // invoice.affrw: 1 = a free config (its own rules - ⚙️ قوانین اکانت),
        // 2 = one renewed since, a service like any other. affrw_end: when it
        // ended (for 🗑 X ساعت بعد). The ones made before are found by their
        // reward row, or by their name and price.
        try {
            $has = $pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'invoice' AND COLUMN_NAME = 'affrw'")->fetchColumn();
            if (!$has) {
                $pdo->exec("ALTER TABLE invoice ADD affrw TINYINT NOT NULL DEFAULT 0");
                $pdo->exec("UPDATE invoice SET affrw = 1 WHERE id_invoice IN (SELECT id_invoice FROM affiliate_reward WHERE id_invoice IS NOT NULL)");
                $names = [];
                foreach (['fa', 'en'] as $l) {
                    $names[] = (string) (lang_tab_texts($l)['users']['affiliates']['rewardServiceName'] ?? '');
                }
                $st = $pdo->prepare("UPDATE invoice SET affrw = 1 WHERE price_product = '0' AND name_product IN (?, ?)");
                $st->execute($names);
            }
            addFieldToTable('invoice', 'affrw_end', null, 'INT NOT NULL DEFAULT 0');
        } catch (Exception $e) {
            error_log("invoice.affrw: " . $e->getMessage());
        }
    }
    // 🏷 the account's name on the panel (⚙️ قوانین اکانت, $lang's): ref_ +
    // id + the next number, or 8 random letters and digits. «کاربر انتخاب
    // کنه» names come from the customer - anything else asking gets ref_.
    function affrw_username($uid, $lang)
    {
        global $pdo;
        $taken = function ($name) use ($pdo) {
            $st = $pdo->prepare("SELECT COUNT(*) FROM invoice WHERE username = ?");
            $st->execute([$name]);
            return (int) $st->fetchColumn() > 0;
        };
        if ((string) feature_setting_value('affrw_uname', $lang, 'ref') === 'random') {
            do {
                $name = chr(random_int(97, 122)) . substr(bin2hex(random_bytes(4)), 0, 7);
            } while ($taken($name));
            return $name;
        }
        $n = 1;
        while ($taken("ref_{$uid}_{$n}")) {
            $n++;
        }
        return "ref_{$uid}_{$n}";
    }
    // ✍️ a name the customer typed: already an account in the bot, or on the
    // panel the gift is made on
    function affrw_name_taken($uid, $name)
    {
        global $pdo, $ManagePanel;
        $st = $pdo->prepare("SELECT COUNT(*) FROM invoice WHERE username = ?");
        $st->execute([(string) $name]);
        if ((int) $st->fetchColumn() > 0) {
            return true;
        }
        $row = affrw_row($uid);
        $panel = affrw_panel(affrw_cfg($row['lang'] ?? 'fa'));
        if ($panel !== null && is_object($ManagePanel)) {
            $d = $ManagePanel->DataUser($panel['name_panel'], (string) $name);
            return is_array($d) && !empty($d['username']);
        }
        return false;
    }
    function affrw_name_kb($tx)
    {
        return json_encode(['inline_keyboard' => [[['text' => $tx['users']['affiliates']['rewardNameBtn'], 'callback_data' => 'affrwname', 'style' => 'success']]]]);
    }
    // 🔄 a free config its owner's language does not let be renewed
    function affrw_renew_blocked($inv)
    {
        // ⏱ an hourly service is never renewed: it is paid as it goes
        if (is_array($inv) && (int) ($inv['payg'] ?? 0) === 1) {
            return true;
        }
        if (!is_array($inv) || (int) ($inv['affrw'] ?? 0) !== 1) {
            return false;
        }
        $owner = select("user", "*", "id", (string) $inv['id_user'], "select");
        return (string) feature_setting_value('affrw_renew', is_array($owner) ? ($owner['lang'] ?? 'fa') : 'fa', '0') !== '1';
    }
    // renewed: from now on a service like any other
    function affrw_mark_renewed($extend, $username, $panelName)
    {
        global $pdo;
        if (!is_array($extend) || empty($extend['status'])) {
            return;
        }
        affrw_ensure_table();
        $pdo->prepare("UPDATE invoice SET affrw = 2 WHERE username = ? AND Service_location = ? AND affrw = 1")->execute([(string) $username, (string) $panelName]);
    }
    // one service's row in 🛍 سرویس‌های من: ⏱'s own button for an hourly one
    // (red, its own name), otherwise the account name - or 🎁's label - in blue
    function myservices_row_btn($row, $tx, $lang, $suffix = '')
    {
        $pg = function_exists('payg_list_button') ? payg_list_button($row, $tx, $lang, $suffix) : null;
        if ($pg !== null) {
            return $pg;
        }
        return ['text' => (affrw_list_label($row, $tx) ?? $row['username']) . $suffix, 'callback_data' => 'product_' . $row['id_invoice'], 'style' => 'primary'];
    }
    // 🛍 سرویس های من: a free config not renewed yet is «🎁 رفرال» (numbered
    // when there are more); null for anything else - its account name then
    function affrw_list_label($row, $tx)
    {
        global $pdo;
        static $ids = [];
        // every list of «🛍 سرویس‌های من» asks here, so ⏱'s label rides along
        $pg = payg_list_label($row, $tx);
        if ($pg !== null) {
            return $pg;
        }
        if (!is_array($row) || (int) ($row['affrw'] ?? 0) !== 1) {
            return null;
        }
        $uid = (string) $row['id_user'];
        if (!isset($ids[$uid])) {
            $st = $pdo->prepare("SELECT id_invoice FROM invoice WHERE id_user = ? AND affrw = 1 AND Status IN ('active', 'end_of_time', 'end_of_volume', 'sendedwarn', 'send_on_hold') ORDER BY CAST(time_sell AS UNSIGNED)");
            $st->execute([$uid]);
            $ids[$uid] = array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN));
        }
        $label = $tx['users']['affiliates']['rewardListLabel'];
        $n = array_search((string) $row['id_invoice'], $ids[$uid], true);
        return (count($ids[$uid]) > 1 && $n !== false) ? $label . ' ' . ($n + 1) : $label;
    }
    // 🗑 the cron, for a free config not renewed: its own rule instead of the
    // bot-wide one - never (the default), as soon as it ended (time or
    // volume), or some hours after. Its owner is told.
    function affrw_cron_ended($invoice, $user, $userData, $Panel)
    {
        global $pdo;
        if (!in_array($userData['status'] ?? '', ['limited', 'expired'], true)) {
            return false;
        }
        $lang = is_array($user) ? ($user['lang'] ?? 'fa') : 'fa';
        $del = (string) feature_setting_value('affrw_del', $lang, 'no');
        if ($del !== 'end' && $del !== 'hours') {
            return false;
        }
        $hours = $del === 'end' ? 0 : max(1, (int) feature_setting_value('affrw_del_hours', $lang, '24'));
        $end = (int) ($invoice['affrw_end'] ?? 0);
        if ($end === 0) {
            $end = ($userData['status'] === 'expired' && (int) ($userData['expire'] ?? 0) > 0) ? (int) $userData['expire'] : time();
            $pdo->prepare("UPDATE invoice SET affrw_end = ? WHERE id_invoice = ?")->execute([$end, $invoice['id_invoice']]);
        }
        if (time() < $end + $hours * 3600) {
            return false;
        }
        $Panel->RemoveUser($invoice['Service_location'], $invoice['username']);
        update("invoice", "Status", "removeTime", "id_invoice", $invoice['id_invoice']);
        bottext_extras_key_hint('users.affiliates.rewardDeleted');
        sendmessage($invoice['id_user'], strtr(payer_texts($invoice['id_user'])['users']['affiliates']['rewardDeleted'], ['{service}' => htmlspecialchars((string) $invoice['username'])]), null, 'HTML');
        return true;
    }
    // whether a customer's row lets a new round count: none yet, refused, or
    // a reward earned with more to come
    function affrw_counting($row)
    {
        return $row === null || in_array($row['status'], ['rejected', 'open'], true);
    }
    // 🚪 the invitees behind the latest reward, and how many more it needs
    // after some of them left its channel
    function affrw_members($row)
    {
        return is_array($row) ? array_map('strval', json_decode((string) ($row['members'] ?? ''), true) ?: []) : [];
    }
    function affrw_missing($row, $cfg)
    {
        $left = json_decode((string) ($row['left_ids'] ?? ''), true) ?: [];
        return max(0, $cfg['need'] - count(array_diff(affrw_members($row), array_map('strval', $left))));
    }
    // 🚪 غیرفعال شدن با خروج از کانال, per language: it watches the channels
    // of 🎁's own 🛡 📯 check, so with that off there is nothing to watch
    function affrw_leave_channels($lang)
    {
        $rv = refv_cfg($lang, 'r');
        if (feature_setting_value('affrw_leave', $lang, '0') !== '1' || !$rv['channel']) {
            return [];
        }
        return refv_channel_rows($rv);
    }
    // the service of the latest reward switched on or off on its panel: its
    // invoice when it is (now) in that state, null when it is gone or ended
    // (expired, used up) - then there is nothing to pause
    function affrw_switch($row, $on)
    {
        global $ManagePanel;
        $inv = select("invoice", "*", "id_invoice", (string) ($row['id_invoice'] ?? ''), "select");
        if (!is_array($inv)) {
            return null;
        }
        $st = $ManagePanel->DataUser($inv['Service_location'], $inv['username'])['status'] ?? '';
        if ($st === ($on ? 'disabled' : 'active')) {
            $ManagePanel->Change_status($inv['username'], $inv['Service_location']);
            return $inv;
        }
        return $st === ($on ? 'active' : 'disabled') ? $inv : null;
    }
    // below the count: paused and the customer told; full again: back on
    function affrw_leave_apply($uid, $row, $name = '', $channel = '')
    {
        global $pdo;
        $missing = affrw_missing($row, affrw_cfg($row['lang']));
        $paused = (int) ($row['suspended'] ?? 0) === 1;
        if ($paused === ($missing > 0)) {
            return;
        }
        $inv = affrw_switch($row, $paused);
        if ($inv === null && !$paused) {
            return;
        }
        $pdo->prepare("UPDATE affiliate_reward SET suspended = ? WHERE user_id = ?")->execute([$paused ? 0 : 1, (string) $uid]);
        if ($inv === null) {
            return;
        }
        $key = $paused ? 'rewardResumed' : 'rewardPaused';
        bottext_extras_key_hint("users.affiliates.{$key}");
        sendmessage($uid, strtr(payer_texts($uid)['users']['affiliates'][$key], [
            '{name}' => htmlspecialchars($name),
            '{channel}' => htmlspecialchars($channel),
            '{service}' => htmlspecialchars((string) $inv['username']),
            '{missing}' => $missing,
        ]), null, 'HTML');
    }
    // A member left one of those channels, or joined again ($chat: the
    // update's chat). Only someone behind a customer's latest free config
    // matters: leaving marks them gone; back in every chosen channel, not.
    function affrw_member_moved($memberId, array $chat, $joined, $name)
    {
        global $pdo;
        $m = select("user", "*", "id", (string) $memberId, "select");
        $uid = is_array($m) ? (string) ($m['aff_rw'] ?? '') : '';
        if ($uid === '0' || $uid === '') {
            return;
        }
        $row = affrw_row($uid);
        if ($row === null || !in_array((string) $memberId, affrw_members($row), true)) {
            return;
        }
        $hit = null;
        foreach (affrw_leave_channels($row['lang']) as $c) {
            $link = (string) $c['link'];
            if ($link === (string) ($chat['id'] ?? '') || (!empty($chat['username']) && strcasecmp(ltrim($link, '@'), (string) $chat['username']) === 0)) {
                $hit = $c;
                break;
            }
        }
        if ($hit === null) {
            return;
        }
        $left = array_map('strval', json_decode((string) ($row['left_ids'] ?? ''), true) ?: []);
        $was = in_array((string) $memberId, $left, true);
        if ($joined) {
            if (!$was || refv_unjoined($memberId, $uid, 'r')) {
                return;
            }
            $left = array_values(array_diff($left, [(string) $memberId]));
        } else {
            if ($was) {
                return;
            }
            $left[] = (string) $memberId;
        }
        $row['left_ids'] = json_encode($left);
        $pdo->prepare("UPDATE affiliate_reward SET left_ids = ? WHERE user_id = ?")->execute([$row['left_ids'], $uid]);
        affrw_leave_apply($uid, $row, $name, (string) $hit['remark']);
    }
    // a new invite while paused fills the gap - it goes with that reward, not
    // toward the next one
    function affrw_refill($uid, $newId)
    {
        global $pdo;
        $row = affrw_row($uid);
        if ($row === null || (int) ($row['suspended'] ?? 0) !== 1) {
            return;
        }
        $members = affrw_members($row);
        $members[] = (string) $newId;
        $row['members'] = json_encode(array_values(array_unique($members)));
        $pdo->prepare("UPDATE affiliate_reward SET members = ? WHERE user_id = ?")->execute([$row['members'], (string) $uid]);
        affrw_leave_apply($uid, $row);
    }
    // how many invites a paused free config still waits for, or null when
    // this service is not one
    function affrw_paused_missing($inv)
    {
        if (!is_array($inv)) {
            return null;
        }
        $row = affrw_row($inv['id_user']);
        if ($row === null || (int) ($row['suspended'] ?? 0) !== 1 || (string) $row['id_invoice'] !== (string) $inv['id_invoice']) {
            return null;
        }
        return max(1, affrw_missing($row, affrw_cfg($row['lang'])));
    }
    // 🔄 the admin's reset from a customer's own screen: their count starts
    // from zero (only people who join from now on count) and they can earn it
    // again, as many times as the setting allows; a request waiting for
    // approval is dropped
    function affrw_reset($uid)
    {
        global $pdo;
        affrw_ensure_table();
        $u = select("user", "*", "id", (string) $uid, "select");
        $stmt = $pdo->prepare("INSERT INTO affiliate_reward (user_id, lang, status, invites, since, time, times) VALUES (?, ?, 'open', 0, ?, ?, 0)
            ON DUPLICATE KEY UPDATE status = 'open', invites = 0, since = VALUES(since), time = VALUES(time), times = 0");
        $stmt->execute([(string) $uid, is_array($u) ? ($u['lang'] ?? 'fa') : 'fa', time(), time()]);
    }
    // Read straight from the table - select()'s cache would miss the
    // conditional updates below.
    function affrw_row($uid)
    {
        global $pdo;
        affrw_ensure_table();
        $stmt = $pdo->prepare("SELECT * FROM affiliate_reward WHERE user_id = ?");
        $stmt->execute([(string) $uid]);
        $r = $stmt->fetch(PDO::FETCH_ASSOC);
        if (!is_array($r)) {
            return null;
        }
        // 🔁 چند بار raised since a row reached the end of it: it goes on
        // counting from here
        $times = affrw_times($r);
        if ($r['status'] === 'done' && $times < affrw_cfg($r['lang'])['max']) {
            $pdo->prepare("UPDATE affiliate_reward SET status = 'open', times = ? WHERE user_id = ? AND status = 'done'")->execute([$times, (string) $uid]);
            $r['status'] = 'open';
            $r['times'] = $times;
        }
        return $r;
    }
    // how many times a customer has had it; a row from before that was
    // counted says «done» only, which was once
    function affrw_times($row)
    {
        if ($row === null) {
            return 0;
        }
        $times = (int) ($row['times'] ?? 0);
        return $row['status'] === 'done' ? max(1, $times) : $times;
    }
    // had it as many times as 🔁 چند بار allows - nothing more to earn (a
    // round already under way still ends the way it would)
    function affrw_used_up($row)
    {
        return $row !== null && in_array($row['status'], ['open', 'rejected', 'done'], true)
            && affrw_times($row) >= affrw_cfg($row['lang'])['max'];
    }
    // counting starts when the offer was switched on - or, after a refusal,
    // at the refusal
    function affrw_since($cfg, $row)
    {
        return max($cfg['since'], is_array($row) ? (int) $row['since'] : 0);
    }
    // Whether $memberId, newly $inviterId's referral, counts for their free
    // config: a newcomer to the bot since the count began, and not already
    // behind their latest reward. Anyone counts while 🎁 is off for the
    // inviter's language (there is nothing to count then).
    function affrw_member_counts($inviterId, $memberId)
    {
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $cfg = affrw_live(is_array($inv) ? ($inv['lang'] ?? 'fa') : 'fa');
        if ($cfg === null) {
            return true;
        }
        $row = affrw_row($inviterId);
        $m = select("user", "*", "id", (string) $memberId, "select");
        return is_array($m) && (int) ($m['register'] ?? 0) > affrw_since($cfg, $row)
            && !in_array((string) $memberId, affrw_members($row), true);
    }
    // valid invites: people who joined the bot through this customer's link
    // since then
    function affrw_count($uid, $since)
    {
        global $pdo;
        affrw_ensure_table();
        $stmt = $pdo->prepare("SELECT id FROM user WHERE aff_rw = ? AND id != ? AND CAST(register AS UNSIGNED) > ?");
        $stmt->execute([(string) $uid, (string) $uid, (int) $since]);
        // someone who filled a paused reward's gap is not a new invite too
        return count(array_diff(array_map('strval', $stmt->fetchAll(PDO::FETCH_COLUMN)), affrw_members(affrw_row($uid))));
    }
    // Takes this customer's one slot: a new row, or a refused one opened
    // again. False when another request got there first.
    function affrw_claim($uid, $lang, $status, $count, $since)
    {
        global $pdo;
        affrw_ensure_table();
        $stmt = $pdo->prepare("INSERT IGNORE INTO affiliate_reward (user_id, lang, status, invites, since, time) VALUES (?, ?, ?, ?, ?, ?)");
        $stmt->execute([(string) $uid, $lang, $status, $count, $since, time()]);
        if ($stmt->rowCount() > 0) {
            return true;
        }
        $stmt = $pdo->prepare("UPDATE affiliate_reward SET lang = ?, status = ?, invites = ?, time = ? WHERE user_id = ? AND status IN ('rejected', 'open')");
        $stmt->execute([$lang, $status, $count, time(), (string) $uid]);
        return $stmt->rowCount() > 0;
    }
    // moves the row on only from the status it is expected to be in, so two
    // admins tapping at once cannot both make a config
    function affrw_move($uid, $from, $to)
    {
        global $pdo;
        affrw_ensure_table();
        $extra = $to === 'rejected' ? ', since = ' . time() : '';
        $stmt = $pdo->prepare("UPDATE affiliate_reward SET status = ?, time = ?{$extra} WHERE user_id = ? AND status = ?");
        $stmt->execute([$to, time(), (string) $uid, $from]);
        return $stmt->rowCount() > 0;
    }
    function affrw_vars($cfg, $count)
    {
        return ['{need}' => $cfg['need'], '{volume}' => volume_num($cfg['gb']), '{days}' => $cfg['days'], '{count}' => min($count, $cfg['need'])];
    }
    // A delivery that never finished - the request died half way (a crash, a
    // timeout) - left its row at 'giving', and that blocked the customer for
    // good: no config, no request to anyone, nothing on 👥 ever again. After
    // five minutes such a row goes to the admins instead, as when the panel
    // refuses, and the customer is told. Swept whenever an invite is counted
    // or anyone opens 👥, so an old stuck one is found too.
    function affrw_unstick()
    {
        global $pdo;
        affrw_ensure_table();
        $st = $pdo->prepare("SELECT user_id, lang, invites FROM affiliate_reward WHERE status = 'giving' AND time < ?");
        $st->execute([time() - 300]);
        foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
            if (!affrw_move($r['user_id'], 'giving', 'pending')) {
                continue;
            }
            affrw_ask_admins($r['user_id'], true);
            bottext_extras_key_hint('users.affiliates.rewardSentToAdmin');
            sendmessage($r['user_id'], strtr(payer_texts($r['user_id'])['users']['affiliates']['rewardSentToAdmin'], affrw_vars(affrw_cfg($r['lang']), (int) $r['invites'])), null, 'HTML');
        }
    }
    // Called when someone joins through $uid's link, and when $uid opens 👥.
    function affrw_check($uid)
    {
        affrw_unstick();
        $u = select("user", "*", "id", $uid, "select");
        if (!is_array($u)) {
            return;
        }
        $lang = $u['lang'] ?? 'fa';
        $cfg = affrw_live($lang);
        if ($cfg === null) {
            return;
        }
        $row = affrw_row($uid);
        // 🔁 چند بار lowered below what they have had: no more either - nor for
        // one ⛔️ kept out of 🎁 (aff_blocked)
        if (!affrw_counting($row) || affrw_used_up($row) || aff_blocked($uid, 'r')) {
            return;
        }
        $count = affrw_count($uid, affrw_since($cfg, $row));
        if ($count < $cfg['need']) {
            return;
        }
        // 👑 inviters of 🎁's 🛡 never wait for an admin - nor does an admin
        // with no limit (🛡 دسترسی ادمین)
        if ($cfg['mode'] === 'auto' || in_array((string) $uid, refv_cfg($lang, 'r')['vip'], true) || affrw_admin_free($uid)) {
            if (!affrw_claim($uid, $lang, 'giving', $count, affrw_since($cfg, $row))) {
                return;
            }
            // anything thrown on the way counts as the panel refusing, rather
            // than ending the request with the row stuck at 'giving'
            try {
                $given = affrw_give($uid);
            } catch (Throwable $e) {
                error_log('affrw_give: ' . $e->getMessage());
                $given = false;
            }
            if ($given) {
                return;
            }
            // the panel refused - an admin gets it instead of nobody
            affrw_move($uid, 'giving', 'pending');
            affrw_ask_admins($uid, true);
        } else {
            if (!affrw_claim($uid, $lang, 'pending', $count, affrw_since($cfg, $row))) {
                return;
            }
            affrw_ask_admins($uid, false);
        }
        $tx = payer_texts($uid);
        bottext_extras_key_hint('users.affiliates.rewardSentToAdmin');
        sendmessage($uid, strtr($tx['users']['affiliates']['rewardSentToAdmin'], affrw_vars($cfg, $count)), null, 'HTML');
    }
    // the message under 👥 زیرمجموعه‌گیری, or null when this language has none
    // ($key: its 🎨 item) - once 🔁 چند بار is used up, a message saying so
    // instead of a page inviting them to earn one
    function affrw_info_text($user, $tx, $link, &$key = null)
    {
        $key = 'rewardInfo';
        $cfg = affrw_live($user['lang'] ?? 'fa');
        if ($cfg === null) {
            return null;
        }
        $a = $tx['users']['affiliates'];
        // ⛔️ kept out of 🎁 by an admin: said so, instead of a page to earn one
        if (aff_blocked($user['id'], 'r')) {
            $key = 'rewardBlocked';
            return $a['rewardBlocked'];
        }
        $row = affrw_row($user['id']);
        if (affrw_used_up($row)) {
            $key = 'rewardLimitReached';
            return strtr($a['rewardLimitReached'], ['{max}' => affrw_cfg($row['lang'])['max']]);
        }
        if ($row !== null && $row['status'] === 'naming') {
            $status = $a['rewardStatusNaming'];
            $count = $cfg['need'];
        } elseif (!affrw_counting($row)) {
            $status = $a['rewardStatusPending'];
            $count = $cfg['need'];
        } else {
            $free = affrw_admin_free($user['id']);
            $status = ($cfg['mode'] === 'auto' || $free) ? $a['rewardStatusAuto'] : $a['rewardStatusAdmin'];
            // an admin with no limit gets it right after this page: shown full
            $count = $free ? $cfg['need'] : affrw_count($user['id'], affrw_since($cfg, $row));
        }
        return strtr($a['rewardInfo'], affrw_vars($cfg, $count) + ['{link}' => $link, '{status}' => $status]);
    }
    // what the admins get: who (name, @username, id), which time this is,
    // how many, the free configs they have had, and who they invited
    function affrw_request_text($uid)
    {
        global $pdo;
        $row = affrw_row($uid);
        $u = select("user", "*", "id", $uid, "select");
        $lang = $row['lang'] ?? 'fa';
        $cfg = affrw_cfg($lang);
        $panel = affrw_panel($cfg);
        $fa = lang_tab_texts('fa');
        $t = $fa['Admin']['AffReward'];
        $since = affrw_since($cfg, $row);
        // the invites affrw_count() counts, newest first
        $stmt = $pdo->prepare("SELECT id FROM user WHERE aff_rw = ? AND id != ? AND CAST(register AS UNSIGNED) > ? ORDER BY CAST(register AS UNSIGNED) DESC");
        $stmt->execute([(string) $uid, (string) $uid, (int) $since]);
        $ids = array_values(array_diff(array_map('strval', $stmt->fetchAll(PDO::FETCH_COLUMN)), affrw_members($row)));
        $panelName = is_array($panel) ? (string) $panel['name_panel'] : $fa['Admin']['FeatureSection']['affrwNoPanel'];
        return strtr($t['request'], [
            '{user}' => aff_user_block($uid, $u),
            '{lang}' => $fa['bottext']['langs'][$lang] ?? $lang,
            '{round}' => affrw_times($row) + 1,
            '{max}' => $cfg['max'],
            '{count}' => count($ids),
            '{need}' => $cfg['need'],
            '{services}' => affrw_services_text($uid),
            '{volume}' => volume_num($cfg['gb']),
            '{days}' => $cfg['days'],
            '{panel}' => aff_bidi($panelName, htmlspecialchars($panelName)),
            '{list}' => aff_label_lines($ids, 15, true),
        ]);
    }
    function affrw_ask_admins($uid, $autoFailed = false)
    {
        $fa = lang_tab_texts('fa');
        $t = $fa['Admin']['AffReward'];
        $kb = json_encode(['inline_keyboard' => [
            [
                ['text' => $t['approveBtn'], 'callback_data' => "affrw|ok|{$uid}", 'style' => 'success'],
                ['text' => $t['rejectBtn'], 'callback_data' => "affrw|no|{$uid}", 'style' => 'danger'],
            ],
            [['text' => $fa['Admin']['manageUser']['manageUserBtn'], 'callback_data' => "manageuser_{$uid}"]],
        ]]);
        $text = affrw_request_text($uid) . ($autoFailed ? $t['autoFailed'] : '');
        foreach (select("admin", "id_admin", null, null, "FETCH_COLUMN") as $aid) {
            sendmessage($aid, $text, $kb, 'HTML');
        }
        // ⏳ and in the report group's 🎁 topic, as its status - the
        // buttons stay with the admins; only a report, so nothing it hits
        // stops the customer being told
        try {
            affrw_topic(affrw_row($uid)['lang'] ?? 'fa', $text . "\n\n" . $t['statusPending']);
        } catch (Throwable $e) {
            error_log('affrw_topic: ' . $e->getMessage());
        }
    }
    // the config message, worded like a bought one's; [text, its sub link]
    function affrw_service_text($panel, $cfg, $tx, $out)
    {
        $sublink = $panel['sublink'] == "onsublink" ? (string) ($out['subscription_url'] ?? '') : "";
        $links = "";
        if ($panel['config'] == "onconfig" && is_array($out['configs'] ?? null)) {
            foreach ($out['configs'] as $link) {
                $links .= "\n" . $link;
            }
        }
        $tpl = $tx['users']['affiliates']['rewardAfterPay'];
        if ($panel['type'] == "WGDashboard") {
            $tpl = $tx['textbot']['wgDashboard'];
        } elseif ($panel['type'] == "ibsng" || $panel['type'] == "mikrotik") {
            $tpl = $tx['textbot']['afterPayIbsng'];
        }
        return [strtr($tpl, [
            '{username}' => "<code>{$out['username']}</code>",
            '{name_service}' => $tx['users']['affiliates']['rewardServiceName'],
            '{location}' => $panel['name_panel'],
            '{day}' => $cfg['days'],
            '{volume}' => volume_num($cfg['gb']),
            '{time_human}' => service_days_text($cfg['days'], $tx),
            '{volume_human}' => service_volume_text($cfg['gb'] * 1024, $tx),
            '{config}' => "<code>{$sublink}</code>",
            '{links}' => $links,
            '{links2}' => $sublink,
            '{password}' => (string) ($out['subscription_url'] ?? ''),
        ]), $sublink];
    }
    // Makes the config on $panel - the same way a paid one is made - lists it
    // under $uid's 🛍 سرویس های من and sends it, in $tx's language. The
    // invoice id and account, or null when the panel refused ($err: why).
    // Also 🧪 تست واقعی's, which is why it leaves affiliate_reward alone.
    function affrw_deliver($uid, $cfg, $panel, $u, $tx, $lang, $invites, &$err = null, $name = null)
    {
        global $pdo, $ManagePanel;
        affrw_ensure_table();
        $out = null;
        if ($panel !== null) {
            $username_ac = $name !== null ? (string) $name : affrw_username($uid, $lang);
            $datac = [
                'expire' => strtotime("+" . $cfg['days'] . " days"),
                'data_limit' => (int) round($cfg['gb'] * pow(1024, 3)),
                'from_id' => $uid,
                'username' => $u['username'] ?? '',
                'type' => 'buy',
                // 🚀 the plan's speed (only a Rebecca panel holds one)
                'speed_mbps' => ($panel['type'] ?? '') === 'rebecca' ? (float) ($cfg['speed'] ?? 0) : 0,
            ];
            $out = $ManagePanel->createUser($panel['name_panel'], "customvolume", $username_ac, $datac);
        }
        if (!is_array($out) || empty($out['username'])) {
            $err = $out['msg'] ?? ($panel === null ? 'panel not found' : '');
            return null;
        }
        $id_invoice = bin2hex(random_bytes(4));
        $stmt = $pdo->prepare("INSERT IGNORE INTO invoice (id_user, id_invoice, username, time_sell, Service_location, name_product, price_product, Volume, Service_time, Status, notifctions, affrw) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)");
        $stmt->execute([$uid, $id_invoice, $out['username'], time(), $panel['name_panel'], $tx['users']['affiliates']['rewardServiceName'], '0', volume_store($cfg['gb']), $cfg['days'], 'active', json_encode(['volume' => false, 'time' => false])]);
        bottext_extras_key_hint('users.affiliates.rewardGiven');
        sendmessage($uid, strtr($tx['users']['affiliates']['rewardGiven'], affrw_vars($cfg, (int) $invites)), null, 'HTML');
        // then the service itself, worded like a bought one
        [$text, $sublink] = affrw_service_text($panel, $cfg, $tx, $out);
        if ($panel['type'] == "ibsng" || $panel['type'] == "mikrotik") {
            update("invoice", "user_info", $out['subscription_url'], "id_invoice", $id_invoice);
        }
        sendMessageService($panel, $out['configs'] ?? [], $sublink, $out['username'], affrw_help_kb($lang, $tx), $text, $id_invoice, $uid, 'images.jpg', 'affrw');
        return ['id_invoice' => $id_invoice, 'username' => $out['username']];
    }
    // Makes the config on the chosen panel and sends it to the customer in
    // their own language. The row has to be 'giving' already; it ends 'done'
    // (or open for the next round) on success and is left for the caller
    // otherwise. With «کاربر انتخاب کنه» and no $name yet, the customer is
    // asked for one instead ('naming') - made once they send it.
    // A message to one topic of the report group (errorreport, porsantreport);
    // nothing when the bot has none. The line with the language of the user it
    // names is added by report_lang_tag(), unless the text carries its own.
    function affrw_report($topic, $text)
    {
        $setting = select("setting", "*", null, null, "select");
        if (strlen((string) ($setting['Channel_Report'] ?? '')) > 0) {
            telegram('sendmessage', [
                'chat_id' => $setting['Channel_Report'],
                'message_thread_id' => select("topicid", "idreport", "report", $topic, "select")['idreport'],
                'text' => $text,
                'parse_mode' => "HTML",
            ]);
        }
    }
    // A message to the report group's 🎁 topic - a topic of its own (made
    // when first needed, also in a group set up before it existed); it used
    // to share 💰 پورسانت's. It ends with the language whose 🎁 plan it is
    // about ($lang) - written here rather than left to report_lang_tag(),
    // which guesses from the ids in it and would name an admin's own language
    // for his 🧪 test of another tab, or an invitee's.
    function affrw_topic($lang, $text)
    {
        $pt = panel_texts();
        $code = in_array($lang, panel_langs(), true) ? $lang : 'fa';
        report_to_topic('affrwreport', $pt['Admin']['AffReward']['topicName'], $text . "\n\n" . sprintf($pt['Admin']['reportgroup']['userLangLine'], $pt['bottext']['langs'][$code] ?? $code));
    }
    // 🗂 the free configs a customer has had, and how many of them are still
    // among their services (a renewed one too)
    function affrw_services_text($uid)
    {
        global $pdo;
        affrw_ensure_table();
        $st = $pdo->prepare("SELECT COUNT(*) AS n, COALESCE(SUM(Status IN ('active', 'end_of_time', 'end_of_volume', 'sendedwarn', 'send_on_hold')), 0) AS live FROM invoice WHERE id_user = ? AND affrw IN (1, 2)");
        $st->execute([(string) $uid]);
        $r = $st->fetch(PDO::FETCH_ASSOC);
        $t = panel_texts()['Admin']['AffReward'];
        if (!is_array($r) || (int) $r['n'] === 0) {
            return $t['servicesNone'];
        }
        return strtr($t['services'], ['{all}' => (int) $r['n'], '{have}' => (int) $r['live']]);
    }
    // 🎁's report of a config made (affrw_deliver's $made) - for a customer's
    // invites, an admin's own and an admin's 🧪 real test alike: who got it,
    // its account, which time this is ($round; none for a test), their free
    // configs so far and the invitees behind it ($members); $extra: a line
    // under it saying where it came from.
    function affrw_report_made($uid, $u, $cfg, $panel, $made, $lang, $extra = '', $round = null, array $members = [])
    {
        // only a report: whatever goes wrong here must not undo a config
        // already made (affrw_check would take it for the panel refusing)
        try {
            $t = panel_texts()['Admin']['AffReward'];
            affrw_topic($lang, strtr($t['report'], [
                '{user}' => aff_user_block($uid, $u),
                '{volume}' => volume_num($cfg['gb']),
                '{days}' => $cfg['days'],
                '{panel}' => aff_bidi($panel['name_panel'], htmlspecialchars((string) $panel['name_panel'])),
                '{service}' => htmlspecialchars((string) $made['username']),
                '{round}' => $round === null ? '' : strtr($t['reportRound'], ['{round}' => (int) $round, '{max}' => $cfg['max']]),
                '{services}' => affrw_services_text($uid),
                // newest first, as in the request
                '{list}' => $members ? strtr($t['reportList'], ['{n}' => count($members), '{list}' => aff_label_lines(array_reverse($members))]) : '',
            ]) . $extra);
        } catch (Throwable $e) {
            error_log('affrw_report_made: ' . $e->getMessage());
        }
    }
    // 🎁 a new referral of $inviterId's, in the report group's 🎁 topic - like
    // 💼's in 💰 پورسانت: the inviter, the newcomer and where the inviter's
    // count stands now. One who was a member before the count began is said
    // not to count. Only while 🎁 is on for the inviter's language.
    function affrw_report_referral($inviterId, $memberId)
    {
        $inv = select("user", "*", "id", (string) $inviterId, "select");
        $lang = is_array($inv) ? ($inv['lang'] ?? 'fa') : 'fa';
        $cfg = affrw_live($lang);
        if ($cfg === null) {
            return;
        }
        // only a report: the referral is counted whatever happens here
        try {
            $t = panel_texts()['Admin']['AffReward'];
            $row = affrw_row($inviterId);
            $since = affrw_since($cfg, $row);
            $m = select("user", "*", "id", (string) $memberId, "select");
            $stats = affrw_used_up($row)
                ? strtr($t['refRUsedUp'], ['{max}' => $cfg['max']])
                : strtr($t['refRStats'], ['{count}' => affrw_count($inviterId, $since), '{need}' => $cfg['need'], '{round}' => affrw_times($row) + 1, '{max}' => $cfg['max']]);
            $stats .= "\n" . strtr($t['refRServices'], ['{services}' => affrw_services_text($inviterId)]);
            $wasMember = is_array($m) && (int) ($m['register'] ?? 0) <= $since;
            affrw_topic($lang, strtr($t['newReferralR'], [
                '{inviter}' => aff_user_block($inviterId, $inv),
                '{member}' => aff_user_block($memberId, $m),
                '{stats}' => $stats,
            ]) . ($wasMember ? "\n\n" . $t['refRWasMember'] : ''));
        } catch (Throwable $e) {
            error_log('affrw_report_referral: ' . $e->getMessage());
        }
    }
    // $extra: a line for the report (who approved it)
    function affrw_give($uid, $name = null, $extra = '')
    {
        global $pdo;
        $fa = lang_tab_texts('fa');
        $row = affrw_row($uid);
        $u = select("user", "*", "id", $uid, "select");
        if ($row === null || !is_array($u)) {
            return false;
        }
        $cfg = affrw_cfg($row['lang']);
        $panel = affrw_panel($cfg);
        if ($name === null && (string) feature_setting_value('affrw_uname', $row['lang'], 'ref') === 'user') {
            affrw_move($uid, 'giving', 'naming');
            $tx = payer_texts($uid);
            bottext_extras_key_hint('users.affiliates.rewardNameAsk');
            sendmessage($uid, strtr($tx['users']['affiliates']['rewardNameAsk'], affrw_vars($cfg, (int) $row['invites'])), affrw_name_kb($tx), 'HTML');
            return true;
        }
        $err = null;
        $made = affrw_deliver($uid, $cfg, $panel, $u, payer_texts($uid), $u['lang'] ?? 'fa', (int) $row['invites'], $err, $name);
        if ($made === null) {
            affrw_report('errorreport', strtr($fa['Admin']['AffReward']['error'], [
                '{id}' => $uid,
                '{panel}' => $panel['name_panel'] ?? '—',
                '{msg}' => htmlspecialchars(json_encode($err, JSON_UNESCAPED_UNICODE)),
            ]));
            return false;
        }
        $id_invoice = $made['id_invoice'];
        // the invitees behind it (for 🚪 a leave), and the next round - or
        // done, once it has been earned as many times as allowed
        $since = affrw_since($cfg, $row);
        $st = $pdo->prepare("SELECT id FROM user WHERE aff_rw = ? AND id != ? AND CAST(register AS UNSIGNED) > ? ORDER BY CAST(register AS UNSIGNED)");
        $st->execute([(string) $uid, (string) $uid, (int) $since]);
        $members = array_values(array_diff(array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN)), affrw_members($row)));
        $times = (int) ($row['times'] ?? 0) + 1;
        $more = $times < $cfg['max'];
        $stmt = $pdo->prepare("UPDATE affiliate_reward SET status = ?, id_invoice = ?, time = ?, times = ?, since = ?, members = ?, left_ids = '[]', suspended = 0 WHERE user_id = ?");
        $stmt->execute([$more ? 'open' : 'done', $id_invoice, time(), $times, $more ? time() : (int) ($row['since'] ?? 0), json_encode($members), (string) $uid]);
        if (!$more) {
            affrw_admin_spent($uid, $cfg);
        }
        affrw_report_made($uid, $u, $cfg, $panel, $made, $row['lang'], $extra, $times, $members);
        return true;
    }
}
if (!function_exists('webpanel_enabled')) {
    // «🤖 پنل تحت وب: روشن ✅ / خاموش ❌» under «پنل تحت وب ربات 🤖» - one switch
    // for the whole bot. Off, the web panel takes no login and lets no open
    // session in (panel/inc/config.php, panel/login.php). On by default, so a
    // bot that has never set it keeps its panel.
    function webpanel_enabled()
    {
        $s = select("setting", "*", null, null, "select");
        return (string) (is_array($s) ? ($s['web_panel_status'] ?? 'on') : 'on') !== 'off';
    }
}
