if (!function_exists('bottext_extras_key_hint')) {
    // For a text that starts with a filled-in value and has no wording of its
    // own to be recognised by: the caller names the key, and the next sticker
    // lookup uses it once. Called with no argument it reads and clears it.
    function bottext_extras_key_hint($key = null)
    {
        static $pending = null;
        if ($key !== null) {
            $pending = (string) $key;
            return null;
        }
        $k = $pending;
        $pending = null;
        return $k;
    }
}
if (!function_exists('panelErrorText')) {
    // A panel that could not be reached, said in words - timeout, refused,
    // unknown domain, bad SSL - with the raw error under it, instead of the
    // raw error (or a JSON dump) alone
    function panelErrorText($rawError)
    {
        global $textbotlang, $request_exec_timeout;
        $raw = (is_array($rawError) || is_object($rawError)) ? json_encode($rawError, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : trim((string) $rawError);
        if ($raw === '' || $raw === false) {
            $raw = 'unknown error';
        }
        error_log('Panel connection error: ' . $raw);
        $messages = $textbotlang['Admin']['managepanel']['panelConnection'] ?? [];
        if (empty($messages)) {
            return htmlspecialchars($raw, ENT_NOQUOTES, 'UTF-8');
        }
        $needle = strtolower($raw);
        if (str_contains($needle, 'timed out') || str_contains($needle, 'timeout') || str_contains($needle, 'operation too slow')) {
            $seconds = preg_match('/after (\d+) milliseconds/', $needle, $ms) ? (int) round(intval($ms[1]) / 1000) : 0;
            if ($seconds < 1) {
                $seconds = (int) round(intval($request_exec_timeout ?: 10000) / 1000);
            }
            $text = sprintf($messages['timeout'], $seconds);
        } elseif (str_contains($needle, 'could not resolve') || str_contains($needle, 'name or service not known') || str_contains($needle, 'name lookup')) {
            $text = $messages['dns'];
        } elseif (str_contains($needle, 'connection refused') || str_contains($needle, 'failed to connect') || str_contains($needle, "couldn't connect") || str_contains($needle, 'connection reset')) {
            $text = $messages['refused'];
        } elseif (str_contains($needle, 'ssl') || str_contains($needle, 'certificate')) {
            $text = $messages['ssl'];
        } else {
            $text = $messages['generic'];
        }
        return $text . sprintf($messages['detail'], htmlspecialchars($raw, ENT_NOQUOTES, 'UTF-8'));
    }
}
if (!function_exists('panelProtocolsConfigured')) {
    // No protocol set for a Marzban / Marzneshin location: the user it made had
    // none either - a config that connects to nothing. Refused instead, saying so.
    function panelProtocolsConfigured($rawProxies)
    {
        $decoded = json_decode((string) $rawProxies, true);
        return is_array($decoded) && count($decoded) > 0;
    }
    function panelProtocolsMissingError($panelName = '')
    {
        global $textbotlang;
        error_log('Panel protocols not configured' . ((string) $panelName !== '' ? " [$panelName]" : ''));
        return ['error' => $textbotlang['Admin']['managepanel']['protocolsNotConfigured'] ?? 'Protocols and inbounds are not configured for this location.'];
    }
}
if (!function_exists('payment_claim')) {
    // Marks a payment paid, and says true to the ONE request that did it. Every
    // gateway asks this before crediting: a callback sent twice, or a browser
    // reload landing at the same moment, went through the «not paid yet?»
    // check twice and credited twice.
    function payment_claim($orderId)
    {
        global $pdo;
        $stmt = $pdo->prepare("UPDATE Payment_report SET payment_Status = 'paid' WHERE id_order = ? AND payment_Status <> 'paid'");
        $stmt->execute([(string) $orderId]);
        clearSelectCache('Payment_report');
        return $stmt->rowCount() === 1;
    }
}
if (!function_exists('balance_add')) {
    // A balance moved by an amount in ONE statement. «Read it, then write the
    // sum back» lost whatever landed in between: a top-up approved while a
    // purchase was talking to the panel, or a second purchase.
    function balance_add($userId, $amount)
    {
        global $pdo, $user;
        $stmt = $pdo->prepare("UPDATE user SET Balance = Balance + ? WHERE id = ?");
        $stmt->execute([$amount, $userId]);
        file_put_contents('log.txt', "\nuser_Balance_" . ($amount >= 0 ? '+' : '') . $amount . "_id_{$userId}_" . ($user['step'] ?? '') . '_' . date("Y-m-d H:i:s"), FILE_APPEND);
        clearSelectCache('user');
    }
}
if (!function_exists('containsHtmlMarkup')) {
    // A panel or product name goes out inside HTML messages: a «<» in it makes
    // Telegram refuse every message that shows it.
    function containsHtmlMarkup($value)
    {
        return is_string($value) && strpos($value, '<') !== false;
    }
}
if (!function_exists('webhook_register')) {
    // Telegram sends the bot's secret with every update (the
    // X-Telegram-Bot-Api-Secret-Token header) and webhook_secret_ok() turns
    // away an update without it. $bot: an agent bot's botsaz row, or null for
    // this bot. A new secret is kept only once Telegram has taken it.
    function webhook_register($bot = null)
    {
        global $domainhosts;
        if ($bot === null) {
            $row = select("setting", "*", null, null, "select");
            $token = null;
            // chat_member is not sent unless asked for: without it a customer joining
            // or leaving a channel never reached the bot (🛡 verification, 🚪 left_channel)
            $params = [
                'url' => "https://$domainhosts/index.php",
                'allowed_updates' => json_encode(['message', 'edited_message', 'callback_query', 'inline_query', 'pre_checkout_query', 'chat_member', 'my_chat_member']),
            ];
        } else {
            if (!is_array($bot) || empty($bot['bot_token'])) {
                return false;
            }
            $row = $bot;
            $token = $bot['bot_token'];
            $params = ['url' => "https://$domainhosts/vpnbot/{$bot['id_user']}{$bot['username']}/index.php"];
        }
        // before table.php added the column: as it always was, no secret
        if (!is_array($row) || !array_key_exists('webhook_secret', $row)) {
            return telegram('setwebhook', $params, $token);
        }
        $stored = (string) $row['webhook_secret'];
        $secret = $stored !== '' ? $stored : bin2hex(random_bytes(24));
        $params['secret_token'] = $secret;
        $res = telegram('setwebhook', $params, $token);
        if (is_array($res) && !empty($res['ok']) && $secret !== $stored) {
            if ($bot === null) {
                update("setting", "webhook_secret", $secret, null, null);
            } else {
                update("botsaz", "webhook_secret", $secret, "bot_token", $token);
            }
        }
        return $res;
    }

    // Is this update really from Telegram's webhook for this bot? No secret yet:
    // register one and let the update through. A wrong or missing one means
    // something else re-registered the webhook (the installer, an older copy of
    // the bot): register ours again - at most once a minute - and answer 403, so
    // Telegram sends the update again, this time with our secret.
    function webhook_secret_ok($bot = null)
    {
        $row = $bot === null ? select("setting", "*", null, null, "select") : $bot;
        if (!is_array($row) || !array_key_exists('webhook_secret', $row)) {
            return true;
        }
        $secret = (string) $row['webhook_secret'];
        $got = $_SERVER['HTTP_X_TELEGRAM_BOT_API_SECRET_TOKEN'] ?? '';
        if ($secret !== '' && is_string($got) && hash_equals($secret, $got)) {
            return true;
        }
        $stamp = sys_get_temp_dir() . '/ciro_webhook_' . md5(__DIR__ . '|' . ($bot === null ? '' : (string) ($bot['bot_token'] ?? '')));
        if (!is_file($stamp) || time() - (int) @filemtime($stamp) >= 60) {
            @touch($stamp);
            webhook_register($bot);
        }
        if ($secret === '') {
            return true;
        }
        http_response_code(403);
        return false;
    }
}
if (!function_exists('service_button_invoice_id')) {
    // The service a button acts on, from its callback data - or null when it
    // is not one of a service's own buttons. Matched anywhere in the data,
    // the way the handlers themselves match them.
    function service_button_invoice_id($datain)
    {
        $datain = (string) $datain;
        if ($datain === '') {
            return null;
        }
        // configget_{id}_{n} and extends_{username}_{id} carry more than the id
        if (preg_match('/configget_([A-Za-z0-9]+)_\w+/', $datain, $m)) {
            return $m[1];
        }
        if (preg_match('/extends_\w*_([A-Za-z0-9]+)$/', $datain, $m)) {
            return $m[1];
        }
        // ⏱'s own: paygcp_{id}_{product} and paygcpok_ carry the id first
        foreach (['paygref_', 'paygpause_', 'paygdel_', 'paygdelok_', 'paygconv_', 'paygcp_', 'paygcpok_', 'paygrm_', 'paygrmok_',
            'updateproduct_', 'product_', 'subscriptionurl_', 'config_', 'extend_', 'changelink_', 'confirmchange_',
            'removeserviceuser_', 'changenote_', 'Extra_volume_', 'Extra_time_', 'changestatus_', 'confirmaccountdisable_',
            'transfer_', 'changeloc_', 'confirmchangeloccha_', 'disorder-', 'confirmdisorders-', 'usagereport_', 'removeauto-', 'subapps_'] as $p) {
            if (preg_match('/' . preg_quote($p, '/') . '([A-Za-z0-9]+)/', $datain, $m)) {
                return $m[1];
            }
        }
        return null;
    }
}
if (!function_exists('speed_limit_parse')) {
    // 🚀 Speed limits - only Rebecca panels have them (its form's «Speed limit»,
    // in Mbps; it keeps them as speed_limit_kbps = Mbps × 1000, 0 = none).
    // A speed someone typed, in Mbps: «10», «2.5», «۵ Mbps», «0» (none) - null
    // when it is not one
    function speed_limit_parse($text)
    {
        $s = trim(strtr((string) $text, [
            '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
            '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
            '٫' => '.', ',' => '.', '،' => '.',
        ]));
        $s = trim((string) preg_replace('/\s*(mbps|mb\/s|مگابیت|مگ)$/iu', '', $s));
        if (!preg_match('/^\d+(\.\d+)?$/', $s) || (float) $s > 100000) {
            return null;
        }
        return round((float) $s, 2);
    }
    // «10», «2.5», «0» - the way it is kept and shown
    function speed_limit_store($mbps)
    {
        $s = rtrim(rtrim(number_format(max(0, (float) $mbps), 2, '.', ''), '0'), '.');
        return $s === '' ? '0' : $s;
    }
    // what Rebecca keeps: kbps
    function speed_limit_kbps($mbps)
    {
        return (int) round(max(0, (float) $mbps) * 1000);
    }
    // can something on $location have one: a Rebecca panel - or every panel
    // ('/all') while at least one of them is Rebecca
    function speed_limit_applies($location)
    {
        global $pdo;
        if ((string) $location === '/all') {
            return (int) $pdo->query("SELECT COUNT(*) FROM marzban_panel WHERE type = 'rebecca'")->fetchColumn() > 0;
        }
        $panel = select("marzban_panel", "*", "name_panel", (string) $location, "select");
        return is_array($panel) && ($panel['type'] ?? '') === 'rebecca';
    }
    // «10 Mbps», or the words for none
    function speed_limit_label($mbps, $none)
    {
        return (float) $mbps > 0 ? speed_limit_store($mbps) . ' Mbps' : $none;
    }
    // A new Rebecca account's speed in kbps (0 = none): what the caller asks
    // for (a referral plan's), else 🎁 اکانت تست's for a test account, else its
    // product's
    function speed_limit_for_new(array $config, $product, array $panel)
    {
        if (isset($config['speed_mbps'])) {
            return speed_limit_kbps($config['speed_mbps']);
        }
        if (is_array($product) && ($product['name_product'] ?? '') === 'usertest') {
            return speed_limit_kbps($panel['speed_usertest'] ?? 0);
        }
        return speed_limit_kbps(is_array($product) ? ($product['speed_limit'] ?? 0) : 0);
    }
}
if (!function_exists('volume_parse')) {
    // A volume someone typed: «10», «0.2», «1.5 گیگ», «200MB», «۲۰۰ مگ» - in
    // $base's unit ('gb' or 'mb'); a bare number is already in it. null when
    // it is not a volume, or not above zero unless $allowZero (0 = no limit).
    // A number starting with a zero, like «05», is refused: 0.5 or 5 - the
    // one who typed it has to say which.
    function volume_parse($text, $base = 'gb', $allowZero = false)
    {
        $s = trim(strtr((string) $text, [
            '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
            '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
            '٫' => '.', ',' => '.', '،' => '.',
        ]));
        if (preg_match('/^0\d/', $s) || !preg_match('/^(\d+(?:\.\d+)?|\.\d+)\s*(mb|m|مگ|مگابایت|مگا\s*بایت|gb|g|گیگ|گیگابایت|گیگا\s*بایت)?$/iu', $s, $m)) {
            return null;
        }
        $n = (float) $m[1];
        $unit = mb_strtolower($m[2] ?? '');
        $isMb = $unit !== '' && in_array(mb_substr($unit, 0, 1), ['m', 'م'], true);
        if ($unit !== '' && $base === 'gb' && $isMb) {
            $n /= 1024;
        } elseif ($unit !== '' && $base === 'mb' && !$isMb) {
            $n *= 1024;
        }
        if ($n < 0 || (!$allowZero && $n <= 0)) {
            return null;
        }
        return $n;
    }
    // a GB amount as it is kept: up to 4 decimals, no trailing zeros
    function volume_store($gb)
    {
        $s = rtrim(rtrim(number_format((float) $gb, 4, '.', ''), '0'), '.');
        return $s === '' ? '0' : $s;
    }
    // ...and as it is shown: up to 2
    function volume_num($gb)
    {
        $s = rtrim(rtrim(number_format((float) $gb, 2, '.', ''), '0'), '.');
        return $s === '' ? '0' : $s;
    }
}
if (!function_exists('service_volume_human')) {
    // A test account's size and length written the way a person would say it:
    // ONE unit, the one that fits, with the word in the reader's language.
    //
    // The panel stores volume in megabytes and time in hours, so a 2 GB service
    // is "2048" and a 30-minute one is "0.5". Printing the stored number with a
    // fixed unit gives "2048 مگابایت" and "0.5 ساعت"; printing both units gives
    // "200 MB / 0.2 GB", which is the same fact twice and reads like a range.
    function bt_trim_number($n)
    {
        $s = rtrim(rtrim(number_format((float) $n, 2, '.', ''), '0'), '.');
        return $s === '' || $s === '-' ? '0' : $s;
    }
    function service_volume_human($mb, $lang)
    {
        return service_volume_text($mb, lang_tab_texts($lang));
    }
    // The same, in the language of the text set $t - the purchase messages use
    // this with the very $textbotlang their template came from, so the unit
    // can never be in a different language from the sentence around it.
    function service_volume_text($mb, $t)
    {
        $m = (float) $mb;
        // the panels treat 0 as "no limit", so saying "0 MB" would be a lie
        if ($m <= 0) {
            return (string) ($t['common']['labels']['unlimitedShort'] ?? '0');
        }
        if ($m >= 1024) {
            return bt_trim_number($m / 1024) . ' ' . (string) ($t['common']['units']['gbShort'] ?? 'GB');
        }
        return bt_trim_number($m) . ' ' . (string) ($t['common']['units']['mbShort'] ?? 'MB');
    }
    function service_time_human($hours, $lang)
    {
        $t = lang_tab_texts($lang);
        $h = (float) $hours;
        if ($h > 0 && $h < 1) {
            return bt_trim_number($h * 60) . ' ' . (string) ($t['common']['units']['minShort'] ?? 'min');
        }
        // "1 hour", not "1 hours"
        $unit = ($h == 1) ? ($t['common']['units']['hourOne'] ?? null) : null;
        return bt_trim_number($h) . ' ' . (string) ($unit ?? $t['common']['units']['hourShort'] ?? 'h');
    }
    // A purchase's length in days: "1 day", "30 days", or unlimited for 0.
    function service_days_text($days, $t)
    {
        $d = (int) $days;
        if ($d <= 0) {
            return (string) ($t['common']['labels']['unlimitedShort'] ?? '0');
        }
        $u = $t['common']['units'] ?? [];
        $unit = ($d === 1) ? ($u['dayOne'] ?? $u['dayShort'] ?? '') : ($u['dayMany'] ?? $u['dayShort'] ?? '');
        return trim($d . ' ' . $unit);
    }
}
if (!function_exists('panel_inbound_ready')) {
    // Is this panel's protocol/inbound actually chosen?
    //
    // marzban_panel.proxies holds it, and a panel created without it will take
    // a service request and fail at the panel's own API - which reaches the
    // customer as a generic "could not create" and tells nobody what is
    // missing. The panel types that do not use inbounds at all are exempt:
    // they either have no such concept or carry their own equivalent.
    function panel_inbound_ready($code_panel)
    {
        $panel = select("marzban_panel", "*", "code_panel", $code_panel, "select");
        if (!is_array($panel)) {
            return false;
        }
        if (in_array((string) ($panel['type'] ?? ''), ['Manualsale', 'WGDashboard', 'ibsng', 'mikrotik', 'hiddify'], true)) {
            return true;
        }
        $raw = trim((string) ($panel['proxies'] ?? ''));
        if ($raw === '' || $raw === 'null' || $raw === '[]' || $raw === '{}') {
            return false;
        }
        $decoded = json_decode($raw, true);
        // a stored value that decodes to nothing usable is the same as unset
        return !(is_array($decoded) && count($decoded) === 0);
    }
}
if (!function_exists('panels_available_count')) {
    // How many panels this customer can actually be shown, asked with the same
    // three filters the lists in keyboard.php use: agent tier, language, and
    // which flow is asking.
    //
    // $kind 'test' counts the test-account panels, anything else the active
    // ones a purchase starts from. Counting the table as a whole - which every
    // gate in index.php used to do - answers a different question: a panel that
    // exists but is not offered in this language passes it, and the customer
    // then lands on a list with nothing in it.
    function panels_available_count($lang, $agent, $kind = 'buy')
    {
        global $pdo;
        $where = ($kind === 'test') ? "TestAccount = 'ONTestAccount'" : "status = 'active'";
        $stmt = $pdo->prepare("SELECT COUNT(*) FROM marzban_panel WHERE {$where} AND (agent = :agent OR agent = 'all') AND (FIND_IN_SET(:userlang, lang) OR lang = 'all' OR lang IS NULL OR lang = '')");
        $stmt->bindValue(':agent', (string) $agent);
        $stmt->bindValue(':userlang', (string) ($lang ?: 'fa'), PDO::PARAM_STR);
        $stmt->execute();
        return (int) $stmt->fetchColumn();
    }
}
if (!function_exists('products_available_count')) {
    // How many products this customer could actually be sold: their agent tier
    // AND their language, the same two filters every product query downstream
    // already applies.
    //
    // Counting the product table as a whole is not the same question - a shop
    // with Persian products and none for English passes that count and then
    // walks its English customers into an empty list.
    function products_available_count($lang, $agent)
    {
        global $pdo;
        $stmt = $pdo->prepare("SELECT COUNT(*) FROM product WHERE agent = :agent AND (FIND_IN_SET(:userlang, lang) OR lang = 'all' OR lang IS NULL OR lang = '')");
        $stmt->bindValue(':agent', (string) $agent);
        $stmt->bindValue(':userlang', (string) ($lang ?: 'fa'), PDO::PARAM_STR);
        $stmt->execute();
        return (int) $stmt->fetchColumn();
    }
}
if (!function_exists('bt_item_enabled')) {
    // Per-language on/off for the message items that have a switch.
    //
    // Only the items listed here have one; everything else is always on, so a
    // key that is not in this map can never be silenced by accident. The
    // shipped defaults differ per item on purpose:
    //
    //   users.unknownMsg  off - the bot speaking uninvited, so an owner opts in
    //   users.text_start  on  - this one gates the welcome STICKER only, not the
    //                           text: the welcome message carries the main
    //                           keyboard, and a bot that does not send it leaves
    //                           the customer with no menu at all
    function bt_item_switch_defaults()
    {
        return [
            'users.unknownMsg' => false,
            'users.text_start' => true,
            // 🔋 پیام‌های هشدار و اتمام سرویس: every message the bot sends on
            // its own about a service running out - on until a tab turns it off
            'textbot.testExpired' => true,
            // the tier kinds have no text key of their own; these name them
            'volpct.vol' => true,
            'volpct.volgb' => true,
            'volpct.time' => true,
            'volpct.timeend' => true,
            'volpct.volend' => true,
        ];
    }
    // What the switch says on the item's own screen - each one names what it
    // actually turns off, because those two are not the same thing.
    function bt_item_switch_label($key)
    {
        return [
            'users.unknownMsg' => 'جواب خودکار',
            'users.text_start' => 'استیکر خوش‌آمد',
            'textbot.testExpired' => 'ارسال این پیام',
            'volpct.vol' => 'ارسال این پیام‌ها',
            'volpct.volgb' => 'ارسال این پیام‌ها',
            'volpct.time' => 'ارسال این پیام‌ها',
            'volpct.timeend' => 'ارسال این پیام',
            'volpct.volend' => 'ارسال این پیام',
        ][$key] ?? 'این قابلیت';
    }
    function bt_item_switch_map($fresh = false)
    {
        static $cache = null;
        if ($cache !== null && !$fresh) {
            return $cache;
        }
        $setting = select("setting", "*", null, null, "select");
        $m = json_decode((string) ($setting['bt_item_lang'] ?? ''), true);
        return $cache = is_array($m) ? $m : [];
    }
    // Strictly this language's own value - no inheriting from Persian the way
    // feature_value() does, because switching something on for Persian must not
    // switch it on for English customers.
    function bt_item_enabled($key, $lang)
    {
        $defaults = bt_item_switch_defaults();
        if (!array_key_exists($key, $defaults)) {
            return true;
        }
        $m = bt_item_switch_map();
        $v = $m[$key][$lang] ?? null;
        if ($v === null || $v === '') {
            return (bool) $defaults[$key];
        }
        return (string) $v === '1';
    }
    function bt_item_set_enabled($key, $lang, $on)
    {
        $m = bt_item_switch_map(true);
        if (!isset($m[$key]) || !is_array($m[$key])) {
