            'fa' => 'Asia/Tehran',
            'en' => 'UTC',
        ];
        return $map[$lang] ?? 'UTC';
    }
}
if (!function_exists('format_datetime')) {
    // language-aware date/time: Persian users see the Jalali calendar on Tehran
    // time; every other language sees the Gregorian calendar on that language's
    // approximate local time. Format tokens (Y/m/d H:i:s ...) match jdate()'s.
    function format_datetime($format, $timestamp = null, $lang = 'fa')
    {
        if ($timestamp === null || $timestamp === '') {
            $ts = time();
        } elseif (is_numeric($timestamp)) {
            $ts = (int) $timestamp;
        } else {
            $ts = strtotime($timestamp);
        }
        $tz = lang_timezone($lang);
        if ($lang === 'fa') {
            return jdate($format, $ts, '', $tz);
        }
        $prevTz = date_default_timezone_get();
        date_default_timezone_set($tz);
        $out = date($format, $ts);
        date_default_timezone_set($prevTz);
        return $out;
    }
}
function generateAuthStr($length = 10)
{
    $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    return substr(str_shuffle(str_repeat($characters, ceil($length / strlen($characters)))), 0, $length);
}
function createqrcode($contents)
{
    $builder = new Builder(
        writer: new PngWriter(),
        writerOptions: [],
        data: $contents,
        encoding: new Encoding('UTF-8'),
        errorCorrectionLevel: ErrorCorrectionLevel::High,
        size: 500,
        margin: 10,
    );

    $result = $builder->build();
    return $result;
}
function sanitize_recursive(array $data): array
{
    $sanitized_data = [];
    foreach ($data as $key => $value) {
        $sanitized_key = htmlspecialchars($key, ENT_QUOTES, 'UTF-8');
        if (is_array($value)) {
            $sanitized_data[$sanitized_key] = sanitize_recursive($value);
        } elseif (is_string($value)) {
            $sanitized_data[$sanitized_key] = htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
        } elseif (is_int($value)) {
            $sanitized_data[$sanitized_key] = filter_var($value, FILTER_SANITIZE_NUMBER_INT);
        } elseif (is_float($value)) {
            $sanitized_data[$sanitized_key] = filter_var($value, FILTER_SANITIZE_NUMBER_FLOAT, FILTER_FLAG_ALLOW_FRACTION);
        } elseif (is_bool($value) || is_null($value)) {
            $sanitized_data[$sanitized_key] = $value;
        } else {
            $sanitized_data[$sanitized_key] = $value;
        }
    }
    return $sanitized_data;
}

function check_active_btn($keyboard, $text_var)
{
    $trace_keyboard = json_decode($keyboard, true)['keyboard'];
    $status = false;
    foreach ($trace_keyboard as $key => $callback_set) {
        foreach ($callback_set as $keyboard_key => $keyboard) {
            if ($keyboard['text'] == $text_var) {
                $status = true;
                break;
            }
        }
    }
    return $status;
}
function deleteFolder($folderPath)
{
    if (!is_dir($folderPath))
        return false;

    $files = array_diff(scandir($folderPath), ['.', '..']);

    foreach ($files as $file) {
        $filePath = $folderPath . DIRECTORY_SEPARATOR . $file;
        if (is_dir($filePath)) {
            deleteFolder($filePath);
        } else {
            unlink($filePath);
        }
    }

    return rmdir($folderPath);
}
function isBase64($string)
{
    if (base64_encode(base64_decode($string, true)) === $string) {
        return true;
    }
    return false;
}
if (!function_exists('telegram_html_chunks')) {
    // Telegram refuses a text message over 4096 characters (counted after the
    // HTML is parsed), and a purchase message listing every config of a big
    // service passes that easily - it then arrived as nothing at all. Splits
    // at line breaks only; a tag still open at a cut is closed at the end of
    // that piece and reopened at the start of the next, so every piece parses
    // on its own. A single plain line over the limit is cut by length.
    function telegram_html_chunks($html, $limit = 4000)
    {
        $len = static function ($s) {
            return mb_strlen(html_entity_decode(strip_tags((string) $s), ENT_QUOTES, 'UTF-8'), 'UTF-8');
        };
        $html = (string) $html;
        if ($len($html) <= $limit) {
            return [$html];
        }
        $lines = [];
        foreach (explode("\n", $html) as $line) {
            if ($len($line) > $limit && strpos($line, '<') === false) {
                foreach (mb_str_split($line, $limit, 'UTF-8') as $piece) {
                    $lines[] = $piece;
                }
            } else {
                $lines[] = $line;
            }
        }
        $chunks = [];
        $cur = '';
        $open = [];
        foreach ($lines as $line) {
            $next = ($cur === '') ? $line : $cur . "\n" . $line;
            if ($cur !== '' && $len($next) > $limit) {
                $close = '';
                foreach (array_reverse($open) as $t) {
                    $close .= '</' . $t[0] . '>';
                }
                $chunks[] = $cur . $close;
                $reopen = '';
                foreach ($open as $t) {
                    $reopen .= $t[1];
                }
                $next = $reopen . $line;
            }
            $cur = $next;
            if (preg_match_all('#<(/?)([a-zA-Z][a-zA-Z0-9-]*)[^>]*>#', $line, $m, PREG_SET_ORDER)) {
                foreach ($m as $tag) {
                    $name = strtolower($tag[2]);
                    if ($tag[1] === '/') {
                        for ($i = count($open) - 1; $i >= 0; $i--) {
                            if ($open[$i][0] === $name) {
                                array_splice($open, $i, 1);
                                break;
                            }
                        }
                    } else {
                        $open[] = [$name, $tag[0]];
                    }
                }
            }
        }
        $chunks[] = $cur;
        // Telegram also refuses an empty message
        return array_values(array_filter($chunks, static function ($c) {
            return trim(strip_tags($c)) !== '';
        }));
    }
}
function sendMessageService($panel_info, $config, $sub_link, $username_service, $reply_markup, $caption, $invoice_id, $user_id = null, $image = 'images.jpg', $kind = 'purchase')
{
    global $setting, $from_id, $textbotlang;
    $user_id = $user_id == null ? $from_id : $user_id;
    // the RECIPIENT's menu decides whether the tutorial button is offered, and
    // it is resolved after $user_id for that reason - the menu is per language
    // now, so the sender's own copy would be the wrong one to ask
    $sms_row = select("user", "lang", "id", $user_id, "select");
    $sms_lang = $sms_row['lang'] ?? 'fa';
    if (!mainmenu_btn_active($sms_lang, "text_help"))
        $reply_markup = null;
    // a purchase, a test account and a 🎁 referral gift also carry the buttons
    // the service has in 🛍 سرویس‌های من (🌐, 📲, 🔰, 💡 ...), above the
    // tutorial button
    if (statusbtn_kind_of_delivery($kind) !== null) {
        $sms_actions = delivery_action_rows($kind, $user_id, $invoice_id, $sms_lang, $panel_info, $sub_link);
        if ($sms_actions) {
            $sms_help = is_string($reply_markup) ? (json_decode($reply_markup, true)['inline_keyboard'] ?? []) : [];
            $reply_markup = json_encode(['inline_keyboard' => array_merge($sms_actions, $sms_help)]);
        }
    }
    $configCount = is_array($config) ? count($config) : 0;
    // Mode 2 is the config page INSTEAD of the full message, not as well as it
    // (it used to send both, which read as "mode 1 is still on"). It needs the
    // panel's «ارسال کانفیگ» and at least one config; without them there is no
    // page to show, so the customer gets the full message (mode 1) instead of
    // nothing. No QR either way in mode 2.
    if ($panel_info['config'] == "onconfig" && $configCount > 0
        && config_delivery_mode($kind, $panel_info['code_panel'] ?? null, $sms_lang) === "2") {
        $cd_hintKey = ['usertest' => 'textbot.getConfigHintTest', 'affrw' => 'users.affiliates.rewardConfigHint'][$kind] ?? 'textbot.getConfigHintBuy';
        // an admin can be the one approving a 🎁 gift, so it is worded in the
        // recipient's language rather than the reader's
        // the recipient's tab, as everything else here: an admin approving a
        // receipt or a 🎁 gift is the one whose request this is
        $cd_hintText = bottext_resolve_key($cd_hintKey, $sms_lang);
        // sendMessageService's own $kind is 'purchase'|'usertest' - keyboard_config()'s
        // is 'usertest'|'buy', so normalize rather than let 'purchase' silently
        // fall through to the usertest column/button settings below.
        $cc_kbKind = ['usertest' => 'usertest', 'affrw' => 'affrw'][$kind] ?? 'buy';
        $cd_kb = json_decode(keyboard_config($config, $invoice_id, false, $cc_kbKind, $sms_lang), true);
        // the 📚 tutorial button the full message carried comes along underneath
        $cd_help = is_string($reply_markup) ? json_decode($reply_markup, true) : null;
        if (is_array($cd_help) && !empty($cd_help['inline_keyboard'])) {
            foreach ($cd_help['inline_keyboard'] as $cd_row) {
                $cd_kb['inline_keyboard'][] = $cd_row;
            }
        }
        sendmessage($user_id, $cd_hintText !== '' ? $cd_hintText : lang_tab_texts($sms_lang)['hardcoded']['getConfigHint'], json_encode($cd_kb), 'HTML');
        return;
    }
    // the full message, split when it runs past Telegram's length limit; the
    // buttons go under the last piece
    $sendFull = static function ($text) use ($user_id, $reply_markup) {
        $parts = telegram_html_chunks($text);
        $last = count($parts) - 1;
        foreach ($parts as $i => $part) {
            sendmessage($user_id, $part, $i === $last ? $reply_markup : null, 'HTML');
        }
    };
    // 🖼 the message's own sticker (🎨) goes first, the way sendmessage() sends
    // one before a text - the QR photo and the WireGuard file below would
    // otherwise go out without it. Sent once: the text fallback won't repeat it.
    if (function_exists('bottext_send_extras')) {
        bottext_send_extras($user_id, $caption);
    }
    if ($panel_info['type'] == "WGDashboard") {
        // WireGuard delivers its .conf file rather than a QR - unchanged
        if ($panel_info['config'] == "onconfig" && $configCount != 1) {
            $sendFull($caption);
        } else {
            $urlimage = "{$panel_info['inboundid']}_{$invoice_id}.conf";
            file_put_contents($urlimage, $sub_link);
            telegram('senddocument', [
                'chat_id' => $user_id,
                'document' => new CURLFile($urlimage),
                'reply_markup' => $reply_markup,
                'caption' => $caption,
                'parse_mode' => "HTML",
            ]);
            unlink($urlimage);
        }
    } else {
        // «ارسال کانفیگ» on: the message goes first WITHOUT the config links,
        // then every config follows on a message of its own - a photo of its
        // own QR with the link under it when the QR is on, as 🛍's «دریافت
        // کانفیگ» sends it, the link alone when not. All of them in the one
        // caption ran past Telegram's 1024 characters, and the photo then came
        // apart from its text.
        $cfgLinks = $panel_info['config'] == "onconfig" && is_array($config)
            ? array_values(array_filter(array_map(fn($c) => trim((string) $c), $config), 'strlen'))
            : [];
        if ($cfgLinks) {
            $caption = service_caption_without_configs($caption, $cfgLinks);
        }
        $qrOn = config_delivery_qr_on($kind, $panel_info['code_panel'] ?? null, $sms_lang);
        // The first message's QR is the subscription link, which covers every
        // config; the configs bring their own.
        $out_put_qrcode = $panel_info['sublink'] == "onsublink" ? (string) $sub_link : "";
        $captionSent = false;
        if ($out_put_qrcode !== '' && $qrOn) {
            $urlimage = "$user_id$invoice_id.png";
            try {
                $qrCode = createqrcode($out_put_qrcode);
                file_put_contents($urlimage, $qrCode->getString());
                addBackgroundImage($urlimage, $qrCode, $image);
                // a photo caption is capped at 1024 characters - a longer message
                // (several config links) follows the QR as its own text instead
                $captionFits = mb_strlen(html_entity_decode(strip_tags((string) $caption), ENT_QUOTES, 'UTF-8')) <= 1024;
                $res = telegram('sendphoto', [
                    'chat_id' => $user_id,
                    'photo' => new CURLFile($urlimage),
                    'reply_markup' => $captionFits ? $reply_markup : null,
                    'caption' => $captionFits ? $caption : '',
                    'parse_mode' => "HTML",
                ]);
                $captionSent = $captionFits && !empty($res['ok']);
            } catch (\Throwable $e) {
                error_log('sendMessageService QR: ' . $e->getMessage());
            }
            if (is_file($urlimage)) {
                unlink($urlimage);
            }
        }
        // the service details must reach the customer even when the QR could not
        if (!$captionSent) {
            $sendFull($caption);
        }
        foreach ($cfgLinks as $i => $link) {
            config_send_one($user_id, $link, $qrOn, $image, "{$user_id}{$invoice_id}_{$i}.png");
        }
    }
}
if (!function_exists('service_caption_without_configs')) {
    // A new service's message with its config links taken out - they follow on
    // messages of their own (sendMessageService). What held them is tidied: an
    // emptied <code></code>, and the blank lines left behind.
    function service_caption_without_configs($caption, array $links)
    {
        $out = str_replace($links, '', (string) $caption);
        $out = preg_replace('~<code>\s*</code>~u', '', $out);
        $out = preg_replace("~[ \t]+\n~u", "\n", $out);
        $out = preg_replace("~\n{3,}~u", "\n\n", $out);
        return rtrim($out);
    }
}
if (!function_exists('config_send_one')) {
    // One config on a message of its own: a photo of its QR on $image with the
    // link under it, exactly as 🛍's «دریافت کانفیگ» sends one - or the link
    // alone, with the QR off or when the photo cannot be made or sent.
    function config_send_one($chatId, $link, $withQr, $image, $file)
    {
        $caption = "<code>{$link}</code>";
        if ($withQr) {
            try {
                $qrCode = createqrcode($link);
                file_put_contents($file, $qrCode->getString());
                addBackgroundImage($file, $qrCode, $image);
                $res = telegram('sendphoto', [
                    'chat_id' => $chatId,
                    'photo' => new CURLFile($file),
                    'caption' => $caption,
                    'parse_mode' => "HTML",
                ]);
                if (is_file($file)) {
                    unlink($file);
                }
                if (!empty($res['ok'])) {
                    return;
                }
            } catch (\Throwable $e) {
                error_log('config_send_one QR: ' . $e->getMessage());
                if (is_file($file)) {
                    unlink($file);
                }
            }
        }
        sendmessage($chatId, $caption, null, 'HTML');
    }
}
function isValidInvitationCode($setting, $fromId, $verfy_status, $lang = 'fa')
{
    global $textbotlang;

    if (feature_value('verifybucodeuser', $lang, $setting['verifybucodeuser']) == "onverify" && $verfy_status != 1) {
        sendmessage($fromId, $textbotlang['hardcoded']['accountVerifiedSuccess'], null, 'html');
        update("user", "verify", "1", "id", $fromId);
        update("user", "cardpayment", "1", "id", $fromId);
    }
}
function createPayZarinpal($price, $order_id)
{
    global $domainhosts;
    $marchent_zarinpal = select("PaySetting", "ValuePay", "NamePay", "merchant_zarinpal", "select")['ValuePay'];
    $curl = curl_init();
    curl_setopt_array($curl, array(
        CURLOPT_URL => 'https://payment.zarinpal.com/pg/v4/payment/request.json',
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => '',
        CURLOPT_MAXREDIRS => 10,
        CURLOPT_TIMEOUT => 0,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_CUSTOMREQUEST => 'POST',
        CURLOPT_HTTPHEADER => array(
            'Content-Type: application/json',
            'Accept: application/json'
        ),
    ));
    curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode([
        "merchant_id" => $marchent_zarinpal,
        "currency" => "IRT",
        "amount" => $price,
        "callback_url" => "https://$domainhosts/payment/zarinpal.php",
        "description" => $order_id,
        "metadata" => array(
            "order_id" => $order_id
        )
    ]));
    $response = curl_exec($curl);
    curl_close($curl);
    return json_decode($response, true);
}
// FrenzyEx (درگاه ارزی ریالی) - creates one v1 payment request per top-up
// attempt and hands back the whole decoded response (plus the real HTTP
// status, since a failure here is a status code, not a body field like
// zarinpal's own 'code'). Never retried on an uncertain result (the guide's
// own create endpoint has no idempotency key) - the caller's message-replace
// ordering (delete-then-show-placeholder, same as every redirect gateway
// already does) is what keeps a second tap from creating a second request.
// ---- three rial gateways from the original bot: CubePay, AbanGateway, Variza ----
// Each one settles through its own callback in payment/, which claims the
// payment (payment_claim) before crediting it, like every gateway here.
if (!function_exists('cubepay_payable_amount')) {
    // CubePay can pass its fee on to the customer: «cubepay_fee» up to 100 is a
    // percentage, above 100 a fixed amount in toman; 0 or empty is no fee
    function cubepay_payable_amount($price)
    {
        $fee = (float) str_replace([',', '،'], '', (string) getPaySettingValue('cubepay_fee', '0'));
        $base = (int) round((float) $price);
        if ($fee <= 0) {
            return $base;
        }
        // rounded first: 50000 × 1.1 is 55000.000000000007 in floating point,
        // which ceil() would turn into 55001
        return $fee <= 100 ? (int) ceil(round($base * (1 + $fee / 100), 4)) : $base + (int) round($fee);
    }
    function createPayCubePay($price, $order_id)
    {
        global $domainhosts;
        $token = trim((string) getPaySettingValue('cubepay_api_token', ''));
        if ($token === '' || $token === '0') {
            return ['success' => false, 'message' => 'cubepay: the API token is not set'];
        }
        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => 'https://cubevps.ir/pay/create-order.php',
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Authorization: Bearer ' . $token],
            CURLOPT_POSTFIELDS => json_encode([
                'price_amount' => cubepay_payable_amount($price),
                'order_id' => $order_id,
                'callback_url' => "https://$domainhosts/payment/cubepay.php",
                'redirect_after_payment' => false,
            ], JSON_UNESCAPED_UNICODE),
        ]);
        $response = curl_exec($curl);
        curl_close($curl);
        $decoded = json_decode((string) $response, true);
        if (!is_array($decoded)) {
            return ['success' => false, 'message' => 'cubepay: no answer it could read'];
        }
        if (empty($decoded['payment_link']) && !empty($decoded['pay_page_url'])) {
            $decoded['payment_link'] = $decoded['pay_page_url'];
        }
        return $decoded;
    }
    // CubePay may ask for its card to be shown in the chat as well: the card,
    // its holder, the EXACT amount (its last digits identify the payment) and
    // how long it stays open. null when it did not ask.
    function cubepay_card_details_text($payment, $textbotlang)
    {
        if (!is_array($payment) || empty($payment['show_card_in_bot']) || empty($payment['card']['number'])) {
            return null;
        }
        $amount = (int) ($payment['pay_amount_toman'] ?? 0);
        $minutes = (int) ($payment['expires_in_minutes'] ?? 0);
        $template = (string) ($textbotlang['users']['Balance']['cubepayCardDetails'] ?? '');
        if ($amount < 1 || $minutes < 1 || $template === '') {
            return null;
        }
        $holder = trim((string) ($payment['card']['holder'] ?? ''));
        return sprintf(
            $template,
            htmlspecialchars((string) $payment['card']['number'], ENT_QUOTES, 'UTF-8'),
            htmlspecialchars($holder === '' ? '-' : $holder, ENT_QUOTES, 'UTF-8'),
            number_format($amount),
            $minutes
        );
    }
}
if (!function_exists('abangateway_endpoint')) {
    // AbanGateway runs on the merchant's own address - https only, never a
    // plain one the API key would travel over in the clear
    function abangateway_endpoint()
    {
        $endpoint = trim((string) getPaySettingValue('abangateway_endpoint', ''));
        $parts = parse_url($endpoint);
        if ($endpoint === '' || $endpoint === '0' || !is_array($parts) || ($parts['scheme'] ?? '') !== 'https' || ($parts['host'] ?? '') === '') {
            return null;
        }
        return rtrim($endpoint, '/');
    }
    function createPayAbanGateway($price, $order_id)
    {
        global $domainhosts;
        $key = trim((string) getPaySettingValue('abangateway_api_key', ''));
        $endpoint = abangateway_endpoint();
        if ($key === '' || $key === '0' || $endpoint === null) {
            return ['success' => false, 'message' => 'abangateway: the API key or the https address is not set'];
        }
        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => $endpoint . '/create',
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 25,
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json', 'Authorization: Bearer ' . $key],
            CURLOPT_POSTFIELDS => json_encode([
                'amount' => (int) round((float) $price),
                'order_id' => $order_id,
                'callback_url' => "https://$domainhosts/payment/abangateway.php",
            ], JSON_UNESCAPED_UNICODE),
        ]);
        $response = curl_exec($curl);
        curl_close($curl);
        $decoded = json_decode((string) $response, true);
        return is_array($decoded) ? $decoded : ['success' => false, 'message' => 'abangateway: no answer it could read'];
    }
    // «abangateway_dailylimit»: once today's paid total reaches it, the gateway
    // says it is busy until tomorrow. 0 or empty is no limit.
    function abangateway_over_daily_limit()
    {
        global $pdo;
        $limit = (int) getPaySettingValue('abangateway_dailylimit', '0');
        if ($limit <= 0) {
            return false;
        }
        $stmt = $pdo->prepare("SELECT SUM(price) FROM Payment_report WHERE Payment_Method = 'AbanGateway' AND payment_Status = 'paid' AND time LIKE ?");
        $stmt->execute([date('Y/m/d') . '%']);
        return (float) $stmt->fetchColumn() >= $limit;
    }
}
if (!function_exists('createPayVariza')) {
    // Variza's panel asks for this address (profile → webhook); it is shown,
    // with a copy button, on the gateway's settings screen
    function variza_webhook_url()
    {
        global $domainhosts;
        return "https://{$domainhosts}/payment/variza_webhook.php";
    }
    function createPayVariza($price, $order_id)
    {
        global $domainhosts;
        $token = trim((string) getPaySettingValue('variza_api_token', ''));
        if ($token === '' || $token === '0') {
            return ['error' => 'variza: the API token is not set'];
        }
        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => 'https://variza.ir/api/v1/pay',
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json', 'Authorization: Bearer ' . $token],
            CURLOPT_POSTFIELDS => json_encode([
                'amount' => (int) round((float) $price),
                'return_url' => "https://{$domainhosts}/payment/variza.php?order=" . rawurlencode((string) $order_id),
                'title' => 'Order ' . $order_id,
                'expires_in' => '1h',
            ], JSON_UNESCAPED_UNICODE),
        ]);
        $response = curl_exec($curl);
        if ($response === false) {
            $err = curl_error($curl);
            curl_close($curl);
            return ['error' => 'variza: ' . $err];
        }
        $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        curl_close($curl);
        $decoded = json_decode((string) $response, true);
        if (!is_array($decoded) || $httpCode < 200 || $httpCode >= 300) {
            return ['error' => 'variza: HTTP ' . $httpCode, 'raw' => mb_substr((string) $response, 0, 300)];
        }
        return $decoded;
    }
}
if (!function_exists('payment_result_page')) {
    // The page a customer's browser lands on after paying: ✓ paid, ✓ already
    // paid, ✕ not confirmed, ⏱ still waiting, ? unknown order - in the
    // customer's own language, with the order and amount and a way back to the
    // bot. $state: success, already, failed, waiting, notfound.
    function payment_result_page($state, $texts, $orderId = null, $price = null, $lang = 'fa')
    {
        global $usernamebot;
        $pg = is_array($texts) && isset($texts['paymentGateway']) ? $texts['paymentGateway'] : [];
        $pick = function ($key, $fallback) use ($pg) {
            return isset($pg[$key]) && $pg[$key] !== '' ? $pg[$key] : $fallback;
        };
        $map = [
            'success' => ['✓', '#2ecc71', $pick('resultSuccessTitle', 'Payment completed'), $pick('resultSuccessText', '')],
            'already' => ['✓', '#2ecc71', $pick('resultAlreadyTitle', 'Already confirmed'), $pick('resultAlreadyText', '')],
            'failed' => ['✕', '#e74c3c', $pick('resultFailedTitle', 'Payment was not confirmed'), $pick('resultFailedText', '')],
            'waiting' => ['⏳', '#3498db', $pick('resultWaitingTitle', 'Waiting for confirmation'), $pick('resultWaitingText', '')],
            'notfound' => ['?', '#e67e22', $pick('resultNotFoundTitle', 'Transaction not found'), $pick('resultNotFoundText', '')],
        ];
        [$icon, $colour, $title, $body] = $map[$state] ?? $map['failed'];
        $h = fn($s) => htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8');
        $dir = $lang === 'fa' ? 'rtl' : 'ltr';
        $rows = '';
        if ($orderId !== null && $orderId !== '') {
            $rows .= '<div class="row"><span>' . $h($pick('resultOrderLabel', 'Order id')) . '</span><b>' . $h($orderId) . '</b></div>';
        }
        if ($price !== null && (float) $price > 0) {
            $rows .= '<div class="row"><span>' . $h($pick('resultAmountLabel', 'Amount')) . '</span><b>' . number_format((float) $price) . '</b></div>';
        }
        $bot = ltrim(trim((string) $usernamebot), '@');
        $back = ($bot !== '' && preg_match('/^[A-Za-z0-9_]+$/', $bot))
            ? '<a class="btn" href="https://t.me/' . $h($bot) . '">' . $h($pick('resultBackToBot', 'Back to the bot')) . '</a>' : '';
        if (!headers_sent()) {
            header('Content-Type: text/html; charset=utf-8');
        }
        echo '<!DOCTYPE html><html lang="' . $h($lang) . '" dir="' . $dir . '"><head><meta charset="utf-8">'
            . '<meta name="viewport" content="width=device-width, initial-scale=1"><title>' . $h($title) . '</title><style>'
            . 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#0f1115;color:#e8eaed;font-family:Tahoma,Arial,sans-serif;padding:20px}'
            . '.card{width:100%;max-width:360px;background:#181b21;border:1px solid #262a33;border-radius:18px;padding:28px 24px;text-align:center}'
            . '.icon{width:58px;height:58px;line-height:58px;border-radius:50%;margin:0 auto 14px;font-size:28px;color:#fff;background:' . $colour . '}'
            . 'h1{font-size:17px;margin:0 0 8px}p{color:#9aa0aa;font-size:13px;line-height:2;margin:0}'
            . '.rows{margin-top:18px}.row{display:flex;justify-content:space-between;gap:12px;font-size:12.5px;border-top:1px solid #262a33;padding:9px 0;color:#9aa0aa}.row b{color:#e8eaed}'
            . '.btn{display:block;margin-top:18px;padding:11px;border-radius:11px;background:#2b6ef2;color:#fff;text-decoration:none;font-size:13.5px}'
            . '</style></head><body><div class="card"><div class="icon">' . $icon . '</div><h1>' . $h($title) . '</h1><p>' . $h($body) . '</p>'
            . ($rows !== '' ? '<div class="rows">' . $rows . '</div>' : '') . $back . '</div></body></html>';
    }
}
if (!function_exists('frenzyex_callback_url')) {
    // the completion-webhook address FrenzyEx's own merchant panel asks for,
    // built from the bot's own domain so the admin never types it by hand.
    // Unlike sms_forward_webhook_url() this carries no secret in the URL -
    // payment/frenzyex.php authenticates the caller by the X-Frenzy-Signature
    // HMAC instead, so the address is safe to show on screen.
    function frenzyex_callback_url()
    {
        global $domainhosts;
        return "https://{$domainhosts}/payment/frenzyex.php";
    }
    // FrenzyEx's public address. config.php can name another one if FrenzyEx
    // ever moves - the same way RBN_GITHUB_API names a mirror for rbnodes.php.
    // config.php is read more than once per request (function.php requires
    // it again), so it has to be written guarded:
    //   defined('FRENZYEX_API_BASE') || define('FRENZYEX_API_BASE', 'https://...');
    function frenzyex_api_base()
    {
        return defined('FRENZYEX_API_BASE') ? rtrim((string) FRENZYEX_API_BASE, '/') : 'https://frenzy.fastsnap.info';
    }
    // Since guide v4 the callback address can travel with each payment
    // request, so the admin does not have to get it registered with FrenzyEx
    // first. FrenzyEx refuses an address it cannot use (HTTP 400, nothing
    // created); when that happens the request is made again without it and
    // the account-level address is used. The refusal is remembered for a day,
    // so every invoice does not cost two requests out of FrenzyEx's ten a
    // minute, and the admin is told once to register the address instead.
    function frenzyex_callback_flag_file()
    {
        return __DIR__ . '/storage/frenzyex_callback_refused';
    }
    function frenzyex_callback_refused_recently()
    {
        $at = (int) @file_get_contents(frenzyex_callback_flag_file());
        return $at > 0 && time() - $at < 86400;
    }
    function frenzyex_callback_mark_refused()
    {
        $file = frenzyex_callback_flag_file();
        if (!is_dir(dirname($file))) {
            @mkdir(dirname($file), 0775, true);
        }
        @file_put_contents($file, (string) time(), LOCK_EX);
    }
}
// One POST to FrenzyEx's v1 create endpoint: the real HTTP status and the
// decoded body. Never retried here - see createPayFrenzyEx().
function frenzyex_create_request($apiKey, array $body)
{
    $curl = curl_init();
    curl_setopt_array($curl, array(
        CURLOPT_URL => frenzyex_api_base() . '/api/v1/payment-requests',
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => '',
        CURLOPT_MAXREDIRS => 10,
        // bounded, unlike the other gateways' CURLOPT_TIMEOUT => 0: FrenzyEx's
        // own guide is explicit that a hung create call must never be retried
        // blindly, so a request that cannot finish in reasonable time should
        // fail cleanly instead of holding the customer's tap open indefinitely
        CURLOPT_TIMEOUT => 20,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_CUSTOMREQUEST => 'POST',
        CURLOPT_HTTPHEADER => array(
            'Content-Type: application/json',
            'Accept: application/json',
            'Authorization: Bearer ' . $apiKey,
        ),
    ));
    curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($body));
    $response = curl_exec($curl);
    $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
    curl_close($curl);
    $decoded = json_decode((string) $response, true);
    return [
        'http_code' => $httpCode,
        'body' => is_array($decoded) ? $decoded : [],
    ];
}
function createPayFrenzyEx($price, $order_id)
{
    $apiKey = select("PaySetting", "ValuePay", "NamePay", "frenzyex_api_key", "select")['ValuePay'];
    $body = [
        'amount' => $price,
        'amount_ccy' => 'TMN',
        'payment_method' => 'auto',
        'order_ref' => $order_id,
        'description' => 'TopUp - ' . $order_id,
    ];
    if (frenzyex_callback_refused_recently()) {
        return frenzyex_create_request($apiKey, $body);
    }
    $pay = frenzyex_create_request($apiKey, $body + ['callback_url' => frenzyex_callback_url()]);
    // Only a 400 is asked again: the guide says a refused callback_url
    // returns 400 and creates nothing, so the second request cannot make a
    // second checkout. Any other failure (a timeout above all) is returned
    // as it is - a POST is never repeated after an uncertain result.
    if ($pay['http_code'] !== 400) {
        return $pay;
    }
    $retry = frenzyex_create_request($apiKey, $body);
    if ($retry['http_code'] >= 200 && $retry['http_code'] < 300) {
        // the address was the reason: remembered, logged, and the admin told
        frenzyex_callback_mark_refused();
        error_log('frenzyex: the per-request callback_url was refused (HTTP 400: ' . mb_substr(json_encode($pay['body']), 0, 200)
            . ') - invoices are made without it for a day; the address registered with FrenzyEx is used');
        $setting = select("setting", "Channel_Report", null, null, "select");
        if (strlen((string) ($setting['Channel_Report'] ?? '')) > 0) {
            telegram('sendmessage', [
                'chat_id' => $setting['Channel_Report'],
                'message_thread_id' => select("topicid", "idreport", "report", "errorreport", "select")['idreport'] ?? null,
                'text' => sprintf(
                    "⚠️ FrenzyEx آدرس کال‌بک ربات رو همراه فاکتور قبول نکرد، پس فاکتورها بدون اون ساخته می‌شن.\n\n"
                    . "برای اینکه پرداخت‌ها خودکار تایید بشن، این آدرس رو توی پنل FrenzyEx (بخش وبهوک) ثبت کن یا به پشتیبانی FrenzyEx بده:\n<code>%s</code>\n\n"
                    . "تا وقتی ثبت نشه، ربات هر ۳ دقیقه خودش وضعیت پرداخت‌ها رو از FrenzyEx می‌پرسه.",
                    htmlspecialchars(frenzyex_callback_url())
                ),
                'parse_mode' => "HTML",
            ]);
        }
    }
    return $retry;
}
// ---- درگاه ارزی ریالی ترونادو (Tronado, API v5) ----
// The invoice is in toman; Tronado's own page (inside Telegram) takes the
// customer's payment and sends the shop TRX for it. The steps, from Tronado's
// own guide (miniapp.tronado.cloud/assets/api-docs.md):
//   1. /Tron/GetPriceToToman  - Tronado's own TRX price, not an exchange's
//   2. /api/v5/GetOrderToken  - PaymentID is this bot's id_order
//   3. the customer pays on t.me/tronado_robot/customerpayment?startapp=TOKEN
//   4. Tronado POSTs a signed IPN on every status change of the order
//      (payment/tronado_ipn.php); cronbot/tronado.php asks about the orders
//      whose IPN never came. Both credit through tronado_settle() only.
// It replaced the original bot's own Tronado gateway (iranpay2, an older
// endpoint without signed callbacks), which has been removed.
if (!function_exists('tronado_callback_url')) {
    // where Tronado sends the IPN. Its domain has to be registered with
    // Tronado's support first, or no IPN is sent at all - so the settings
    // screen shows it with a copy button.
    function tronado_callback_url()
    {
        global $domainhosts;
        return "https://{$domainhosts}/payment/tronado_ipn.php";
    }
    // the smallest invoice Tronado itself accepts, in toman; 0 = none. An
    // empty or unreadable value is Tronado's own 150,000.
    function tronado_min_toman()
    {
        $raw = trim((string) getPaySettingValue('tronado_min_amount', ''));
        $v = money_normalize($raw);
        return $raw === '' || $v === null ? 150000 : max(0, (int) round((float) $v));
    }
    // a setting the admin never filled reads back as the row's default '0'
    function tronado_setting($name)
    {
        $v = trim((string) getPaySettingValue($name, ''));
        return $v === '0' ? '' : $v;
    }
    // how much of Tronado's fee the shop takes on (wageFromBusinessPercentage):
    // 0 = the customer pays all of it on top of the invoice (Tronado's own
    // default), 100 = the shop pays all of it. Anything unreadable is 0.
    function tronado_wage_percent()
    {
        $v = money_normalize(str_replace(['%', '٪'], '', tronado_setting('tronado_wage_percent')));
        return $v === null ? 0 : max(0, min(100, (int) round((float) $v)));
    }
    // One POST to Tronado. Always with a body ({} at the least): the guide
    // warns that a body-less POST is refused with 411, which looks like a 404.
    // TRONADO_API_BASE only exists for a test rig that stands in for Tronado.
    function tronado_request($path, array $body = [], $withKey = true)
    {
        $base = defined('TRONADO_API_BASE') ? rtrim((string) TRONADO_API_BASE, '/') : 'https://bot.tronado.cloud';
        $headers = ['Content-Type: application/json', 'Accept: application/json'];
        if ($withKey) {
            $headers[] = 'x-api-key: ' . tronado_setting('tronado_api_key');
        }
        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => $base . $path,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            // bounded: a customer is waiting on this tap
            CURLOPT_TIMEOUT => 20,
            CURLOPT_CUSTOMREQUEST => 'POST',
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_POSTFIELDS => empty($body) ? '{}' : json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
        ]);
        $response = curl_exec($curl);
        $error = $response === false ? curl_error($curl) : '';
        $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        curl_close($curl);
        $decoded = is_string($response) ? json_decode($response, true) : null;
        return [
            'http_code' => $httpCode,
            'body' => is_array($decoded) ? $decoded : null,
            'raw' => is_string($response) ? mb_substr($response, 0, 300) : '',
            'error' => $error,
        ];
    }
    // Tronado's price of one TRX in toman, or null when it cannot be read
    function tronado_price_toman()
    {
        $r = tronado_request('/Tron/GetPriceToToman', [], false);
        $price = (int) ($r['body']['TronPriceToman'] ?? 0);
        return $price > 0 ? $price : null;
    }
    // What the checkout asked Tronado for, kept in Payment_report's
    // dec_not_confirmed: "12.345678 TRX", plus ", wage 50%" when the shop took
    // on part of the fee. It is also the «توضیحات» line of the admin's payment
    // report, so it stays readable rather than JSON.
    function tronado_order_note($tron, $wage)
    {
        return number_format((float) $tron, 6, '.', '') . ' TRX' . ((int) $wage > 0 ? ', wage ' . (int) $wage . '%' : '');
    }
    function tronado_order_note_parse($note)
    {
        if (preg_match('/^\s*([0-9]+(?:\.[0-9]+)?)\s*TRX(?:,\s*wage\s*([0-9]{1,3})%)?/', (string) $note, $m)) {
            return ['tron' => (float) $m[1], 'wage' => isset($m[2]) ? (int) $m[2] : 0];
        }
        return null;
    }
    // Creates one Tronado order for a top-up of $price toman. Never retried:
    // a second GetOrderToken with the same PaymentID is not something the
    // guide promises to be safe.
    function createPayTronado($price, $order_id)
    {
        if (tronado_setting('tronado_api_key') === '' || tronado_setting('tronado_wallet') === '') {
            return ['ok' => false, 'error' => 'tronado: the API key or the TRX wallet is not set'];
        }
        $rate = tronado_price_toman();
        if ($rate === null) {
            return ['ok' => false, 'error' => 'tronado: could not read the TRX price (/Tron/GetPriceToToman)'];
        }
        // rounded UP to the sun (6 decimals): the TRX asked for is never worth
        // less than the toman the wallet is going to be credited with
        $tron = ceil(round((float) $price / $rate, 9) * 1000000) / 1000000;
        $wage = tronado_wage_percent();
        $r = tronado_request('/api/v5/GetOrderToken?wageFromBusinessPercentage=' . $wage, [
            'PaymentID' => (string) $order_id,
            'WalletAddress' => tronado_setting('tronado_wallet'),
            'TronAmount' => $tron,
            'CallbackUrl' => tronado_callback_url(),
        ]);
        $b = is_array($r['body']) ? $r['body'] : [];
        // the documented shape is flat; an older one wrapped it in Data
        $token = trim((string) ($b['Token'] ?? ($b['Data']['Token'] ?? '')));
        $errMsg = trim((string) ($b['ErrorMessage'] ?? ($b['Data']['ErrorMessage'] ?? '')));
        if ($r['http_code'] < 200 || $r['http_code'] >= 300 || $token === '' || $errMsg !== '') {
            if ($errMsg !== '') {
                // Tronado said why in its own words - that is the whole story
                return ['ok' => false, 'error' => 'tronado: ' . $errMsg];
            }
            return ['ok' => false, 'error' => 'tronado: ' . ($r['error'] !== '' ? $r['error'] : 'HTTP ' . $r['http_code']), 'raw' => $r['raw']];
        }
        $estimated = money_normalize((string) ($b['EstimatedTomanAmount'] ?? ($b['Data']['EstimatedTomanAmount'] ?? '')));
        return [
            'ok' => true,
            'token' => $token,
            // the link the guide says to put on the bot's own button
            'url' => 'https://t.me/tronado_robot/customerpayment?startapp=' . rawurlencode($token),
            'tron' => $tron,
            'wage' => $wage,
            'estimated' => $estimated === null ? null : (int) round((float) $estimated),
        ];
    }
    // Tronado's own word on an order, asked by this bot's PaymentID; null when
    // it could not be asked right now
    function tronado_order_status($paymentId)
    {
        $r = tronado_request('/Order/GetStatusByPaymentID', ['Id' => (string) $paymentId]);
        if ($r['http_code'] < 200 || $r['http_code'] >= 300 || !is_array($r['body'])) {
            return null;
        }
        return $r['body'];
    }
    // the guide's own test for a finished payment; a rejected (40) or
    // cancelled (200) order never counts, whatever else it says
    function tronado_is_paid(array $st)
    {
        $status = (int) ($st['OrderStatusID'] ?? 0);
        if ($status === 40 || $status === 200) {
            return false;
        }
        return ($st['IsPaid'] ?? false) === true || $status === 30;
    }
    function tronado_admin_alert($text, $topic = 'errorreport')
    {
        $setting = select("setting", "*", null, null, "select");
        if (strlen((string) ($setting['Channel_Report'] ?? '')) === 0) {
            return;
        }
        telegram('sendmessage', [
            'chat_id' => $setting['Channel_Report'],
            'message_thread_id' => select("topicid", "idreport", "report", $topic, "select")['idreport'] ?? null,
            'text' => $text,
            'parse_mode' => "HTML",
        ]);
    }
    // The one place a Tronado payment is credited, for the IPN and the cron
    // alike. $st is what Tronado's own API says about the order (never only
    // the IPN body); $ipn is the IPN body when there is one, for the toman
    // figures only it carries. Returns what happened, for the caller's log:
    // credited | already | unpaid | short | mismatch | failed
    function tronado_settle(array $row, array $st, array $ipn = [])
    {
        global $pdo;
        $textbotlang = lang_tab_texts('fa');
        $orderId = (string) $row['id_order'];
        $stPid = (string) ($st['PaymentID'] ?? ($st['PaymentId'] ?? ''));
        if ($stPid !== '' && $stPid !== $orderId) {
            error_log("tronado: status answer is for PaymentID={$stPid}, not order={$orderId}");
            return 'mismatch';
        }
        if (!tronado_is_paid($st)) {
            return 'unpaid';
        }
        // paid less than asked: an order Tronado adjusted down (TronAmount under
        // ActualTronAmount), or - when the customer carries the whole fee - less
        // TRX than the invoice asked for. Never credited as the full invoice:
        // the admin is told, once, and decides.
        $asked = tronado_order_note_parse($row['dec_not_confirmed'] ?? '');
        $got = (float) ($st['TronAmount'] ?? 0);
        $actual = (float) ($st['ActualTronAmount'] ?? 0);
        $short = $got <= 0
            || ($actual > 0 && $got < $actual * 0.99)
            || ($asked !== null && $asked['wage'] === 0 && $asked['tron'] > 0 && $got < $asked['tron'] * 0.99);
        if ($short) {
            $note = (string) ($row['dec_not_confirmed'] ?? '');
            // an ASCII marker in the row, so a repeated IPN or the next cron
            // run knows the admin has already been told (and the log, too)
            if (strpos($note, '| SHORT') === false) {
                error_log(sprintf('tronado: paid less than asked - order=%s asked=%s got=%s actual=%s', $orderId, $asked === null ? '?' : $asked['tron'], $got, $actual));
                update("Payment_report", "dec_not_confirmed", trim($note . ' | SHORT'), "id_order", $orderId);
                $user = select("user", "*", "id", $row['id_user'], "select");
                tronado_admin_alert(sprintf(
                    $textbotlang['hardcoded']['tronadoShortPayment'],
                    $orderId,
                    $row['id_user'],
                    $user['username'] ?? '-',
                    number_format((float) $row['price']),
                    $asked === null ? '—' : $asked['tron'],
                    $got,
                    htmlspecialchars((string) ($st['Hash'] ?? '-'))
                ));
            }
            return 'short';
        }
        // claim before crediting: only the call that flips the row goes on to
        // DirectPayment(), so a repeated IPN, the cron and an IPN at the same
        // moment can never credit twice. 'expire' counts too - the customer may
        // finish on Tronado's page after the bot closed the invoice, and a paid
        // order must not be left uncredited for it.
        $claim = $pdo->prepare("UPDATE Payment_report SET payment_Status = 'paid' WHERE id_order = ? AND payment_Status IN ('Unpaid', 'expire')");
        $claim->execute([$orderId]);
        if ($claim->rowCount() !== 1) {
            $now = (string) (select("Payment_report", "payment_Status", "id_order", $orderId, "select")['payment_Status'] ?? '');
            if ($now !== 'paid') {
                // rejected by an admin, or anything else that is not a repeat
                error_log("tronado: paid on Tronado but order={$orderId} is \"{$now}\" here");
                tronado_admin_alert(sprintf($textbotlang['hardcoded']['tronadoNotCredited'], $orderId, htmlspecialchars($now)));
            }
            return 'already';
        }
        $hash = trim((string) ($st['Hash'] ?? ($ipn['Hash'] ?? '')));
        if ($hash !== '') {
            // the hash is what Tronado's support asks for - it goes into the
            // admin's payment report («توضیحات») through DirectPayment()
            update("Payment_report", "dec_not_confirmed", trim((string) ($row['dec_not_confirmed'] ?? '')) . ' | ' . $hash, "id_order", $orderId);
        }
        try {
            DirectPayment($orderId, "../images.jpg");
        } catch (\Throwable $e) {
            // already 'paid': a later IPN or cron run cannot credit it twice -
            // nor finish it, so the admin is told exactly which order
            error_log("tronado: DirectPayment failed - order={$orderId}: " . $e->getMessage());
            tronado_admin_alert(sprintf($textbotlang['hardcoded']['tronadoCreditFailed'], $orderId, htmlspecialchars($e->getMessage())));
            return 'failed';
        }
        $user = select("user", "*", "id", $row['id_user'], "select");
        $cashback = (float) money_normalize(tronado_setting('chashbacktronado'));
        if ($cashback > 0 && is_array($user)) {
            $gift = ((float) $row['price'] * $cashback) / 100;
            // into the wallet the payment was made in, worded in the payer's language
            wallet_credit($user['id'], $gift, payment_currency($row));
            sendmessage($user['id'], sprintf(payer_texts($user['id'])['paymentGateway']['giftReport'], $gift), null, 'HTML');
        }
        $paidToman = (int) ($ipn['UserPaidTomanAmount'] ?? 0);
        tronado_admin_alert(sprintf(
            $textbotlang['hardcoded']['tronadoPaymentLog'],
            $row['id_user'],
            $user['username'] ?? '-',
            number_format((float) $row['price']),
            $paidToman > 0 ? number_format($paidToman) : '—',
            $got,
            $orderId,
            htmlspecialchars($hash !== '' ? $hash : '-')
        ), 'paymentreport');
        return 'credited';
    }
    // Tronado's optional Dispute Callback (a card holder's complaint that
    // Tronado accepted after the order was paid). The bot never takes money
    // back from a wallet by itself - it tells the admin what changed, once per
    // DisputeId (Tronado delivers at least once, so repeats are expected).
    function tronado_dispute_report(array $d)
    {
        $id = (string) ($d['DisputeId'] ?? '');
        if ($id === '') {
            return;
        }
        $seen = json_decode((string) getPaySettingValue('tronado_disputes_seen', '[]'), true);
        $seen = is_array($seen) ? $seen : [];
        if (in_array($id, $seen, true)) {
            return;
        }
        $seen[] = $id;
        pay_global_set('tronado_disputes_seen', json_encode(array_slice($seen, -300)));
        $textbotlang = lang_tab_texts('fa');
        $t = $textbotlang['hardcoded'];
        $orderId = (string) ($d['PaymentId'] ?? ($d['PaymentID'] ?? ''));
        $row = $orderId !== '' ? select("Payment_report", "*", "id_order", $orderId, "select") : null;
        $user = is_array($row) ? select("user", "*", "id", $row['id_user'], "select") : null;
        $outcome = (string) ($d['Outcome'] ?? '');
        $outcomeText = $t['tronadoDisputeOutcomes'][$outcome] ?? htmlspecialchars($outcome);
        tronado_admin_alert(sprintf(
            $t['tronadoDispute'],
            htmlspecialchars($orderId !== '' ? $orderId : '-'),
            is_array($row) ? $row['id_user'] : '-',
            htmlspecialchars((string) ($user['username'] ?? '-')),
            htmlspecialchars((string) ($d['DisputeTypeTitle'] ?? ($d['DisputeType'] ?? '-'))),
            $outcomeText,
            number_format((int) ($d['OriginalUserMustPayToman'] ?? 0)),
            (float) ($d['OriginalTronAmount'] ?? 0),
            number_format((int) ($d['UserMustPayToman'] ?? 0)),
            (float) ($d['TronAmount'] ?? 0),
            is_array($row) ? htmlspecialchars((string) $row['payment_Status']) : '-'
        ));
    }
}
// ---- درگاه ارزی ریالی هوش‌پی (HooshPay, API v1) ----
// A toman invoice the customer pays card to card on HooshPay's own page,
// confirmed there at once by the bank's SMS; the shop is settled in USDT.
// From HooshPay's guide (hooshpay.xyz/developers):
//   1. POST /api/v1/invoices         - order_id is this bot's id_order, and
//      callback_url travels with every invoice (nothing to register)
//   2. the customer pays on data.payment_url the exact payable_amount (a few
//      toman off the round figure, which is how HooshPay matches the SMS)
//   3. HooshPay POSTs payment.success to the callback, signed with
//      X-HooshPay-Signature (payment/hooshpay.php); cronbot/hooshpay.php asks
//      about the invoices whose callback never came. Both credit only through
//      hooshpay_settle(), and only once POST /invoices/{uid}/verify says paid.
if (!function_exists('hooshpay_callback_url')) {
    function hooshpay_callback_url()
    {
        global $domainhosts;
        return "https://{$domainhosts}/payment/hooshpay.php";
    }
    // a setting the admin never filled reads back as the row's default '0'
    function hooshpay_setting($name)
    {
        $v = trim((string) getPaySettingValue($name, ''));
        return $v === '0' ? '' : $v;
    }
    // who carries HooshPay's fee: seller (the shop), buyer (added to what the
    // customer pays) or split. Persian words are understood too; anything
    // else - or nothing - leaves it to the HooshPay account's own setting.
    function hooshpay_fee_mode()
    {
        $v = mb_strtolower(trim(hooshpay_setting('hooshpay_fee_mode')));
        $map = [
            'seller' => 'seller', 'فروشنده' => 'seller', 'فروشگاه' => 'seller',
            'buyer' => 'buyer', 'خریدار' => 'buyer', 'مشتری' => 'buyer',
            'split' => 'split', 'نصف' => 'split', 'نصف‌نصف' => 'split', 'نصف نصف' => 'split',
        ];
        return $map[$v] ?? null;
    }
    // One request to HooshPay. HOOSHPAY_API_BASE only exists for a test rig
    // that stands in for HooshPay.
    function hooshpay_request($method, $path, ?array $body = null)
    {
        $base = defined('HOOSHPAY_API_BASE') ? rtrim((string) HOOSHPAY_API_BASE, '/') : 'https://hooshpay.xyz';
        $curl = curl_init();
        $opts = [
            CURLOPT_URL => $base . '/api/v1' . $path,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            // bounded: a customer is waiting on this tap
            CURLOPT_TIMEOUT => 20,
            CURLOPT_CUSTOMREQUEST => $method,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json', 'X-API-KEY: ' . hooshpay_setting('hooshpay_api_key')],
        ];
        if ($method === 'POST') {
            // {} rather than [] for an empty body
            $opts[CURLOPT_POSTFIELDS] = empty($body) ? '{}' : json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        }
        curl_setopt_array($curl, $opts);
        $response = curl_exec($curl);
        $error = $response === false ? curl_error($curl) : '';
        $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        curl_close($curl);
        $decoded = is_string($response) ? json_decode($response, true) : null;
        return [
            'http_code' => $httpCode,
            'body' => is_array($decoded) ? $decoded : null,
            'raw' => is_string($response) ? mb_substr($response, 0, 300) : '',
            'error' => $error,
        ];
    }
    // why a call failed, in HooshPay's own words when it gave any
    function hooshpay_error_text(array $r)
    {
        $b = is_array($r['body']) ? $r['body'] : [];
        $msg = $b['detail'] ?? ($b['message'] ?? ($b['error'] ?? ''));
        if (is_array($msg)) {
            $msg = json_encode($msg, JSON_UNESCAPED_UNICODE);
        }
        $msg = trim((string) $msg);
        if ($msg !== '') {
            return 'HTTP ' . $r['http_code'] . ': ' . $msg;
        }
        return $r['error'] !== '' ? $r['error'] : 'HTTP ' . $r['http_code'] . ($r['raw'] !== '' ? ' — ' . $r['raw'] : '');
    }
    // Creates one HooshPay invoice for a top-up of $price toman. Never retried:
    // a second create would be a second invoice the customer could pay.
    function createPayHooshPay($price, $order_id)
    {
        if (hooshpay_setting('hooshpay_api_key') === '') {
            return ['ok' => false, 'error' => 'hooshpay: the API key is not set'];
        }
        $body = [
            'amount' => (int) round((float) $price),
            'order_id' => (string) $order_id,
            'description' => 'TopUp - ' . $order_id,
            'callback_url' => hooshpay_callback_url(),
        ];
        $feeMode = hooshpay_fee_mode();
        if ($feeMode !== null) {
            $body['fee_mode'] = $feeMode;
        }
        $r = hooshpay_request('POST', '/invoices', $body);
        $d = is_array($r['body']['data'] ?? null) ? $r['body']['data'] : [];
        $uid = trim((string) ($d['uid'] ?? ''));
        $url = trim((string) ($d['payment_url'] ?? ''));
        if ($r['http_code'] < 200 || $r['http_code'] >= 300 || empty($r['body']['success']) || $uid === '' || strpos($url, 'https://') !== 0) {
            return ['ok' => false, 'error' => 'hooshpay: ' . hooshpay_error_text($r)];
        }
        $payable = (int) ($d['payable_amount'] ?? 0);
        return [
            'ok' => true,
            'uid' => $uid,
            'url' => $url,
            'payable' => $payable > 0 ? $payable : null,
        ];
    }
    // HooshPay's own word on an invoice: GET for a look, POST .../verify for the
    // final answer before anything is credited. null when it could not be asked.
    function hooshpay_invoice_status($uid)
    {
        $r = hooshpay_request('GET', '/invoices/' . rawurlencode((string) $uid));
        return ($r['http_code'] >= 200 && $r['http_code'] < 300 && is_array($r['body'])) ? $r['body'] : null;
    }
    function hooshpay_invoice_verify($uid)
    {
        $r = hooshpay_request('POST', '/invoices/' . rawurlencode((string) $uid) . '/verify', []);
        return ($r['http_code'] >= 200 && $r['http_code'] < 300 && is_array($r['body'])) ? $r['body'] : null;
    }
    // X-HooshPay-Signature = hex(HMAC-SHA256(JSON of the body with its keys
    // sorted, unescaped unicode and slashes, secret)) - as the guide's PHP
    // sample builds it. The raw body and a fully sorted copy are accepted too,
    // so a nested field or another serializer on their side cannot lock a
    // real payment out. Compared in constant time.
    function hooshpay_signature_ok($rawBody, $signature, $secret)
    {
        $signature = strtolower(trim((string) $signature));
        if ($signature === '' || $secret === '') {
            return false;
        }
        $candidates = [(string) $rawBody];
        $payload = json_decode((string) $rawBody, true);
        if (is_array($payload)) {
            $top = $payload;
            ksort($top);
            $candidates[] = json_encode($top, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $deep = function ($v) use (&$deep) {
                if (!is_array($v)) {
                    return $v;
                }
                if (array_keys($v) !== range(0, count($v) - 1)) {
                    ksort($v);
                }
                return array_map($deep, $v);
            };
            $candidates[] = json_encode($deep($payload), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        }
        foreach (array_unique($candidates) as $c) {
            if (hash_equals(hash_hmac('sha256', $c, $secret), $signature)) {
                return true;
            }
        }
        return false;
    }
    function hooshpay_admin_alert($text, $topic = 'errorreport')
    {
        $setting = select("setting", "*", null, null, "select");
        if (strlen((string) ($setting['Channel_Report'] ?? '')) === 0) {
            return;
        }
        telegram('sendmessage', [
            'chat_id' => $setting['Channel_Report'],
            'message_thread_id' => select("topicid", "idreport", "report", $topic, "select")['idreport'] ?? null,
            'text' => $text,
            'parse_mode' => "HTML",
        ]);
    }
    // The one place a HooshPay payment is credited, for the callback and the
    // cron alike. $v is HooshPay's answer to POST /invoices/{uid}/verify -
    // never the callback body alone. Returns what happened, for the caller's
    // log: credited | already | unpaid | mismatch | failed
    function hooshpay_settle(array $row, array $v)
    {
        global $pdo;
        $textbotlang = lang_tab_texts('fa');
        $orderId = (string) $row['id_order'];
        $uid = trim(explode('|', (string) ($row['dec_not_confirmed'] ?? ''))[0]);
        $d = is_array($v['data'] ?? null) ? $v['data'] : [];
        if (($v['paid'] ?? false) !== true || (string) ($v['status'] ?? ($d['status'] ?? '')) !== 'paid') {
            return 'unpaid';
        }
        // the answer has to be about THIS invoice, for THIS amount. A
        // mismatch is never credited; the admin is told once (the row keeps
        // an ASCII marker so a resent callback or the next cron run stays quiet)
        $vUid = (string) ($d['uid'] ?? '');
        $vOrder = (string) ($d['order_id'] ?? '');
        $vAmount = $d['amount'] ?? null;
        $why = null;
        if ($vUid !== '' && $uid !== '' && $vUid !== $uid) {
            $why = "uid {$vUid} ≠ {$uid}";
        } elseif ($vOrder !== '' && $vOrder !== $orderId) {
            $why = "order_id {$vOrder} ≠ {$orderId}";
        } elseif ($vAmount !== null && (int) $vAmount !== (int) round((float) $row['price'])) {
            $why = 'amount ' . (int) $vAmount . ' ≠ ' . (int) round((float) $row['price']);
        }
        if ($why !== null) {
            $note = (string) ($row['dec_not_confirmed'] ?? '');
            if (strpos($note, '| MISMATCH') === false) {
                error_log("hooshpay: paid but {$why} - order={$orderId}");
                update("Payment_report", "dec_not_confirmed", trim($note . ' | MISMATCH'), "id_order", $orderId);
                hooshpay_admin_alert(sprintf($textbotlang['hardcoded']['hooshpayMismatch'], $orderId, htmlspecialchars($uid), htmlspecialchars($why)));
            }
            return 'mismatch';
        }
        // claim before crediting: only the call that flips the row goes on to
        // DirectPayment(), so a resent callback, the cron and a callback at the
        // same moment can never credit twice. 'expire' counts too - a payment
        // HooshPay confirms after the bot closed the invoice is still credited.
        $claim = $pdo->prepare("UPDATE Payment_report SET payment_Status = 'paid' WHERE id_order = ? AND payment_Status IN ('Unpaid', 'expire')");
        $claim->execute([$orderId]);
        if ($claim->rowCount() !== 1) {
            $now = (string) (select("Payment_report", "payment_Status", "id_order", $orderId, "select")['payment_Status'] ?? '');
            if ($now !== 'paid') {
                error_log("hooshpay: paid on HooshPay but order={$orderId} is \"{$now}\" here");
                hooshpay_admin_alert(sprintf($textbotlang['hardcoded']['hooshpayNotCredited'], $orderId, htmlspecialchars($now)));
            }
            return 'already';
        }
        $tracking = trim((string) ($d['tracking_code'] ?? ''));
        if ($tracking !== '') {
            // the tracking code is what HooshPay's support asks for - it goes
            // into the admin's payment report («توضیحات») through DirectPayment()
            update("Payment_report", "dec_not_confirmed", trim((string) ($row['dec_not_confirmed'] ?? '')) . ' | ' . $tracking, "id_order", $orderId);
        }
        try {
            DirectPayment($orderId, "../images.jpg");
        } catch (\Throwable $e) {
            // already 'paid': a later callback or cron run cannot credit it
            // twice - nor finish it, so the admin is told exactly which order
            error_log("hooshpay: DirectPayment failed - order={$orderId}: " . $e->getMessage());
            hooshpay_admin_alert(sprintf($textbotlang['hardcoded']['hooshpayCreditFailed'], $orderId, htmlspecialchars($e->getMessage())));
            return 'failed';
        }
        $user = select("user", "*", "id", $row['id_user'], "select");
        $cashback = (float) money_normalize(hooshpay_setting('chashbackhooshpay'));
        if ($cashback > 0 && is_array($user)) {
            $gift = ((float) $row['price'] * $cashback) / 100;
            // into the wallet the payment was made in, worded in the payer's language
            wallet_credit($user['id'], $gift, payment_currency($row));
            sendmessage($user['id'], sprintf(payer_texts($user['id'])['paymentGateway']['giftReport'], $gift), null, 'HTML');
        }
        $payable = (int) ($d['payable_amount'] ?? 0);
        hooshpay_admin_alert(sprintf(
            $textbotlang['hardcoded']['hooshpayPaymentLog'],
            $row['id_user'],
            $user['username'] ?? '-',
            number_format((float) $row['price']),
            $payable > 0 ? number_format($payable) : '—',
            $orderId,
            htmlspecialchars($uid !== '' ? $uid : '-'),
            htmlspecialchars($tracking !== '' ? $tracking : '-')
        ), 'paymentreport');
        return 'credited';
    }
}
function createPayaqayepardakht($price, $order_id)
{
    global $domainhosts;
    $merchant_aqayepardakht = select("PaySetting", "ValuePay", "NamePay", "merchant_id_aqayepardakht", "select")['ValuePay'];
    $curl = curl_init();
    curl_setopt_array($curl, array(
        CURLOPT_URL => 'https://panel.aqayepardakht.ir/api/v2/create',
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => '',
        CURLOPT_MAXREDIRS => 10,
        CURLOPT_TIMEOUT => 0,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_CUSTOMREQUEST => 'POST',
        CURLOPT_HTTPHEADER => array(
            'Content-Type: application/json',
            'Accept: application/json'
        ),
    ));
    curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode([
        'pin' => $merchant_aqayepardakht,
        'amount' => $price,
        'callback' => $domainhosts . "/payment/aqayepardakht.php",
        'invoice_id' => $order_id,
    ]));
    $response = curl_exec($curl);
    curl_close($curl);
    return json_decode($response, true);
}
function parseConfigs($input)
{
    $lines = explode("\n", $input);
    $configs = [];

    $currentName = null;
    $currentData = [];

    foreach ($lines as $line) {
        $line = trim($line);

        if (strpos($line, '#') === 0) {
            if ($currentName && $currentData) {
                $configs[] = [
                    'name' => $currentName,
                    'config' => implode("\n", $currentData)
                ];
            }
            $currentName = trim(substr($line, 1));
            $currentData = [];
        } else {
            if ($line !== '') {
                $currentData[] = $line;
            }
        }
    }
    if ($currentName && $currentData) {
        $configs[] = [
            'name' => $currentName,
            'config' => implode("\n", $currentData)
        ];
    }

    return $configs;
}

